/* ==== game.css ==== */
/* Dandy's Heroes - Dandy's World-style terminal panels: dark showroom
   hardware, thick plastic frames, bright inventory colors and Toon stickers. */
:root{
  --bg:#101416;
  --bg2:#202729;
  --panel:#2e3739;
  --panel2:#3e494a;
  --panel3:#171d1f;
  --rim:#b8c1bd;
  --rim-soft:#687474;
  --edge:#080b0c;
  --text:#ffffff;
  --dim:#c1cbc6;
  --accent:#a5f247;
  --accent2:#77da7f;
  --tape:#e8e2d4;
  --ichor:#c3cbcf;
  --star:#ffe27a;
  --ticket:#ffb0e0;
  --good:#7ce4a0;
  --bad:#ff7b7b;
  --wht:#f4f0ff; --grn:#6ee87f; --blu:#6cc4ff; --pur:#c99bff; --red:#ff7b7b;
  --safe-b: env(safe-area-inset-bottom, 0px);
}
*{box-sizing:border-box;margin:0;padding:0;-webkit-tap-highlight-color:transparent}
/* Several overlays below set an explicit `display`, which outranks the UA rule
   for the `hidden` attribute. Without this they can never actually be hidden. */
[hidden]{display:none !important}
html,body{height:100%}
/* Opt-in safety mode. The JS side suppresses battle flashes, camera jolts,
   zoom punches, hitstop, and screen tints; this CSS pass covers authored DOM
   animations across menus and decorative battle VFX that do not use FX's
   central helpers. Damage/status text remains visible and readable. */
html.accessibility-reduced-effects *,
html.accessibility-reduced-effects *::before,
html.accessibility-reduced-effects *::after{
  animation-duration:.001ms!important;
  animation-iteration-count:1!important;
  transition-duration:.001ms!important;
  scroll-behavior:auto!important;
}
html.accessibility-reduced-effects #flash{display:none!important}
html.accessibility-reduced-effects #fxBack,
html.accessibility-reduced-effects #fxFront{visibility:hidden!important}
html:not(.accessibility-reduced-effects) #fxBack,
html:not(.accessibility-reduced-effects) #fxFront{visibility:visible}

/* Optional user-controlled battle performance mode. The simulation keeps its
   normal clock; this only removes compositor-heavy decoration and filters. */
html.graphics-low #stage:after,
html.graphics-low #bgLayer:before,
html.graphics-low #floorLine:before{display:none!important}
html.graphics-lite #bgLayer{filter:none!important}
html.graphics-lite #vignette,
html.graphics-lite .unit .shadow{display:none!important}
html.graphics-lite .unit .body img,
html.graphics-lite .unit .nameplate,
html.graphics-lite .unit .status-chip,
html.graphics-lite .unit .stats,
html.graphics-lite #fxBack .p,
html.graphics-lite #fxFront .p,
html.graphics-lite #popLayer .pop{filter:none!important;box-shadow:none!important;text-shadow:none!important}
html.graphics-lite .unit .body,
html.graphics-lite .unit-loadout,
html.graphics-lite .unit .stats{filter:none!important}
html.graphics-lite .unit.boss .body:before,
html.graphics-lite .unit.elite .body:before,
html.graphics-lite .unit.casting .body:before,
html.graphics-lite .unit.hurt .body:after,
html.graphics-lite .unit .barnaby-companion{animation:none!important}
html.graphics-lite .unit .hpmini.low,
html.graphics-lite .unitcard.ult-ready .uc-port{animation:none!important}
body{
  background:var(--bg); color:var(--text);
  font:700 14px/1.35 "Trebuchet MS","Arial Black","Verdana",system-ui,sans-serif;
  overflow:hidden; user-select:none;
}
button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}
img{display:block}
::-webkit-scrollbar{width:7px;height:7px}
::-webkit-scrollbar-track{background:#0e1013;border-radius:4px}
::-webkit-scrollbar-thumb{background:var(--rim-soft);border-radius:4px;border:1px solid var(--edge)}

/* ---------- the signature outlined text ---------- */
.ink,.tb-name,.endtitle,.boot-logo,h2.sec,.floor .fnum,#waveInfo{
  -webkit-text-stroke:4px var(--edge);
  paint-order:stroke fill;
}
.ink-s{-webkit-text-stroke:3px var(--edge);paint-order:stroke fill}

/* ---------- boot ---------- */
#boot{position:fixed;inset:0;z-index:900;display:grid;place-items:center;
  background:repeating-linear-gradient(0deg,#101516 0 3px,#151c1d 3px 7px),radial-gradient(circle at 50% 38%,#35433e,#101516 72%)}
.boot-inner{text-align:center;width:min(82vw,430px)}
.boot-logo{font:900 clamp(30px,10vw,58px)/0.95 "Arial Black","Verdana",sans-serif;letter-spacing:-2px;
  color:#f8f9f2;text-shadow:0 5px 0 #0b0e0f,0 0 0 4px #0b0e0f}
.boot-logo span{display:block;color:var(--accent)}
#boot.done{opacity:0;pointer-events:none;transition:opacity .45s}

/* Reusable asset gate for battle and animation-heavy views. It reports real
   image decode progress; cached bundles pass through without an artificial
   countdown, while cold loads keep unfinished sprites off the stage. */
#loadScreen{position:fixed;inset:0;z-index:890;display:grid;place-items:center;overflow:hidden;padding:22px;background:radial-gradient(ellipse at 50% 37%,#6a9b60 0,#315844 34%,#17392f 68%,#10241f 100%);opacity:0;pointer-events:auto;transition:opacity .22s ease}
#loadScreen[hidden]{display:none}#loadScreen.visible{opacity:1}
.load-curtain{position:absolute;top:-8%;bottom:-8%;width:clamp(38px,10vw,112px);background:repeating-linear-gradient(90deg,#8b3e38 0 12px,#a34c40 12px 24px,#77332f 24px 30px);border:4px solid #552d29;box-shadow:inset -9px 0 0 #ffffff12,0 0 22px #07130f88;z-index:0;pointer-events:none}.load-curtain-left{left:-18px;border-radius:0 0 52% 0;transform:rotate(2deg)}.load-curtain-right{right:-18px;border-radius:0 0 0 52%;transform:rotate(-2deg)}
.load-stage-stars{position:absolute;inset:0;overflow:hidden;pointer-events:none}.load-stage-stars i{position:absolute;color:#ffdb72;font-style:normal;text-shadow:0 2px #9b6131;animation:loadStar 2.2s ease-in-out infinite}.load-stage-stars i:nth-child(1){top:18%;left:23%;font-size:24px}.load-stage-stars i:nth-child(2){top:24%;right:21%;font-size:17px;animation-delay:-.7s}.load-stage-stars i:nth-child(3){bottom:24%;left:18%;font-size:30px;animation-delay:-1.2s}.load-stage-stars i:nth-child(4){bottom:20%;right:20%;font-size:22px;animation-delay:-1.7s}
.load-screen-inner{position:relative;z-index:1;width:min(82vw,460px);padding:19px 22px 16px;text-align:center;border:4px solid #563d2b;border-radius:25px;background:linear-gradient(160deg,#fff3c9,#f4d991 72%,#e4ba69);box-shadow:0 8px 0 #4a3425,0 18px 40px #07130f99,inset 0 3px #fff9;transform:translateY(14px) scale(.97);transition:transform .3s cubic-bezier(.2,.9,.25,1.3)}#loadScreen.visible .load-screen-inner{transform:translateY(0) scale(1)}
.load-mascot{position:absolute;right:-20px;top:-51px;width:91px;height:75px;pointer-events:none}.load-mascot img{width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 4px 2px #543c27);animation:loadDandyPeek 1.8s ease-in-out infinite}.load-mascot span{position:absolute;right:60px;top:4px;white-space:nowrap;padding:5px 8px;border:2px solid #583e29;border-radius:12px;background:#fff8db;color:#493525;font-size:7px;font-weight:1000;letter-spacing:.5px;box-shadow:0 2px #583e29;transform:rotate(-5deg)}
.load-screen-kicker{color:#577b40;font-size:8px;font-weight:1000;letter-spacing:2.3px}.load-screen-title{margin-top:5px;color:#fff8dc;font:1000 clamp(21px,6vw,34px)/1 "Arial Black",sans-serif;-webkit-text-stroke:3px #65452d;paint-order:stroke fill;text-shadow:0 4px #65452d,0 6px #382c21;transform:rotate(-1deg)}.load-screen-cast{display:flex;align-items:end;justify-content:center;min-height:115px;margin:9px 0 3px}.load-screen-cast img{width:clamp(43px,15vw,76px);height:106px;margin:0 -5px;object-fit:contain;filter:saturate(1.08) contrast(1.05) drop-shadow(0 5px 2px #573c2777);animation:loadCastBob 1.05s cubic-bezier(.45,0,.55,1) infinite;animation-delay:calc(var(--load-i,0) * -.14s)}
.load-screen-bar{height:19px;overflow:hidden;border:3px solid #553c2b;border-radius:99px;background:#b99054;box-shadow:inset 0 2px 3px #563e2955,0 3px #7d5635}.load-screen-bar i{position:relative;display:block;width:0;height:100%;border-radius:99px;background:linear-gradient(90deg,#5cae4b,#9bdc5f 52%,#f5d35f);box-shadow:inset 0 2px #ffffffaa;transition:width .13s ease-out}.load-screen-bar i:after{content:"";position:absolute;inset:0;background:repeating-linear-gradient(135deg,#ffffff30 0 7px,transparent 7px 14px);animation:loadStripe .65s linear infinite}.load-screen-row{display:flex;justify-content:space-between;margin-top:10px;color:#60452f;font-size:8px;font-weight:1000;letter-spacing:.5px}.load-screen-row b{color:#4b3828;font-size:10px}.load-screen-count{min-height:11px;margin-top:6px;color:#84633f;font-size:7px;font-weight:900;letter-spacing:.6px;text-transform:uppercase}
@keyframes loadCastBob{0%,100%{transform:translateY(4px) rotate(-2deg)}50%{transform:translateY(-9px) rotate(2deg)}}@keyframes loadDandyPeek{0%,100%{transform:translateY(2px) rotate(-3deg)}50%{transform:translateY(-5px) rotate(4deg)}}@keyframes loadStar{0%,100%{opacity:.5;transform:scale(.75) rotate(-12deg)}50%{opacity:1;transform:scale(1.12) rotate(14deg)}}@keyframes loadStripe{to{transform:translateX(14px)}}
@media(max-width:380px){.load-screen-inner{padding:17px 15px 14px}.load-screen-cast img{width:clamp(40px,14vw,54px);height:94px;margin:0 -4px}.load-mascot{right:-9px;top:-44px;width:75px;height:64px}.load-mascot span{right:49px;font-size:6px}}
@media(prefers-reduced-motion:reduce){#loadScreen,#loadScreen *{animation-duration:.01ms!important;animation-iteration-count:1!important;scroll-behavior:auto!important;transition-duration:.01ms!important}}

/* ---------- app frame ---------- */
#app{position:fixed;inset:0;display:flex;flex-direction:column;
  max-width:560px;margin:0 auto;
  background:
    repeating-linear-gradient(90deg,rgba(255,255,255,.025) 0 1px,transparent 1px 22px),
    repeating-linear-gradient(0deg,rgba(0,0,0,.12) 0 2px,transparent 2px 7px),linear-gradient(180deg,#293234,var(--bg2));
  box-shadow:0 0 0 3px var(--edge),0 0 60px #000}
#topbar{flex:0 0 auto;display:flex;align-items:center;justify-content:space-between;
  gap:8px;padding:7px 9px;background:linear-gradient(180deg,#151b1c,#242d2e);
  border-bottom:3px solid #080b0c;box-shadow:inset 0 -2px #65716d,inset 0 2px rgba(255,255,255,.12)}
.tb-left{display:flex;align-items:center;gap:9px;min-width:0}
.tb-lvl{display:grid;place-items:center;width:42px;height:42px;border-radius:9px;
  background:linear-gradient(180deg,#586662,#273233);
  border:3px solid #080b0c;line-height:1;
  box-shadow:inset 0 2px #aab7b166,0 3px 0 #080b0c}
.tb-lvl span{font-weight:900;color:var(--accent);font-size:17px;
  -webkit-text-stroke:3px var(--edge);paint-order:stroke fill}
.tb-lvl small{font-size:6px;letter-spacing:.5px;color:var(--dim)}
.tb-name{font-weight:900;letter-spacing:.5px;font-size:14px;color:#fff}
.account-btn{display:flex;align-items:center;gap:6px;min-width:0;padding:3px 7px 3px 3px;border:2px solid #090d0e;border-radius:99px;color:#fff;background:linear-gradient(180deg,#465352,#252d2e);box-shadow:inset 0 1px #ffffff22,0 2px #080b0c}.account-avatar{display:grid;place-items:center;width:27px;height:27px;overflow:hidden;border-radius:50%;background:#151a1c;font-size:14px}.account-avatar img{width:100%;height:100%;object-fit:cover}.account-label{max-width:92px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px;font-weight:900}.account-btn:active{transform:translateY(2px);box-shadow:none}
.tb-right{display:flex;gap:5px;flex-wrap:wrap;justify-content:flex-end}
.res{display:flex;align-items:center;gap:4px;
  background:linear-gradient(180deg,#3d4948,#222a2b);
  border:2px solid #090d0e;border-radius:7px;padding:3px 7px 3px 5px;
  font-size:11px;font-weight:900;
  box-shadow:inset 0 2px 0 rgba(255,255,255,.14)}
.res i{font-style:normal;font-size:13px}.currency-icon{display:inline-block;width:1em;height:1em;object-fit:contain;vertical-align:-.13em}.res .currency-icon{width:16px;height:16px;vertical-align:-.2em;filter:drop-shadow(0 1px 1px #000)}.res .ichor-icon{width:13px;height:13px}
.res span{-webkit-text-stroke:2.5px var(--edge);paint-order:stroke fill}
.res[data-res=ichor] span{color:var(--ichor)}
.res[data-res=tape] span{color:var(--tape)}
.res[data-res=notes] span{color:#d5a7ff}.res[data-res=notes] i{color:#d5a7ff;text-shadow:0 0 7px #a96bdf}
.res[data-res=star] span{color:var(--star)}
.res[data-res=ticket] span{color:var(--ticket)}
.res[data-res=raidTicket] span{color:#f6d35f}.res[data-res=raidTicket] i{color:#f6d35f;text-shadow:0 0 7px #f6d35f66}
.res[data-res=counterToken] span{color:#7dd3fc}.res[data-res=counterToken] i{color:#7dd3fc;text-shadow:0 0 7px #38bdf866}
.res.bump{animation:resBump .4s cubic-bezier(.2,1.6,.4,1)}
@keyframes resBump{0%{transform:scale(1)}40%{transform:scale(1.28) rotate(-4deg)}100%{transform:scale(1)}}

#screen{flex:1 1 auto;overflow-y:auto;overflow-x:hidden;padding:10px 10px 18px;
  scrollbar-width:thin}
/* menu content pops in, staggered, like stickers being placed */
#screen>*{animation:cardIn .32s cubic-bezier(.2,1.5,.4,1) backwards}
#screen>*:nth-child(1){animation-delay:.00s}
#screen>*:nth-child(2){animation-delay:.04s}
#screen>*:nth-child(3){animation-delay:.08s}
#screen>*:nth-child(4){animation-delay:.12s}
#screen>*:nth-child(5){animation-delay:.16s}
#screen>*:nth-child(6){animation-delay:.20s}
#screen>*:nth-child(7){animation-delay:.24s}
#screen>*:nth-child(n+8){animation-delay:.28s}
@keyframes cardIn{from{opacity:0;transform:translateY(16px) scale(.94)}}

/* ---------- nav: chunky circular slots ---------- */
#navbar{flex:0 0 auto;display:grid;grid-template-columns:repeat(6,1fr);gap:4px;
  padding:7px 6px calc(7px + var(--safe-b));
  background:linear-gradient(180deg,#111617,#263031);border-top:3px solid #080b0c;box-shadow:inset 0 2px #5e6b6766}
#navbar button{display:grid;place-items:center;gap:2px;padding:4px 0;color:var(--dim);
  transition:transform .12s}
#navbar button i{font-style:normal;font-size:18px;line-height:1;
  width:40px;height:40px;display:grid;place-items:center;border-radius:10px;
  background:linear-gradient(180deg,#4b5856,#2c3536);
  border:3px solid #080b0c;
  box-shadow:inset 0 2px #e4fff21f,0 3px 0 #080b0c;
  transition:transform .14s,background .14s}
#navbar button span{display:flex;align-items:center;flex-direction:column;font-size:9px;font-weight:900;line-height:1;letter-spacing:.3px;
  -webkit-text-stroke:2.5px var(--edge);paint-order:stroke fill}
#navbar button span b{font-size:inherit;font-weight:900}
#navbar button span small{margin-top:2px;color:#aebbb5;font-size:6px;font-weight:900;letter-spacing:.4px;text-transform:uppercase;-webkit-text-stroke:1.5px var(--edge)}
#navbar button:active i{transform:translateY(3px);box-shadow:inset 0 2px 0 rgba(255,255,255,.16),0 0 0 rgba(0,0,0,.4)}
#navbar button.on{color:#fff}
#navbar button.on i{background:linear-gradient(180deg,#c9fb5b,#55ae57);
  transform:translateY(-4px) scale(1.06)}
#navbar .nav-main i{width:52px;height:52px;font-size:23px}

/* ---------- panels ---------- */
h2.sec{font-size:12px;letter-spacing:1.5px;color:#fff;margin:15px 3px 8px;font-weight:900}
h2.sec:first-child{margin-top:3px}
.card{background:linear-gradient(180deg,#465151,#2a3334);
  border:3px solid #090d0e;border-radius:11px;padding:12px;margin-bottom:10px;
  position:relative;overflow:hidden;
  box-shadow:inset 0 2px #eafff01f,0 4px 0 #111617}
.card:before{content:"";position:absolute;inset:3px;border-radius:7px;border:1px solid #d8f3e022;pointer-events:none}
.card.tap{cursor:pointer;transition:transform .1s,box-shadow .1s}.card.tap:active{transform:translateY(4px);box-shadow:inset 0 2px #eafff01f,0 0 0 #111617}
.row{display:flex;align-items:center;gap:10px}
.grow{flex:1 1 auto;min-width:0}
.muted{color:var(--dim)}
.tiny{font-size:11px}
.mini{font-size:10px}
.b{font-weight:900}
.center{text-align:center}
.spacer{height:8px}

/* ---------- buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;
  padding:9px 16px;border-radius:14px;font-weight:900;font-size:13px;color:#fff;
  background:linear-gradient(180deg,#637270,#374344);
  border:3px solid #080b0c;
  box-shadow:inset 0 2px #f1fff533,0 4px 0 #101415;
  -webkit-text-stroke:3px var(--edge);paint-order:stroke fill;
  transition:transform .07s,box-shadow .07s}
.btn:active{transform:translateY(4px);box-shadow:inset 0 2px 0 rgba(255,255,255,.20),0 0 0 rgba(0,0,0,.42)}
.btn.pri{background:linear-gradient(180deg,#ff8f90,#cf4b5b)}
.btn.go{background:linear-gradient(180deg,#b8fa5d,#5fc35b)}
.btn.gold{background:linear-gradient(180deg,#c3f65d,#63b956)}
.btn.wide{width:100%}
.btn[disabled]{opacity:.45;pointer-events:none;filter:saturate(.4)}
.btn.tiny{padding:6px 11px;font-size:11px;border-radius:11px;border-width:3px}
.pill{display:inline-block;padding:3px 9px;border-radius:7px;font-size:10px;font-weight:900;
  background:linear-gradient(180deg,#52615e,#303a3b);border:2px solid #080b0c;box-shadow:inset 0 1px #fff2}
.bar{height:14px;border-radius:7px;background:#111617;overflow:hidden;
  border:3px solid #080b0c;box-shadow:inset 0 2px #0008}
.bar>i{display:block;height:100%;border-radius:99px;transition:width .35s cubic-bezier(.2,1.2,.4,1);
  box-shadow:inset 0 2px 0 rgba(255,255,255,.35)}

/* ---------- Event Board: an illustrated stack of selectable encounters ---------- */
.event-raid{position:relative;min-height:100%;margin:-10px -10px -18px;padding:10px 10px 22px;overflow:hidden;
  background:radial-gradient(ellipse at 20% 5%,#b9ddff 0%,#6da9ef 26%,#4878c7 65%,#273e82 100%)}
.event-raid:before,.event-raid:after{content:"";position:absolute;pointer-events:none;filter:blur(1px);opacity:.48}
.event-raid:before{width:260px;height:86px;top:96px;left:-70px;background:radial-gradient(ellipse,#fff 0 20%,transparent 65%)}
.event-raid:after{width:260px;height:96px;top:310px;right:-120px;background:radial-gradient(ellipse,#d7efff 0 18%,transparent 66%)}
.event-ribbon{position:relative;z-index:1;display:flex;align-items:center;justify-content:center;gap:12px;min-height:48px;
  clip-path:polygon(0 50%,7% 0,93% 0,100% 50%,93% 100%,7% 100%);
  color:#262c38;background:linear-gradient(135deg,#777f8b,#ecf0f2 22%,#9ca5b0 45%,#f5f7fa 66%,#6d7581);
  border:2px solid #252a31;box-shadow:0 3px 0 #172237,0 6px 14px #18356799;text-shadow:0 1px #fff}
.event-ribbon:before{content:"";position:absolute;inset:5px 28px;border:1px solid #59616e;clip-path:inherit;opacity:.8}
.event-ribbon div{position:relative;text-align:center;line-height:1;letter-spacing:.8px}.event-ribbon b{display:block;font-size:18px;font-weight:900}.event-ribbon small{font-size:7px;font-weight:900;letter-spacing:1.7px}
.event-ribbon-gem{position:relative;color:#d4992e;font-size:20px;text-shadow:0 1px #fff}
.event-window{position:relative;z-index:1;margin:4px 7px 10px;padding:3px 7px;color:#fff;font-size:10px;font-weight:900;letter-spacing:.25px;
  background:#101928e8;border-left:2px solid #d2e8ff;border-bottom:2px solid #d2e8ff;text-shadow:0 2px 2px #000}
.event-list{position:relative;z-index:1;display:grid;gap:8px}
.event-banner{position:relative;height:100px;width:100%;overflow:hidden;text-align:left;color:#fff;border:3px solid #2d1c10;border-radius:14px;
  background:linear-gradient(105deg,hsl(var(--event-hue) 75% 25%),hsl(var(--event-hue) 72% 47%) 42%,hsl(calc(var(--event-hue) + 25) 75% 28%));
  box-shadow:inset 0 0 0 2px #f9dc7b,inset 0 0 0 5px #6b3c1a,0 4px 0 #18223f,0 7px 13px #18356777;
  transition:transform .12s,filter .12s}
.event-banner:before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(135deg,rgba(255,255,255,.12) 0 4px,transparent 4px 13px),radial-gradient(circle at 12% 15%,#fff9 0 1px,transparent 2px);mix-blend-mode:screen;opacity:.65}
.event-banner:active{transform:translateY(3px);box-shadow:inset 0 0 0 2px #f9dc7b,inset 0 0 0 5px #6b3c1a,0 1px 0 #18223f}.event-banner.selected{filter:brightness(1.16) saturate(1.14);outline:3px solid #fff3a6;outline-offset:2px}
.event-sheen{position:absolute;inset:-20% 45% -20% -30%;background:linear-gradient(105deg,transparent 30%,#fff5 48%,transparent 62%);transform:skewX(-17deg)}
.event-crest{position:absolute;z-index:3;top:5px;left:5px;width:29px;height:29px;border-radius:50%;display:grid;place-items:center;color:#7a4a17;font-size:19px;
  background:radial-gradient(circle at 33% 28%,#fff6b3,#c78926 64%,#734012);border:2px solid #2d1c10;box-shadow:0 2px 0 #392007;text-shadow:0 1px #ffeac1}
.event-art{position:absolute;z-index:2;right:4px;bottom:2px;width:47%;height:88px;display:flex;justify-content:flex-end;align-items:end}.event-art img{position:relative;height:92px;max-width:78%;object-fit:contain;filter:drop-shadow(0 3px 2px #0009) drop-shadow(0 0 7px #fff5)}.event-art img+img{margin-left:-19px}
