/* ---------- hero tile: sticker card ---------- */
.htile{position:relative;border-radius:16px;overflow:hidden;
  background:linear-gradient(180deg,#4a515b,#2f343b);
  border:3px solid var(--edge);
  box-shadow:inset 0 2px 0 rgba(255,255,255,.16),0 4px 0 rgba(0,0,0,.36);
  aspect-ratio:3/4;display:flex;flex-direction:column;justify-content:flex-end;
  cursor:pointer;transition:transform .12s}
.htile:active{transform:translateY(4px) scale(.97);box-shadow:inset 0 2px 0 rgba(255,255,255,.16),0 0 0 rgba(0,0,0,.36)}
.htile.locked{filter:grayscale(1) brightness(.45)}
.htile .por{position:absolute;inset:0 0 15px;display:grid;place-items:center;padding:6px}
.htile .por img{max-width:100%;max-height:100%;object-fit:contain;
  filter:saturate(1.1) contrast(1.05)
    drop-shadow(0 0 1.5px rgba(0,0,0,.45))
    drop-shadow(0 -1px 0 rgba(255,255,255,.22))
    drop-shadow(0 4px 5px rgba(0,0,0,.6))}
.htile .nm{position:relative;font-size:10px;font-weight:900;text-align:center;
  background:linear-gradient(transparent,rgba(10,12,15,.94) 45%);padding:13px 2px 3px;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
  -webkit-text-stroke:2.5px var(--edge);paint-order:stroke fill}
.htile .lv{position:absolute;top:4px;left:4px;font-size:10px;font-weight:900;
  background:linear-gradient(180deg,#4c535e,#2c3138);border:2px solid var(--edge);
  border-radius:8px;padding:0 5px;z-index:2}
.htile .stars{position:absolute;bottom:15px;left:0;right:0;text-align:center;font-size:9px;
  letter-spacing:-1px;color:var(--star);z-index:2;
  -webkit-text-stroke:2px var(--edge);paint-order:stroke fill}
.htile .rar{position:absolute;top:5px;right:5px;width:12px;height:12px;border-radius:50%;
  border:2px solid var(--edge);z-index:2}
.htile .rar-label{position:absolute;top:35px;right:3px;z-index:2;max-width:70%;padding:1px 3px;border:1px solid var(--edge);border-radius:4px;color:#fff;background:#101516c9;font-size:6px;font-weight:1000;line-height:1;white-space:nowrap}
.htile .obt{position:absolute;top:20px;right:3px;font-size:11px;z-index:2;
  filter:drop-shadow(0 1px 1px #000)}
.htile.locked .obt{filter:none}
.htile.locked .por img{filter:brightness(0)}
.lock-q{position:absolute;inset:0;display:grid;place-items:center;color:#fff;font-size:20px;font-weight:900;letter-spacing:1px;text-shadow:0 2px 3px #000}
.htile .shd{position:absolute;bottom:15px;right:4px;font-size:9px;font-weight:900;
  color:var(--tape);background:#0e1013cc;border:2px solid var(--edge);
  border-radius:7px;padding:0 4px;z-index:2}

/* ---------- floors ---------- */
.floor{display:flex;align-items:center;gap:10px;padding:10px;border-radius:14px;
  background:linear-gradient(180deg,var(--panel2),var(--panel));
  border:3px solid var(--edge);margin-bottom:8px}
.floor .fnum{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;
  font-weight:900;background:#191c21;border:3px solid var(--edge);flex:0 0 auto;font-size:16px}
.node{display:flex;flex-direction:column;align-items:center;gap:3px;padding:9px 4px;
  border-radius:14px;border:3px solid var(--edge);
  background:linear-gradient(180deg,#4a515b,#31363d);min-width:0;
  box-shadow:inset 0 2px 0 rgba(255,255,255,.15),0 4px 0 rgba(0,0,0,.34);
  transition:transform .12s}
.node:active{transform:translateY(4px);box-shadow:inset 0 2px 0 rgba(255,255,255,.15),0 0 0 rgba(0,0,0,.34)}
.node .ic{font-size:23px;line-height:1;filter:drop-shadow(0 2px 2px rgba(0,0,0,.5))}
.node .lb{font-size:9px;font-weight:900;letter-spacing:.3px;
  -webkit-text-stroke:2.5px var(--edge);paint-order:stroke fill}
.node.done{opacity:.4;filter:grayscale(.6)}
.node.next{border-color:var(--accent);animation:nodePulse 1.3s infinite}
@keyframes nodePulse{
  0%,100%{box-shadow:inset 0 2px 0 rgba(255,255,255,.15),0 4px 0 rgba(0,0,0,.34),0 0 0 0 rgba(255,210,63,.55)}
  55%{box-shadow:inset 0 2px 0 rgba(255,255,255,.15),0 4px 0 rgba(0,0,0,.34),0 0 0 9px rgba(255,210,63,0)}}

/* ---------- battle ---------- */
/* Same phone-frame sizing as #app: a fixed-width column on wide screens
   instead of stretching edge-to-edge, so launching a battle doesn't suddenly
   change the app's apparent size. */
#battle{position:fixed;inset:0;z-index:500;background:#000;overflow:hidden;
  max-width:560px;margin:0 auto;box-shadow:0 0 0 3px var(--edge),0 0 60px #000}
#stage{position:absolute;inset:0;transform-origin:50% 60%;will-change:transform;background:#091016}
#stage:after{content:"";position:absolute;z-index:8;inset:0;pointer-events:none;border:1px solid #d9eef01a;
  background:linear-gradient(115deg,transparent 0 44%,#bde8f008 49%,#bde8f016 50%,transparent 56%),
    repeating-linear-gradient(0deg,transparent 0 7px,#d8f5f20a 8px 9px);
  mix-blend-mode:screen;opacity:.42;animation:battleScan 8s linear infinite}
#bgLayer{position:absolute;inset:-6%;background-size:cover;background-position:center;
  filter:brightness(.54) saturate(.92) contrast(1.08);overflow:hidden}
/* Treat the supplied floor art as a distant set piece. The layered light
   bands, ceiling haze, and side colors make every floor feel like an actual
   room with a horizon instead of a flat image behind the units. */
#bgLayer:before{content:"";position:absolute;inset:0;
  background:
    radial-gradient(ellipse at 50% 47%,#f6dc9c2e 0 4%,#f6dc9c12 15%,transparent 40%),
    radial-gradient(ellipse at 50% 68%,#6bb8c41d 0 8%,transparent 37%),
    radial-gradient(circle at 8% 43%,#6dc9e41a,transparent 27%),
    radial-gradient(circle at 92% 43%,#e9777d1a,transparent 27%),
    linear-gradient(180deg,#07141ce0 0 12%,transparent 31%,#0b111985 56%,#05080de6 78%);
  mix-blend-mode:screen;animation:battleAtmosphere 11s ease-in-out infinite alternate;pointer-events:none}
#bgLayer:after{content:"";position:absolute;inset:0;
  background:
    linear-gradient(180deg,#02070b38 0 21%,transparent 36%,#05090ed0 63%,#020407f4 100%),
    linear-gradient(90deg,#03121c62,transparent 20% 80%,#190c1462),
    radial-gradient(ellipse at 50% 50%,transparent 0 43%,#0204079e 100%);
  box-shadow:inset 0 0 100px #010305cc}
/* The walkable depth range is a visible perspective plane. Its top edge is
   positioned from Battle.ground and Battle.depthSpan, so every unit's feet
   remain inside the surface while moving toward or away from the camera. */
#floorLine{position:absolute;left:0;right:0;height:120px;bottom:0;pointer-events:none;
  overflow:hidden;border-top:3px solid #b9e1d858;
  background:
    radial-gradient(ellipse at 50% 2%,#f6dd9c46 0 4%,#f6dd9c13 13%,transparent 34%),
    linear-gradient(90deg,#09202b3d 0 12%,transparent 31% 69%,#2815213d 88% 100%),
    repeating-linear-gradient(0deg,transparent 0 31px,#b7d7d514 32px 34px),
    linear-gradient(180deg,#1b333ba8 0%,#0c1a21e8 35%,#05090f 100%);
  box-shadow:inset 0 18px 34px #d3f5ed16,inset 0 -40px 60px #010305b8,0 -8px 35px #78ced626}
#floorLine:before{content:"";display:block;position:absolute;inset:-12% -28% -8%;
  background:
    repeating-linear-gradient(90deg,transparent 0 10.4%,#b8e2db1a 10.55% 10.72%),
    repeating-linear-gradient(0deg,transparent 0 31px,#b8e2db1a 32px 34px),
    linear-gradient(90deg,transparent 0 49.6%,#f4d88b28 49.8% 50.2%,transparent 50.4% 100%);
  transform:perspective(500px) rotateX(62deg) scaleX(1.42);transform-origin:50% 0;opacity:.9}
#floorLine:after{content:"";position:absolute;inset:0;
  background:
    linear-gradient(90deg,transparent 0 12%,#76d9dc17 12.2% 12.45%,transparent 12.7% 87.3%,#f08a8d17 87.55% 87.8%,transparent 88%),
    radial-gradient(ellipse at 50% 26%,transparent 0 31%,#01030630 63%,#010306d9 100%);
  border-top:1px solid #f6dfaa2a}
#fxBack,#fxFront,#unitLayer,#popLayer{position:absolute;inset:0;pointer-events:none}
/* Explicit stacking order for the battle stage layers. #unitLayer needs its
   own z-index so it becomes a contained stacking context - otherwise the
   per-unit z-index used for 2.5D depth ordering (near units above far ones)
   escapes upward and competes directly with #fxFront/#popLayer/#flash,
   painting sprites over floating numbers and the white hit-flash. */
#bgLayer{z-index:0}
#floorLine{z-index:1}
#fxBack{z-index:2}
#unitLayer{z-index:3}
#fxFront{z-index:4}
#popLayer{z-index:5}
.hero-skill-dialogue{position:absolute;z-index:30;left:0;top:0;max-width:min(43vw,230px);padding:7px 11px 8px;border:4px solid #090b0c;border-radius:14px;color:#fff;background:repeating-linear-gradient(135deg,#bda373 0 7px,#aa8e61 7px 14px);box-shadow:inset 0 2px #fff8,0 4px #090b0c,0 0 0 1px #090b0c;transform:translate(-50%,calc(-100% - 6px)) scale(.82);transform-origin:50% 100%;opacity:0;pointer-events:none;text-align:center;font:900 clamp(10px,2.3vw,14px)/1.12 "Arial Black","Trebuchet MS",sans-serif;letter-spacing:-.2px;-webkit-text-stroke:1.5px #111820;paint-order:stroke fill;transition:opacity .14s ease-out,transform .22s cubic-bezier(.16,1.35,.35,1)}
.hero-skill-dialogue:after{content:"";position:absolute;left:50%;bottom:-10px;width:16px;height:16px;background:#b39869;border-right:4px solid #090b0c;border-bottom:4px solid #090b0c;transform:translateX(-50%) rotate(45deg);z-index:-1}
.hero-skill-dialogue.visible{opacity:1;transform:translate(-50%,calc(-100% - 6px)) scale(1)}
.hero-skill-dialogue.leaving{opacity:0;transform:translate(-50%,calc(-100% - 14px)) scale(.94)}
@media(max-width:430px){.hero-skill-dialogue{max-width:44vw;padding:6px 8px 7px;border-width:3px;border-radius:11px;font-size:10px;-webkit-text-stroke:1px #111820}.hero-skill-dialogue:after{bottom:-8px;width:12px;height:12px;border-width:3px}}
#flash{position:absolute;inset:0;pointer-events:none;opacity:0;mix-blend-mode:screen;z-index:6}
#vignette{position:absolute;inset:0;pointer-events:none;
  box-shadow:inset 0 0 150px 45px rgba(0,0,0,.8);z-index:7}

/* Anchored at the stage's TOP-left, not bottom - the transform below carries
   an absolute y (matching how every FX/skill call already treats u.y as a
   stage-top-relative coordinate). Anchoring to bottom:0 instead - the old
   setup - pinned every sprite to the literal screen edge regardless of
   `ground`, which is why characters used to sit inside the portrait dock. */
.unit{position:absolute;top:0;left:0;width:0;height:0;will-change:transform}
.unit .body{position:absolute;left:0;bottom:0;transform-origin:50% 100%;will-change:transform}
.unit .body img{width:100%;height:auto;display:block;
  filter:saturate(1.12) contrast(1.06)
    drop-shadow(0 0 1.5px rgba(0,0,0,.5))
    drop-shadow(0 -1px 0 rgba(255,255,255,.28))
    drop-shadow(0 8px 9px rgba(0,0,0,.5))}
.unit.casting:not(.waxwell-runner) .body:before{content:"";position:absolute;z-index:-1;left:-22%;bottom:-8%;width:144%;height:29%;border:2px solid #8fe7ff8c;border-top-color:transparent;border-radius:50%;box-shadow:0 0 14px #8fe7ff55;transform:rotate(-7deg);pointer-events:none;animation:battleCastRing .6s ease-in-out infinite alternate}.unit.foe.casting:not(.waxwell-runner) .body:before{border-color:#ff8b9a99;border-top-color:transparent;box-shadow:0 0 14px #ff8b9a55}.unit.boss:not(.casting) .body:before{content:"";position:absolute;z-index:-1;left:-28%;bottom:-11%;width:156%;height:31%;border:2px solid #e8b96b66;border-top-color:transparent;border-radius:50%;box-shadow:0 0 13px #d56b5c44;transform:rotate(5deg);pointer-events:none;animation:battleBossAura 2.2s ease-in-out infinite}.unit.elite:not(.casting) .body:before{content:"";position:absolute;z-index:-1;left:-18%;bottom:-8%;width:136%;height:25%;border:1px solid #d5e59c66;border-top-color:transparent;border-radius:50%;pointer-events:none;animation:battleEliteAura 2.8s ease-in-out infinite}.unit.hurt:not(.delilah-sample) .body:after{content:"";position:absolute;z-index:6;inset:8% 5% 2%;border:2px solid #fff4df99;border-radius:45%;background:radial-gradient(ellipse,#fff6 0 9%,transparent 52%);mix-blend-mode:screen;pointer-events:none;animation:battleHurtFlash .1s ease-out both}
.unit.targeting .nameplate{filter:drop-shadow(0 0 5px #e6d27866)}.unit.targeting .nameplate:after{content:" ◈";color:#f0d978;font-size:8px;opacity:.9}
.unit .body .soulvester-carried-sword{position:absolute;z-index:4;left:28%;bottom:3%;width:78%;height:auto;display:block;
  pointer-events:none;filter:saturate(1.08) contrast(1.03) drop-shadow(0 2px 2px #071012b8) drop-shadow(0 0 2px #d8fff0a8);transform-origin:25% 76%}
.unit.brightney-unit:before{content:"";position:absolute;z-index:-1;left:-70px;bottom:-36px;width:140px;height:150px;border-radius:50%;
  background:radial-gradient(ellipse at 50% 62%,#fff3b03d 0 16%,#fff3b018 38%,transparent 72%);
  box-shadow:0 0 24px #fff3b01c;pointer-events:none;animation:brightneySafetyGlow 2.2s ease-in-out infinite}
.unit.brightney-unit:after{content:"";position:absolute;z-index:-1;left:-78px;bottom:-27px;width:156px;height:112px;border:2px solid #fff3b026;border-radius:50%;
  border-top-color:#fffbe08a;border-bottom-color:transparent;transform:rotate(-8deg);pointer-events:none;animation:brightneySafetyOrbit 4.8s linear infinite}
@keyframes brightneySafetyGlow{0%,100%{opacity:.58;transform:scale(.94)}50%{opacity:.92;transform:scale(1.04)}}
@keyframes brightneySafetyOrbit{to{rotate:360deg}}
.poppy-sprite-bubble{position:absolute;z-index:-1;border:3px solid rgba(255,235,249,.9);border-radius:50%;pointer-events:none;
  background:radial-gradient(circle at 32% 25%,rgba(255,255,255,.55) 0 5%,rgba(255,187,226,.2) 13% 38%,rgba(119,220,244,.2) 68%,rgba(255,255,255,.48) 72%,transparent 75%);
  box-shadow:inset -8px -12px 18px rgba(236,124,189,.25),inset 5px 6px 10px rgba(255,255,255,.35),0 0 10px rgba(255,174,222,.45);
