/* ---------- visual novel story scene ---------- */
.banterScene{position:absolute;inset:0;z-index:40;overflow:hidden;background:linear-gradient(180deg,#07101a73,#07101ad9 72%,#030609f2);animation:vnFade .25s both}.banterScene.post-battle:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 50% 28%,#7be0ff24,transparent 48%);pointer-events:none}.vn-top{position:absolute;z-index:3;top:58px;left:12px;right:12px;text-align:center;color:#fff;text-shadow:0 2px #000}.vn-top small,.vn-top b{display:block}.vn-top small{font-size:8px;color:#bdf56a;letter-spacing:2px;text-transform:uppercase}.vn-top b{margin-top:3px;font-size:18px;letter-spacing:.3px}.vn-cast{position:absolute;z-index:1;left:2%;right:2%;top:92px;bottom:116px;display:flex;align-items:flex-end;justify-content:center;pointer-events:none}.vn-portrait{position:relative;width:min(31vw,170px);height:100%;margin:0 -4.5%;opacity:.28;filter:grayscale(.45) brightness(.6);transform:translateY(14px) scale(.9);transition:opacity .2s,filter .2s,transform .25s;transform-origin:50% 100%}.vn-portrait img{position:absolute;inset:auto 0 0;width:100%;height:100%;object-fit:contain;filter:drop-shadow(0 8px 5px #000b)}.vn-portrait i{position:absolute;left:10%;right:10%;bottom:-2px;height:14px;border-radius:50%;background:#0008;filter:blur(4px)}.vn-portrait.active{z-index:2;opacity:1;filter:none;transform:translateY(0) scale(1.08)}
.banterBox{position:absolute;z-index:4;left:9px;right:9px;bottom:12px;min-height:86px;display:flex;gap:8px;align-items:flex-start;background:linear-gradient(180deg,#fdfaf8f5,#e7dfd2f5);color:#251e17;border:3px solid #111820;border-radius:7px;padding:14px 14px 11px;box-shadow:0 6px 0 #0008,inset 0 2px #fff9;animation:boxIn .18s cubic-bezier(.2,1.4,.4,1)}.banterBox:before{content:"";position:absolute;left:12px;right:12px;top:-5px;height:7px;background:linear-gradient(90deg,#73d8ff,#f0a6cf);clip-path:polygon(0 35%,100% 0,98% 100%,2% 70%)}.banterBox .bb-body{flex:1;min-width:0}.banterBox .bb-name{display:inline-block;min-width:75px;margin:-25px 0 8px;padding:4px 11px;border:2px solid #111820;border-radius:5px;background:#203746;color:#dff8ff;font-size:10px;font-weight:900;letter-spacing:.8px;text-transform:uppercase;box-shadow:0 2px #0006}.banterBox.narrator .bb-name{background:#554b43;color:#fff2da}.banterBox .bb-text{font-size:13px;line-height:1.42;font-weight:700}.banterBox .bb-action{font-weight:600;color:#8a5e72}.banterBox .bb-progress{position:absolute;right:10px;top:5px;color:#756c62;font-size:7px;font-weight:900}.banterBox .bb-next{flex:none;align-self:flex-end;opacity:.55;font-size:12px;animation:bbBounce 1s ease-in-out infinite}.vn-skip{position:absolute;z-index:5;right:8px;top:8px;padding:5px 7px;border:1px solid #ffffff55;border-radius:4px;background:#07101aaa;color:#fff;font-size:7px;font-weight:900}.banterScene.post-battle .vn-top small{color:#73d8ff}
@keyframes boxIn{0%{transform:translateY(16px);opacity:0}100%{transform:translateY(0);opacity:1}}
@keyframes bbBounce{0%,100%{transform:translateY(0)}50%{transform:translateY(3px)}}
@keyframes vnFade{from{opacity:0}to{opacity:1}}

/* Compact campaign dialogue: keep the fight visible and let the active
   speaker own the bubble instead of covering the entire stage with a panel. */
.banterScene{background:linear-gradient(180deg,#07101a22 0%,#07101a38 55%,#030609a8 100%);backdrop-filter:blur(1px)}
.banterScene.post-battle:before{background:radial-gradient(circle at 50% 32%,#7be0ff18,transparent 54%)}
.vn-top{top:35px;left:50%;right:auto;width:min(72vw,300px);transform:translateX(-50%);padding:5px 11px;border:1px solid #ffffff2e;border-radius:999px;background:#08121a78;box-shadow:0 3px 12px #0004;animation:vnPillIn .35s cubic-bezier(.2,1.3,.4,1)}
.vn-top small{font-size:7px;letter-spacing:1.6px}.vn-top b{font-size:12px;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.vn-cast{top:76px;bottom:70px;left:5%;right:5%;align-items:flex-end}
.vn-portrait{width:min(29vw,154px);height:100%;margin:0 -5%;opacity:.16;filter:grayscale(.5) brightness(.56);transform:translateY(16px) scale(.84);transition:opacity .25s,filter .25s,transform .32s cubic-bezier(.2,1.3,.4,1)}
.vn-portrait img{filter:drop-shadow(0 6px 4px #0009)}
.vn-portrait figcaption{position:absolute;z-index:2;left:50%;bottom:5px;transform:translateX(-50%) translateY(4px);padding:3px 6px;border:1px solid #ffffff2c;border-radius:999px;background:#07101ac4;color:#e8f6f2;font-size:7px;font-weight:900;letter-spacing:.4px;white-space:nowrap;opacity:0;transition:opacity .2s,transform .2s}
.vn-portrait.active{opacity:.9;filter:none;transform:translateY(0) scale(1)}
.vn-portrait.active figcaption{opacity:1;transform:translateX(-50%) translateY(0)}
.banterBox{left:12px;right:12px;bottom:58px;width:min(88vw,390px);min-height:0;max-height:42vh;margin:0;padding:13px 13px 12px 57px;gap:6px;border:2px solid #111820;border-radius:17px;background:linear-gradient(145deg,#fffaf0f5,#e5ddd1ee);box-shadow:0 5px 0 #0007,0 8px 18px #0005,inset 0 2px #fff9;animation:bubbleIn .3s cubic-bezier(.2,1.35,.4,1)}
.banterBox[data-align="right"]{left:auto;right:12px}
.banterBox[data-align="center"]{left:12px;right:12px;width:min(88vw,390px);margin-left:auto;margin-right:auto}
.banterBox.narrator{padding-left:15px;background:linear-gradient(145deg,#f3eee6ee,#d8d0c5ea)}
.banterBox:before{top:-4px;left:22px;right:22px;height:5px;border-radius:99px;clip-path:none;opacity:.8}
.banterBox:after{content:"";position:absolute;left:22px;bottom:-13px;width:0;height:0;border:8px solid transparent;border-top-color:#111820;transform:rotate(8deg);filter:drop-shadow(0 2px 0 #0005)}
.banterBox[data-align="right"]:after{left:auto;right:22px;transform:rotate(-8deg)}
.banterBox[data-align="center"]:after{left:50%;transform:translateX(-50%)}
.bb-speaker{position:absolute;z-index:2;left:-9px;top:-23px;width:54px;height:54px;display:grid;place-items:center;border:3px solid #111820;border-radius:50%;background:linear-gradient(145deg,#9de7ff,#4d91b0);box-shadow:0 3px 0 #0007,0 0 0 3px #ffffffc4;animation:bbIconIn .35s cubic-bezier(.15,1.55,.35,1)}
.bb-speaker:after{content:"";position:absolute;right:-8px;bottom:3px;width:15px;height:15px;background:#f7eee2;border-right:2px solid #111820;border-bottom:2px solid #111820;transform:skew(18deg) rotate(35deg);z-index:-1}
.bb-speaker .bb-icon{width:43px;height:43px;object-fit:contain;filter:drop-shadow(0 2px 1px #0008)}
.bb-speaker i{position:absolute;inset:-5px;border:1px solid #ffffff8c;border-radius:50%;animation:bbRing 1.7s ease-out infinite;pointer-events:none}
.banterBox .bb-body{position:relative;z-index:1}.banterBox .bb-name{min-width:0;margin:-1px 25px 5px 0;padding:3px 8px;border-width:1px;border-radius:999px;font-size:8px;letter-spacing:.7px;box-shadow:0 2px #0004;animation:bbNameIn .25s .06s both}
.banterBox .bb-text{font-size:12px;line-height:1.35;font-weight:700;animation:bubbleTextIn .28s .05s both}
.banterBox .bb-progress{right:11px;top:9px;font-size:7px}.banterBox .bb-next{font-size:10px;animation:bbBounce .9s ease-in-out infinite}.banterBox.narrator .bb-next{align-self:flex-end}
.vn-skip{top:8px;right:8px;border-radius:999px;background:#07101a86;transition:transform .15s,background .15s}.vn-skip:active{transform:scale(.94);background:#07101ad8}
@keyframes vnPillIn{from{opacity:0;transform:translateX(-50%) translateY(-7px) scale(.9)}}
@keyframes bubbleIn{from{opacity:0;transform:translateY(12px) scale(.94)}to{opacity:1;transform:translateY(0) scale(1)}}
@keyframes bbIconIn{from{opacity:0;transform:scale(.55) rotate(-12deg)}to{opacity:1;transform:scale(1) rotate(0)}}
@keyframes bbNameIn{from{opacity:0;transform:translateX(-5px)}}
@keyframes bubbleTextIn{from{opacity:0;transform:translateY(4px);clip-path:inset(0 100% 0 0)}to{opacity:1;transform:translateY(0);clip-path:inset(0 0 0 0)}}
@keyframes bbRing{0%{opacity:.75;transform:scale(.92)}100%{opacity:0;transform:scale(1.32)}}
@media(max-width:560px){.vn-top{top:33px}.vn-cast{top:72px;bottom:65px}.vn-portrait{width:min(31vw,125px)}.banterBox{bottom:53px;width:calc(100vw - 24px);max-height:45vh;padding-left:53px}.bb-speaker{width:50px;height:50px}.bb-speaker .bb-icon{width:40px;height:40px}.banterBox .bb-text{font-size:11.5px}}
@media(prefers-reduced-motion:reduce){.banterScene *{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}

/* Dialogue uses icons only. Keep the character art and the battle floor clear;
   the small icon rail identifies the cast while the bubble lives in the quiet
   upper story area. */
.vn-cast{top:78px;bottom:auto;left:50%;right:auto;width:min(92vw,430px);height:43px;transform:translateX(-50%);gap:6px;align-items:center;justify-content:center}
.vn-portrait{position:relative;width:40px;height:40px;margin:0;flex:0 0 40px;opacity:.42;filter:none;transform:scale(.86);border:2px solid #ffffff42;border-radius:50%;background:#07101acc;box-shadow:0 2px 5px #0007;overflow:visible;transition:opacity .2s,transform .25s,border-color .2s,box-shadow .2s}
.vn-portrait img{position:absolute;inset:3px;width:calc(100% - 6px);height:calc(100% - 6px);object-fit:contain;filter:drop-shadow(0 2px 1px #000b)}
.vn-portrait figcaption{left:50%;bottom:-14px;transform:translateX(-50%);padding:2px 4px;font-size:5.5px;background:#07101acc}
.vn-portrait i{display:none}
.vn-portrait.active{opacity:1;filter:none;transform:scale(1.08);border-color:#bdf56a;box-shadow:0 0 0 2px #bdf56a55,0 3px 8px #0009}
.vn-portrait.active figcaption{transform:translateX(-50%);opacity:1}
.banterBox{top:130px;bottom:auto;max-height:25vh}
.banterBox[data-align="center"]{top:130px;bottom:auto}
@media(max-width:560px){.vn-cast{top:74px;height:40px}.vn-portrait{width:36px;height:36px;flex-basis:36px}.banterBox,.banterBox[data-align="center"]{top:119px;bottom:auto;max-height:29vh}}

/* ---------- Friendship Badge medallion (see badgeIconHtml, data/badges.js) ----------
   Most badges use a color and emoji; badges with their own art use .bi-art. */
.badgeIcon{position:relative;width:44px;height:44px;flex:none;border-radius:50%;
  display:grid;place-items:center;border:3px solid var(--edge);
  box-shadow:inset 0 2px 0 rgba(255,255,255,.18),0 2px 0 rgba(0,0,0,.35)}
.badgeIcon:before{content:"";position:absolute;inset:-3px;border-radius:50%;
  background:conic-gradient(var(--gold) var(--fill,0%),rgba(255,255,255,.12) 0);
  z-index:-1;opacity:.85}
.badgeIcon .bi-emoji{font-size:19px;filter:drop-shadow(0 1px 1px rgba(0,0,0,.5))}
.badgeIcon .bi-art{width:100%;height:100%;display:block;object-fit:cover;border-radius:50%}
.badgeIcon .bi-lvl{position:absolute;bottom:-4px;right:-4px;background:#1c1f24;
  border:2px solid var(--edge);border-radius:8px;font-size:9px;font-weight:900;
  padding:1px 4px;color:var(--gold)}

/* ---------- results: "THAT'S A WRAP!" ---------- */
#battleEnd{position:absolute;inset:0;z-index:20;overflow-y:auto;overflow-x:hidden;
  display:flex;flex-direction:column;padding:36px 0 calc(76px + env(safe-area-inset-bottom,0px));
  background:
    radial-gradient(ellipse at 50% 42%,rgba(70,70,70,.55),transparent 62%),
    repeating-linear-gradient(41deg,rgba(255,255,255,.016) 0 3px,transparent 3px 7px),
    #17181a;
  animation:wrapFade .25s}
#battleEnd.wrap-win{background:
  radial-gradient(ellipse at 50% 30%,rgba(255,204,72,.17),transparent 58%),
  repeating-linear-gradient(41deg,rgba(255,255,255,.016) 0 3px,transparent 3px 7px),#17181a}
#battleEnd.wrap-loss{background:
  radial-gradient(ellipse at 50% 30%,rgba(255,78,78,.13),transparent 58%),
  repeating-linear-gradient(41deg,rgba(255,255,255,.016) 0 3px,transparent 3px 7px),#17181a}
@keyframes wrapFade{from{opacity:0}}

/* the whole card is one centred column that can scroll if the run was long */
.wrap-inner{position:relative;z-index:8;margin:auto;width:100%;display:flex;flex-direction:column;align-items:center}
.wrap-kicker{position:relative;z-index:4;margin-bottom:5px;padding:4px 9px;border:2px solid #141414;border-radius:6px;
  color:#17181a;background:#f2c84b;box-shadow:0 3px 0 #141414;font-size:8px;font-weight:1000;letter-spacing:2px;
  animation:wrapKicker .3s .08s both}
.wrap-loss .wrap-kicker{color:#fff;background:#c45b64}
@keyframes wrapKicker{from{opacity:0;transform:translateY(-8px) scale(.8)}to{opacity:1;transform:none}}

/* hazard tape across the top and bottom, like the Dandy's World results card */
.wrap-tape{position:absolute;left:0;right:0;height:26px;z-index:6;
  background:repeating-linear-gradient(45deg,#f5c518 0 22px,#141414 22px 44px);
  box-shadow:0 0 0 3px #141414;}
.wrap-tape.top{top:0;animation:ticketInT .45s cubic-bezier(.2,1.4,.4,1)}
.wrap-tape.bot{bottom:0;animation:ticketInB .45s cubic-bezier(.2,1.4,.4,1)}
@keyframes ticketInT{from{transform:translateY(-100%)}}
@keyframes ticketInB{from{transform:translateY(100%)}}

.wrap-title{position:relative;z-index:4;font:900 clamp(30px,10vw,54px)/1 "Verdana",sans-serif;
  letter-spacing:1px;color:#fff;text-align:center;padding:0 12px;
  -webkit-text-stroke:9px #141414;paint-order:stroke fill;
  filter:drop-shadow(0 6px 0 rgba(0,0,0,.5));
  transform-origin:50% 50%;
  animation:wrapSlam .5s cubic-bezier(.15,1.8,.35,1) both;
  transition:transform .45s cubic-bezier(.2,1.4,.4,1),font-size .45s,margin .45s}
@keyframes wrapSlam{
  0%{transform:scale(3.4) rotate(-9deg);opacity:0}
  55%{transform:scale(.86) rotate(2deg);opacity:1}
  75%{transform:scale(1.08) rotate(-1deg)}
  100%{transform:scale(1) rotate(0)}}
.wrap-title.lose{color:#ff8f8f}
/* once the results appear the title shrinks up out of the way */
.wrap-title.settled{font-size:clamp(20px,6.5vw,32px);-webkit-text-stroke-width:6px;margin-bottom:6px}

.wrap-panel{position:relative;z-index:4;width:min(92vw,430px);margin-top:12px;
  background:linear-gradient(180deg,#3a3f47,#262a30);
  border:4px solid #141414;border-radius:18px;padding:14px 12px 12px;
  box-shadow:inset 0 3px 0 rgba(255,255,255,.12),0 8px 0 rgba(0,0,0,.45);
  animation:wrapPanel .42s cubic-bezier(.2,1.5,.4,1) both}
.wrap-panel.win{border-color:#f1c94b}
.wrap-panel.loss{border-color:#a94d59}
@keyframes wrapPanel{from{transform:scale(.72) translateY(26px);opacity:0}}
.wrap-head{font:900 15px/1 "Verdana",sans-serif;letter-spacing:4px;color:#fff;text-align:center;
  -webkit-text-stroke:5px #141414;paint-order:stroke fill;margin-bottom:10px}

.wrap-line{display:flex;align-items:baseline;justify-content:space-between;gap:12px;text-align:left;font-weight:900;font-size:13px;color:#fff;
  padding:3px 2px;-webkit-text-stroke:4px #141414;paint-order:stroke fill;
  animation:wrapLine .34s cubic-bezier(.2,1.7,.4,1) both}
@keyframes wrapLine{from{transform:scale(.55) translateY(10px);opacity:0}}
.wrap-label{color:#d7dce1;white-space:nowrap}
.wrap-line b{color:#ffd23f;text-align:right;overflow-wrap:anywhere}
.wrap-line.big{font-size:clamp(17px,5.4vw,23px);margin-top:8px;color:#ffd23f;
  -webkit-text-stroke-width:6px;
  display:block;text-align:center;animation:wrapEarn .55s cubic-bezier(.15,1.9,.35,1) both}
@keyframes wrapEarn{
  0%{transform:scale(.3) rotate(-6deg);opacity:0}
  60%{transform:scale(1.22) rotate(2deg);opacity:1}
  100%{transform:scale(1) rotate(0)}}

.wrap-perf{margin-top:10px;border-top:3px solid #141414;padding-top:8px;
  animation:wrapLine .34s cubic-bezier(.2,1.7,.4,1) both}
.wrap-perf .row{margin-bottom:3px}
.wrap-report-title{margin-bottom:8px;color:#fff;font:1000 10px/1 Arial,sans-serif;letter-spacing:2px;text-align:center}
.wrap-report-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:5px;margin-bottom:9px}
.wrap-stat{min-width:0;padding:6px 3px 5px;border:2px solid #151719;border-radius:7px;background:#20252a;text-align:center;box-shadow:inset 0 1px #fff1}
.wrap-stat b{display:block;color:#fff;font:1000 12px/1 Arial,sans-serif;white-space:nowrap}
.wrap-stat span{display:block;margin-top:4px;color:#bfc7cc;font:900 7px/1.05 Arial,sans-serif;letter-spacing:.35px}
.wrap-stat.damage b,.wrap-roster-stat.damage{color:#ffd34e}.wrap-stat.danger b,.wrap-roster-stat.danger{color:#ff9696}
.wrap-stat.heal b,.wrap-roster-stat.heal{color:#8ff0b0}.wrap-stat.heal-soft b,.wrap-roster-stat.heal-soft{color:#9edcff}
.wrap-roster{border:2px solid #151719;border-radius:7px;overflow:hidden;background:#171b1f}
.wrap-roster-head,.wrap-roster-row{display:grid;grid-template-columns:minmax(104px,1.6fr) repeat(4,minmax(42px,1fr));align-items:center;gap:4px;padding:5px 5px}
.wrap-roster-head{background:#2c3339;color:#abb6bd;font:1000 7px/1 Arial,sans-serif;letter-spacing:.55px;text-align:right}
.wrap-roster-head span:first-child{text-align:left}.wrap-roster-row{border-top:1px solid #333a3f;color:#fff;font:900 10px/1 Arial,sans-serif}.wrap-roster-row.ko{opacity:.58}
.wrap-hero-name{display:flex;align-items:center;min-width:0;gap:5px}.wrap-hero-name img{width:23px;height:23px;object-fit:contain;flex:none}.wrap-hero-name span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.wrap-roster-stat{text-align:right;white-space:nowrap;font-size:9px}.wrap-report-note{margin-top:6px;color:#929da3;font:700 7px/1.25 Arial,sans-serif;text-align:center}

.wrap-btns{position:relative;z-index:10;width:min(92vw,430px);display:flex;gap:8px;margin-top:12px;
  min-height:44px;pointer-events:auto;
  animation:wrapLine .34s cubic-bezier(.2,1.7,.4,1) both}
.wrap-btns .btn{position:relative;z-index:11;touch-action:manipulation;pointer-events:auto}
.wrap-skip{position:absolute;bottom:40px;left:50%;transform:translateX(-50%);z-index:12;
  font-weight:900;font-size:12px;letter-spacing:2px;color:#cfd5dd;
  -webkit-text-stroke:4px #141414;paint-order:stroke fill;
  background:none;border:0;padding:8px 16px;opacity:.85}
.wrap-skip:active{transform:translateX(-50%) scale(.94)}

