.enemy-preview-head small{display:block;color:#ff8790;font-size:6px;letter-spacing:1.5px}.enemy-preview-head h2{margin:3px 0;font:900 18px/1 "Arial Black",sans-serif;color:#fff}.enemy-preview-head span{color:#c6d0cc;font-size:7px;letter-spacing:.5px}
.enemy-preview-section{margin-top:10px}.enemy-preview-section-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:5px;color:#e9f0eb;font-size:8px;letter-spacing:1px}.enemy-preview-section-title span{color:#ffb2b2;font-size:6px;letter-spacing:.6px}
.enemy-preview-moves{display:grid;gap:5px}.enemy-preview-move{padding:7px 8px;border:2px solid #202a2c;border-radius:8px;background:linear-gradient(180deg,#263032,#1b2224)}.enemy-preview-move.locked{opacity:.48}.enemy-preview-move-top{display:flex;align-items:baseline;gap:6px}.enemy-preview-move-top>span{color:#ffb6b6;font-size:6px;font-weight:900;letter-spacing:.7px}.enemy-preview-move-top>b{flex:1;color:#fff;font-size:10px}.enemy-preview-move-top>i{color:#aebbb6;font-size:6px;font-style:normal;white-space:nowrap}.enemy-preview-move-desc{margin-top:4px;color:#c7d0cc;font-size:7px;line-height:1.35}.enemy-preview-move-desc em{color:#ffe27a;font-style:normal;font-weight:900}.enemy-preview-move-desc .status-tag{font-size:inherit}
.enemy-preview-gear-list{display:grid;gap:5px}.enemy-preview-gear{display:flex;align-items:center;gap:8px;padding:7px 8px;border:2px solid #303b3d;border-radius:8px;background:#20292b}.enemy-preview-gear>img{width:32px;height:32px;object-fit:contain;filter:drop-shadow(0 2px 1px #000)}.enemy-preview-gear>strong{width:32px;text-align:center;font-size:24px}.enemy-preview-gear b{display:block;color:#fff;font-size:9px}.enemy-preview-gear b small{color:#ffe27a;font-size:6px}.enemy-preview-gear span{display:block;margin-top:2px;color:#9ee7ff;font-size:6px}.enemy-preview-gear p{margin:3px 0 0;color:#c0cac5;font-size:7px;line-height:1.25}.enemy-preview-empty{padding:9px;border:2px dashed #394547;border-radius:8px;color:#9daaa5;font-size:7px;text-align:center}
@media(max-width:560px){#modalBox.enemy-preview-modal{width:96vw;padding:10px}.enemy-preview-move-top>b{font-size:9px}.enemy-preview-move-desc{font-size:6px}}

.arena-fighter .arena-rarity-badge{position:absolute;z-index:5;top:-7px;right:-7px;max-width:50px;padding:2px 3px;border:1px solid #160a05;border-radius:4px;color:#211006;background:var(--rarity,#f4f0ff);box-shadow:0 2px 2px #0009;font:1000 6px/1 Georgia,serif;white-space:nowrap}

