.arena-fighter.rarity-border-1>img{border-color:#f4f0ff!important}.arena-fighter.rarity-border-2>img{border-color:#5fe07a!important}.arena-fighter.rarity-border-3>img{border-color:#5aa9ff!important}.arena-fighter.rarity-border-4>img{border-color:#c17bff!important}.arena-fighter.rarity-border-5>img{border-color:#ff6060!important}.arena-fighter.rarity-border-6>img{border-color:#ffce4d!important}
@keyframes mIn{from{transform:scale(.86) translateY(18px);opacity:0}to{transform:none;opacity:1}}
#toasts{position:fixed;left:0;right:0;top:62px;z-index:850;display:flex;flex-direction:column;
  align-items:center;gap:6px;pointer-events:none}
