  box-shadow:inset 0 2px 0 rgba(255,255,255,.12)}
.skill.lockd{opacity:.45;filter:grayscale(.5)}
.goob-hug-line{position:absolute;z-index:3;height:8px;transform-origin:0 50%;border:2px solid #2a1b13;border-radius:99px;background:repeating-linear-gradient(90deg,#f3bd68 0 13px,#74aee8 13px 24px,#e95e72 24px 34px);box-shadow:0 0 7px #f3bd68aa,0 2px #0008;pointer-events:none;animation:goobLineWiggle .42s ease-in-out infinite alternate}.goob-hug-line:after{content:"";position:absolute;inset:-4px;background:linear-gradient(90deg,transparent,#fff8,transparent);opacity:.55;animation:goobLineShine 1.2s linear infinite}.goob-hug-line.strained{filter:saturate(1.35);animation-duration:.16s;box-shadow:0 0 10px #ff7b7bcc,0 2px #0008}
