/* ---------- prize parade / scratch ---------- */
.scratch-preview{position:relative;overflow:hidden;border-color:#d88555!important;background:linear-gradient(120deg,#623a83,#ca5b75 55%,#f2a64f)!important;box-shadow:inset 0 2px #fff7,0 4px #321f42!important}.scratch-preview:before{content:"";position:absolute;inset:-30% -15%;background:repeating-radial-gradient(ellipse at 50% 50%,#fff2 0 2px,transparent 3px 22px);opacity:.7;transform:rotate(-12deg)}.scratch-preview>*{position:relative}.scratch-preview-burst{position:absolute;top:-8px;right:4px;font-size:42px;filter:drop-shadow(0 3px #51274f);transform:rotate(12deg)}.scratch-preview small{display:block;color:#fff1c9;font-size:7px;font-weight:1000;letter-spacing:1.1px}.scratch-preview .b{margin-top:2px;color:#fffdf0;font-size:13px;text-shadow:0 2px #63314d}.scratch-preview .muted{color:#fff0d5}.scratch-preview-hero{width:45px;height:45px;margin-right:-12px;object-fit:contain;filter:drop-shadow(0 3px 1px #3b1d44)}.scratch-ticket-count{position:relative;z-index:1;align-self:flex-start;padding:5px 7px;border:2px solid #5b2f4f;border-radius:99px;color:#52273d;background:#fff3b9;box-shadow:0 2px #6c334c;font-size:10px}.scratch-ticket-count b{font-size:12px}.scratch-modal-head{position:relative;overflow:hidden;padding:12px 10px 10px;border:3px solid #5b315b;border-radius:16px;color:#fff7dd;background:linear-gradient(135deg,#6b3e88,#d76078 58%,#ef9f4c);box-shadow:inset 0 2px #fff6,0 4px #452844;text-align:center}.scratch-modal-head:before{content:"";position:absolute;inset:0;background:repeating-radial-gradient(ellipse at 50% -30%,#fff2 0 2px,transparent 3px 20px);pointer-events:none}.scratch-modal-head>*{position:relative}.scratch-modal-stars{color:#fff1a5;font-size:10px;letter-spacing:7px}.scratch-modal-title{margin:1px 0 5px;color:#fffbe4;font-size:21px;font-weight:1000;letter-spacing:1.5px;text-shadow:0 3px #723955}.scratch-modal-feature{display:flex;align-items:center;justify-content:center;gap:3px;min-height:36px}.scratch-modal-feature img{width:37px;height:37px;margi