/* ---------- choices ---------- */
.choice{padding:12px;border-radius:14px;
  background:linear-gradient(180deg,#4a515b,#333941);
  border:3px solid var(--edge);margin-bottom:9px;cursor:pointer;
  box-shadow:inset 0 2px 0 rgba(255,255,255,.13),0 4px 0 rgba(0,0,0,.32);
  transition:transform .1s,border-color .15s}
.choice:active{transform:translateY(4px);box-shadow:inset 0 2px 0 rgba(255,255,255,.13),0 0 0 rgba(0,0,0,.32)}
.choice:hover{border-color:var(--accent)}
.choice b{display:block;font-size:13px;margin-bottom:3px}

.modrow{display:flex;gap:6px;flex-wrap:wrap;margin-top:8px}
.modtag{font-size:10px;font-weight:900;padding:4px 9px;border-radius:99px;
  background:linear-gradient(180deg,#7a3050,#4a1f30);border:2px solid var(--edge);color:#ffc8d8}

/* Primary screen decisions stay reachable while the supporting details move. */
.screen-actionbar{position:sticky;z-index:22;top:0;margin:7px -2px 8px;padding:6px;border:2px solid #080b0c;border-radius:10px;background:#182121e8;box-shadow:0 3px #0b0f10;backdrop-filter:blur(8px)}

/* Real service timers: one UTC clock drives every daily and weekly reset. */
.live-service-strip{display:grid;grid-template-columns:auto 1fr 1fr;align-items:center;gap:7px;margin-bottom:10px;
  padding:7px 8px;border:3px solid var(--edge);border-radius:9px;background:linear-gradient(180deg,#182020,#2d3938);
  box-shadow:inset 0 1px #efffe622,0 3px #111617;color:var(--dim);font-size:7px;letter-spacing:.55px}
.live-service-strip>span{display:flex;align-items:center;gap:4px;color:#aef46b;font-size:9px}.live-service-strip>span i{width:7px;height:7px;border-radius:50%;background:#78dd6b;box-shadow:0 0 5px #78dd6b}
.live-service-strip>div{text-align:right}.live-service-strip b{display:block;color:#fff;font-size:9px;letter-spacing:.2px}

/* ---------- Dandy's World terminal pass ---------- */
:root{--gold:#a5f247}
#screen{background:linear-gradient(180deg,#2d3738,#202829)}
h2.sec{color:#eaffe4;text-shadow:0 3px #111;-webkit-text-stroke:3px #0b0e0f}
.htile{border-radius:9px;background:linear-gradient(180deg,#56625f,#293233);border-color:#080b0c;box-shadow:inset 0 2px #efffe633,0 4px #111617}
.htile .por{inset:0 0 17px;padding:5px;background:radial-gradient(circle at 50% 30%,#6b807b55,transparent 65%)}
.htile .nm{font-size:9px;background:linear-gradient(transparent,#101516 48%);padding:14px 2px 3px}.htile .lv{border-radius:5px;background:#1a2223;border-color:#090d0e}.htile .rar{border-color:#080b0c}
.floor,.oppo,.choice{border-radius:10px;border-color:#080b0c;background:linear-gradient(180deg,#4b5856,#293233);box-shadow:inset 0 2px #efffe622,0 4px #111617}.node{border-radius:9px;border-color:#080b0c;background:linear-gradient(180deg,#586663,#2b3536);box-shadow:inset 0 2px #efffe622,0 3px #111617}

/* Events live on a service terminal, not a fantasy map. */
.event-raid{margin:-10px -10px -18px;padding:10px 10px 22px;min-height:100%;background:
  repeating-linear-gradient(90deg,transparent 0 21px,#ffffff06 21px 22px),
  repeating-linear-gradient(0deg,#00000017 0 2px,transparent 2px 8px),linear-gradient(180deg,#394544,#1e2829 72%,#141a1b)}
.event-raid:before{top:112px;left:-80px;width:280px;height:150px;background:radial-gradient(ellipse,#83a87b24 0 10%,transparent 60%);filter:none}.event-raid:after{top:auto;bottom:8px;right:-110px;width:260px;height:120px;background:radial-gradient(ellipse,#80cc6520 0 9%,transparent 64%);filter:none}
