.event-stage-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:6px}.event-stage{position:relative;min-height:48px;padding:5px 3px;border:2px solid #080b0c;border-radius:8px;color:#dce6e1;background:linear-gradient(180deg,#52605c,#293332);box-shadow:inset 0 1px #fff2,0 3px #111617}.event-stage b,.event-stage small{display:block}.event-stage b{font-size:13px}.event-stage small{margin-top:2px;color:#aebbb5;font-size:7px}.event-stage.done{color:#142114;background:linear-gradient(180deg,#bdf36b,#62b758)}.event-stage.done small{color:#234322}.event-stage.current:after{content:"NEXT";position:absolute;top:3px;right:4px;color:#bdf36b;font-size:5px;letter-spacing:.5px}.event-stage.selected{outline:2px solid #eaffe0;outline-offset:1px;transform:translateY(-1px)}.event-stage:disabled{opacity:.3;filter:grayscale(1);box-shadow:none}.event-dossier.delilah .event-stage.done{background:linear-gradient(180deg,#e2a4ff,#9552b3)}.event-dossier.delilah .event-stage.current:after{color:#e2a4ff}
