.looey-inflate-live{position:absolute;z-index:8;pointer-events:none;opacity:0;transform:translateY(18px) scale(.46,.68);border:4px solid #fff;border-radius:49% 51% 47% 53%;background:radial-gradient(circle at 32% 23%,#fff 0 5%,#fff9 7%,transparent 17%),radial-gradient(ellipse at 45% 42%,#fff 0 15%,#ffd5e5 36%,#ff8fb0 72%,#d75c96 100%);box-shadow:inset -10px -10px 18px #9c3f7866,0 0 13px #fff,0 5px 4px #42152b88;transition:transform .38s cubic-bezier(.15,1.5,.3,1),opacity .14s}.looey-inflate-live:after{content:"";position:absolute;left:50%;bottom:-26px;width:2px;height:29px;background:#fff;box-shadow:0 0 2px #56354a;transform:rotate(5deg)}.looey-inflate-live i{position:absolute;left:50%;bottom:-7px;width:13px;height:13px;background:#ffb4cb;border:3px solid #fff;transform:translateX(-50%) rotate(45deg);z-index:-1}.looey-inflate-live b,.looey-inflate-live em{position:absolute;display:block;border-radius:50%;background:#fff8;box-shadow:0 0 5px #fff}.looey-inflate-live b{left:27%;top:22%;width:9px;height:9px}.looey-inflate-live em{right:20%;top:37%;width:5px;height:5px}.looey-inflate-live.active{opacity:.96;transform:translateY(-3px) scale(1,1)}.looey-inflate-live.leaving{opacity:0;transform:translateY(-36px) scale(1.1,.84);transition:transform .28s ease-in,opacity .22s}.looey-show-stage{position:absolute;z-index:3;pointer-events:none;opacity:0;transform:scale(.76);transform-origin:50% 70%;transition:transform .38s cubic-bezier(.15,1.4,.3,1),opacity .2s}.looey-show-stage.active{opacity:1;transform:scale(1)}.looey-show-stage.leaving{opacity:0;transform:scale(1.1);transition:transform .42s ease-in,opacity .36s}.looey-show-spotlight{position:absolute;left:18%;top:0;width:64%;height:100%;border-radius:50% 50% 12% 12%;background:linear-gradient(180deg,#fff8 0,#ffe9f533 42%,transparent 84%);filter:blur(3px);transform:perspective(180px) rotateX(12deg)}.looey-show-stage:before,.looey-show-stage:after{content:"";position:absolute;top:8%;width:3px;height:88%;background:linear-gradient(#ff8fb0,#ffd166,#8fe8ff);box-shadow:0 0 7px #fff}.looey-show-stage:before{left:8%;transform:rotate(17deg)}.looey-show-stage:after{right:8%;transform:rotate(-17deg)}.looey-show-ball{position:absolute;z-index:2;width:18px;height:18px;border:3px solid #fff;border-radius:50%;box-shadow:0 2px 3px #3a1830,0 0 8px currentColor;background:currentColor;animation:looeyJuggle 1.12s ease-in-out infinite}.looey-show-ball.one{left:31%;top:37%;color:#ff8fb0}.looey-show-ball.two{left:47%;top:17%;color:#ffd166;animation-delay:-.36s}.looey-show-ball.three{left:63%;top:37%;color:#8fe8ff;animation-delay:-.72s}.looey-show-stage span{position:absolute;left:50%;bottom:0;transform:translateX(-50%);padding:3px 7px;border:2px solid #fff;border-radius:5px;color:#fff;background:#5b2e578e;box-shadow:0 2px #241228;font:1000 8px/1 Arial,sans-serif;letter-spacing:1px;white-space:nowrap}@keyframes looeyJuggle{0%,100%{transform:translateY(19px) scale(.82)}50%{transform:translateY(-26px) scale(1.04)}}
.looey-inflate-live{background:radial-gradient(circle at 32% 23%,#fff 0 8%,#fffdfd 10%,transparent 20%),radial-gradient(ellipse at 45% 42%,#fff 0 32%,#fff9fb 58%,#ffe2ed 82%,#ffb6cf 100%);box-shadow:inset -10px -10px 18px #e987ad55,0 0 13px #fff,0 5px 4px #42152b88}

/* Flutter's aerial-control terrain. It stays light enough for battle units
   to remain readable while making gust paths and Wingstorm unmistakable. */
.flutter-gust-live{position:absolute;z-index:4;pointer-events:none;opacity:0;overflow:hidden;border:2px solid #c9f8ff;border-radius:48% 52% 42% 58%;background:linear-gradient(90deg,#baf6ff22,#79dff455 48%,#eaffff18);box-shadow:0 0 12px #75e6f766,inset 0 0 16px #d8fbff33;transform:scaleX(.2) rotate(-2deg);transition:transform .3s cubic-bezier(.2,1.4,.4,1),opacity .18s}.flutter-gust-live.active{opacity:.9;transform:scaleX(1) rotate(0)}.flutter-gust-live.leaving{opacity:0;transform:scaleX(1.08) rotate(3deg)}.flutter-gust-live i{position:absolute;width:58%;height:18px;border-top:2px solid #eaffff;border-radius:50%;transform:rotate(calc((var(--flutter-face) - 1) * 2deg));animation:flutterGustTurn 1.1s linear infinite}.flutter-gust-live i:nth-child(1){left:4%;top:24%;opacity:.7}.flutter-gust-live i:nth-child(2){left:18%;top:47%;width:70%;animation-delay:-.34s}.flutter-gust-live i:nth-child(3){left:2%;top:70%;width:48%;animation-delay:-.7s}.flutter-gust-live b{position:absolute;right:10px;bottom:7px;color:#eaffff;font:900 7px/1 Arial,sans-serif;letter-spacing:1.2px;text-shadow:0 1px 3px #16718b}.flutter-trail-live{position:absolute;z-index:3;pointer-events:none;width:88px;height:36px;opacity:0;border-radius:60%;background:linear-gradient(90deg,#d8fbff88,#65d6e933,transparent);clip-path:polygon(0 50%,22% 17%,100% 0,72% 50%,100% 100%,22% 83%);transform-origin:calc((1 + var(--flutter-face)) * 25%) 50%;transform:scaleX(.2) rotate(calc((var(--flutter-face) - 1) * 3deg));filter:drop-shadow(0 0 5px #90ebf8);transition:transform .25s ease-out,opacity .18s}.flutter-trail-live.active{opacity:.8;transform:scaleX(1) rotate(calc((var(--flutter-face) - 1) * 3deg))}.flutter-trail-live.leaving{opacity:0;transform:scaleX(1.2) rotate(calc((var(--flutter-face) - 1) * 5deg));filter:blur(5px)}.flutter-wingstorm-live{position:absolute;z-index:2;pointer-events:none;opacity:0;border:2px dashed #d8fbff;border-radius:50%;background:repeating-conic-gradient(from 8deg,#84e9f822 0 8deg,#d8fbff08 8deg 22deg),radial-gradient(ellipse,#7de1ef1e,transparent 68%);box-shadow:0 0 18px #6cdeef66,inset 0 0 24px #bdf6ff33;transform:scale(.62) rotate(-6deg);transition:transform .5s cubic-bezier(.2,1.2,.4,1),opacity .3s}.flutter-wingstorm-live.active{opacity:.72;transform:scale(1) rotate(0)}.flutter-wingstorm-live.leaving{opacity:0;transform:scale(1.08) rotate(5deg)}.flutter-wingstorm-live i{position:absolute;left:50%;top:50%;width:42%;height:2px;background:linear-gradient(90deg,transparent,#eaffff,transparent);transform-origin:0 50%;animation:flutterGustTurn 2.8s linear infinite}.flutter-wingstorm-live i:nth-child(1){transform:rotate(0)}.flutter-wingstorm-live i:nth-child(2){transform:rotate(45deg);animation-delay:-.35s}.flutter-wingstorm-live i:nth-child(3){transform:rotate(90deg);animation-delay:-.7s}.flutter-wingstorm-live i:nth-child(4){transform:rotate(135deg);animation-delay:-1.05s}.flutter-wingstorm-live b{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);padding:4px 7px;border:1px solid #d8fbff;border-radius:99px;background:#123d49bb;color:#eaffff;font:900 8px/1 Arial,sans-serif;letter-spacing:1.4px;text-shadow:0 1px 3px #09313b}@keyframes flutterGustTurn{to{transform:rotate(360deg)}}

