/* Waxwell's floor pieces keep their warmth and volume without flashing the
   entire battle. The motion is local, slow, and easy to read. */
@keyframes waxFlicker{from{transform:translateY(1px) scaleY(.82);filter:drop-shadow(0 0 4px #ff8a38)}to{transform:translateY(-2px) scaleY(1.14);filter:drop-shadow(0 0 8px #ffd35b)}}
@keyframes waxZoneHeat{from{filter:saturate(1) brightness(.96)}to{filter:saturate(1.22) brightness(1.13)}}
.fx-wax-zone.soft em{box-shadow:0 2px 3px #4f2816aa}.fx-wax-zone.flame{animation:waxZoneHeat 1.2s ease-in-out infinite alternate}.fx-wax-trail.flame{animation:waxTrailHeat .8s ease-in-out infinite alternate}.fx-wax-zone.violet-flame{animation:violetWaxHeat 1.1s ease-in-out infinite alternate}
@keyframes violetWaxHeat{from{filter:saturate(1.1) brightness(.98) drop-shadow(0 0 6px #c084fc)}to{filter:saturate(1.35) brightness(1.18) drop-shadow(0 0 14px #e879f9)}}
.fx-wax-figure{position:absolute;z-index:3;left:0;top:0;width:0;height:0;pointer-events:none;opacity:0;transform-origin:50% 100%;transition:transform .16s ease-out,opacity .18s}.fx-wax-figure.shown{opacity:1}.fx-wax-figure img{position:absolute;left:-33px;bottom:0;width:66px;height:104px;object-fit:contain;filter:sepia(1) saturate(2.2) hue-rotate(345deg) brightness(1.18) contrast(1.08) drop-shadow(0 0 8px #e7bd54) drop-shadow(0 5px 4px #42230f);opacity:.86}.wax-figure-halo{position:absolute;left:-42px;bottom:4px;width:84px;height:32px;border:2px solid #f4cf68;border-radius:50%;background:radial-gradient(ellipse,#fff3a533 0 24%,#e7bd5444 46%,transparent 72%);box-shadow:inset 0 0 12px #e7bd5488,0 0 12px #e7bd54;animation:waxFigurePulse 1.35s ease-in-out infinite alternate}.wax-figure-wick{position:absolute;z-index:2;left:-4px;bottom:93px;width:8px;height:17px;border-radius:60% 40% 55% 45%;background:linear-gradient(#fff8c7 0 21%,#ffbd4a 33%,#db4b27 70%,transparent);filter:drop-shadow(0 0 6px #ff8a38);animation:waxFlicker .48s ease-in-out infinite alternate}.fx-wax-figure b{position:absolute;z-index:4;left:-35px;bottom:108px;width:70px;padding:2px 3px;border:1px solid #fff0a5;border-radius:4px;color:#42280d;background:#b8772be8;box-shadow:0 1px #4b2711,0 0 7px #e7bd54;font:900 6px/1 Arial,sans-serif;letter-spacing:.45px;text-align:center;white-space:nowrap}.fx-wax-figure>i{position:absolute;z-index:5;left:25px;bottom:103px;color:#fff5bb;font-size:11px;font-style:normal;text-shadow:0 1px #5d3616,0 0 5px #e7bd54}.fx-wax-figure.melting{opacity:0;filter:blur(2px);transition:transform .4s ease-in,opacity .35s ease-in,filter .3s}
@keyframes waxFigurePulse{from{transform:scale(.86);opacity:.54}to{transform:scale(1.1);opacity:.94}}

/* Mastery gets a full-screen payoff rather than disappearing among ordinary
   material toasts. It remains tap-to-dismiss and clears itself quickly. */
.mastery-levelup{position:fixed;z-index:2000;inset:0;display:grid;place-items:center;padding:22px;pointer-events:auto;background:radial-gradient(circle at 50% 42%,#ffda7b33,transparent 34%),#080a12a8;animation:masteryFade .22s both}.mastery-levelup article{position:relative;overflow:hidden;width:min(340px,100%);padding:19px 16px 16px;border:2px solid #ffe19a;border-radius:18px;color:#fff7db;text-align:center;background:linear-gradient(145deg,#48233b,#151a3b 52%,#132739);box-shadow:0 18px 55px #000b,inset 0 1px #fff7;animation:masteryRise .52s cubic-bezier(.16,.9,.24,1.16) both}.mastery-levelup article:before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(135deg,#fff1 0 2px,transparent 2px 12px);pointer-events:none}.mastery-levelup small{position:relative;color:#ffd979;font-size:8px;font-weight:1000;letter-spacing:2px}.mastery-medal{position:relative;margin:3px auto -2px;font-size:54px;line-height:1;filter:drop-shadow(0 4px 4px #2a0f34);animation:masteryMedal .8s .18s both}.mastery-levelup h2{position:relative;margin:0;color:#fff6c9;font:1000 29px Georgia,serif;letter-spacing:1px;text-shadow:0 3px #4a2041}.mastery-levelup p{position:relative;margin:2px 0 12px;color:#bedfff;font-size:8px;font-weight:1000;letter-spacing:1px}.mastery-rewards{position:relative;display:flex;flex-wrap:wrap;justify-content:center;gap:5px}.mastery-rewards span{padding:4px 6px;border:1px solid #ffe49a77;border-radius:6px;color:#fff4d3;background:#0811248c;font-size:9px;font-weight:1000}.mastery-rewards i{margin-right:3px;font-size:12px;font-style:normal}.mastery-burst{position:absolute;width:360px;height:360px;border-radius:50%;background:repeating-conic-gradient(from 0deg,#ffe9a344 0 4deg,transparent 4deg 14deg);animation:masteryBurst 1.1s both}.mastery-levelup.leaving{animation:masteryOut .24s both}.mastery-levelup.leaving article{animation:masteryDrop .24s both}@keyframes masteryFade{from{opacity:0}to{opacity:1}}@keyframes masteryRise{from{opacity:0;transform:translateY(30px) scale(.7)}to{opacity:1;transform:none}}@keyframes masteryMedal{0%{transform:scale(0) rotate(-25deg)}62%{transform:scale(1.25) rotate(8deg)}100%{transform:none}}@keyframes masteryBurst{from{opacity:0;transform:scale(.45) rotate(-20deg)}35%{opacity:1}to{opacity:0;transform:scale(1.22) rotate(32deg)}}@keyframes masteryOut{to{opacity:0}}@keyframes masteryDrop{to{opacity:0;transform:translateY(15px) scale(.92)}}

/* ---------- Home command hub ---------- */
