.mastery-levelup.compact article:before,.mastery-levelup.compact .mastery-burst,.mastery-levelup.compact .mastery-medal{display:none}
.mastery-levelup.compact small{font-size:7px;letter-spacing:1.2px}.mastery-levelup.compact h2{margin:2px 0 0;font-size:16px;letter-spacing:.4px}.mastery-levelup.compact p{margin:2px 0 6px;font-size:7px;letter-spacing:.5px}.mastery-levelup.compact .mastery-rewards{justify-content:flex-start;gap:3px}.mastery-levelup.compact .mastery-rewards span{padding:3px 5px;font-size:8px}.mastery-levelup.compact .mastery-rewards i{font-size:10px}
