.eightball-liquid{width:42px;height:42px;border-radius:50%;background:radial-gradient(circle at 50% 50%,#0c1b33,#050b16 80%);border:2px solid #1a2a44;box-shadow:inset 0 0 10px #000,0 0 10px var(--fortune-col,#ffe27a);display:grid;place-items:center;position:relative}
