.toodles-live-hammer.impact{opacity:1;transform:rotate(24deg) scale(1.08);transition:transform .12s,opacity .25s}
.hammer-head{position:absolute;left:0;top:0;width:48px;height:24px;border-radius:6px;border:2.5px solid #2a1122;background:linear-gradient(180deg,#ff4d6d,#c9184a);box-shadow:inset 0 2px #fff9,0 3px 6px #0008}
.hammer-head:before,.hammer-head:after{content:"";position:absolute;top:1px;width:7px;height:18px;border-radius:3px;background:#ffd166;border:1.5px solid #2a1122}
