.gourdy-mega-pumpkin{position:absolute;z-index:14;width:76px;height:76px;pointer-events:none;display:grid;place-items:center;opacity:0;transform:scale(.5);transition:transform .28s cubic-bezier(.17,1.5,.3,1),opacity .2s}
