/* Mrs. Holloway Spectral Spiral Vortex */
.mrs-holloway-spiral-vortex{position:absolute;z-index:14;border-radius:50%;pointer-events:none;opacity:0;will-change:transform,opacity;display:grid;place-items:center}
.spiral-vortex-core{position:absolute;inset:0;border-radius:50%;background:radial-gradient(circle,#fff 0%,#f3e8ff 8%,#c070edaa 28%,#7928ca55 58%,transparent 78%);box-shadow:0 0 35px #c070f0,0 0 70px #a855f766,inset 0 0 25px #fff;animation:vortexPulse .6s ease-in-out infinite alternate}
.spiral-vortex-ring{position:absolute;border-radius:50%;border:3px dashed #d8b4fe;box-shadow:0 0 18px #a855f7,0 0 34px #a855f755;animation:vortexSpin 1.8s linear infinite}
