@keyframes vortexSpin{to{transform:rotate(1turn)}}
@keyframes vortexPulse{0%{transform:scale(.92);opacity:.8}100%{transform:scale(1.08);opacity:1}}
.mrs-holloway-spiral-vortex.active{opacity:1;transition:transform .4s cubic-bezier(.16,1.3,.3,1),opacity .25s}
.mrs-holloway-spiral-vortex.leaving{opacity:0;transform:scale(1.3) rotate(180deg);transition:transform .3s ease-in,opacity .25s}

