.mrs-holloway-apparition{position:absolute;z-index:13;width:120px;height:160px;pointer-events:none;transform-origin:50% 90%;opacity:0;transform:scale(.5) translateY(20px);filter:drop-shadow(0 0 24px #a855f7) drop-shadow(0 0 45px #c084fc)}
