/* ==== shelly-fx.css ==== */
/* Shelly: inked field-notebook effects */
.sh-fx{position:absolute;z-index:14;pointer-events:none;opacity:0;transition:opacity .25s}
.sh-fx.on{opacity:1}.sh-fx.off{opacity:0}
.sh-fx svg{display:block;overflow:visible}
.sh-draw{stroke-dasharray:1;stroke-dashoffset:1}
.sh-fx.on .sh-draw{animation:shDraw .55s ease-out var(--d,0s) forwards}
.sh-chalk.on .sh-draw{animation-duration:.9s}
@keyframes shDraw{to{stroke-dashoffset:0}}
.sh-layer{transform-box:fill-box;transform-origin:center;transform:scale(.1);opacity:0}
.sh-fx.on .sh-layer{animation:shLayer .5s cubic-bezier(.2,1.3,.4,1) var(--d,0s) forwards}
@keyframes shLayer{60%{opacity:1}to{transform:scale(1);opacity:1}}
.sh-dig{transition:opacity .45s}
.sh-dig.on{animation:shShake .35s .05s}
@keyframes shShake{25%{transform:translateY(-3px)}60%{transform:translateY(2px)}}
.sh-ammo{opacity:0}.sh-fx.on .sh-ammo{animation:shFade .3s .45s forwards}
@keyframes shFade{to{opacity:1}}
.sh-wave{opacity:0;stroke-dasharray:90;stroke-dashoffset:90;transform-box:fill-box;transform-origin:left center}
.sh-fx.on .sh-wave{animation:shWave .7s ease-out var(--d,0s) forwards}
@keyframes shWave{0%{opacity:1;stroke-dashoffset:90;transform:scale(.7)}60%{opacity:1;stroke-dashoffset:0}100%{opacity:0;stroke-dashoffset:0;transform:scale(1.25)}}
.sh-pop{opacity:0;transform-box:fill-box;transform-origin:center}
.sh-fx.on .sh-pop{animation:shPop .55s ease-out var(--d,0s) forwards}
@keyframes shPop{0%{opacity:0;transform:scale(.2)}30%{opacity:1;transform:scale(1.15)}100%{opacity:0;transform:scale(1) translateY(-4px)}}
.sh-chalk.on{animation:shBreathe 2.4s ease-in-out infinite}
@keyframes shBreathe{50%{opacity:.62}}
.sh-amber{transform:translateY(-70px) rotate(-8deg) scale(.9)}
.sh-amber.on{transform:none;transition:transform .5s cubic-bezier(.3,1.5,.5,1),opacity .2s}
.sh-amber.off{transform:translateY(-10px) scale(1.06);transition:transform .3s,opacity .3s}
.sh-glint{stroke-dasharray:40;stroke-dashoffset:40}
.sh-fx.on .sh-glint{animation:shDraw .5s .35s ease-out forwards}
.sh-lens{transform:translate(-30px,12px) rotate(-25deg)}
.sh-lens.on{transform:none;transition:transform .45s cubic-bezier(.3,1.4,.5,1),opacity .2s;animation:shScan .9s .3s ease-in-out}
@keyframes shScan{30%{transform:translate(7px,-4px) rotate(5deg)}65%{transform:translate(-5px,3px) rotate(-4deg)}}

