/* ==== home-hub-v2.css ==== */
/* Home Base: the team is present, useful, and visibly heading out together. */
.home-hub.home-hub-enter{animation:homeHubIn .42s cubic-bezier(.16,1.3,.3,1) both}.home-hub.home-hub-leaving{pointer-events:none;animation:homeHubOut .36s cubic-bezier(.55,0,.8,.35) both}.home-hub.home-hub-leaving .home-stage-toon{animation:homeToonLeave .28s calc(var(--home-i) * .035s) ease-in forwards}.home-hub.home-hub-leaving .home-stage-next{animation:homeSignLeave .25s ease-in forwards}.home-stage{height:224px!important;border:4px solid #172825!important;border-radius:19px!important;background:linear-gradient(180deg,#8de0dc 0 43%,#64bf75 43% 100%)!important;box-shadow:inset 0 0 0 3px #fff5b0,inset 0 0 0 7px #ffffff55,0 6px 0 #25493b,0 11px 20px #0d201b77!important}.home-stage:after{z-index:1!important;background:linear-gradient(90deg,#12353277,transparent 39%,#1d573544),linear-gradient(0deg,#173d2b66 0 5%,transparent 31%)!important}.home-stage-sky,.home-stage-floor{position:absolute;inset:0;pointer-events:none}.home-stage-sky{z-index:-2;background:radial-gradient(ellipse at 15% 14%,#fff 0 8%,transparent 9%),radial-gradient(ellipse at 77% 22%,#fff9 0 5%,transparent 6%),linear-gradient(180deg,#a4eced,#63cbd0 55%,transparent 56%)}.home-stage-floor{z-index:-1;top:43%;background:repeating-linear-gradient(90deg,#ffffff20 0 2px,transparent 2px 29px),repeating-linear-gradient(0deg,#2c81461c 0 2px,transparent 2px 19px),linear-gradient(180deg,#a6e876,#55ac65 58%,#317b4a);transform:perspective(220px) rotateX(12deg);transform-origin:top}.home-stage-rays{z-index:0!important;inset:-45% -25%!important;opacity:.7;background:repeating-conic-gradient(from 10deg at 61% 88%,#fff8 0 4deg,transparent 4deg 14deg)!important;animation:homeRays 23s linear infinite}.home-stage-sign{position:absolute;z-index:5;left:10px;top:10px;display:grid;gap:1px;padding:5px 10px 5px 7px;border:3px solid #172825;border-radius:6px 14px 14px 6px;background:linear-gradient(180deg,#f25441,#c73029);box-shadow:2px 3px #70261e;color:#fff9a7;text-align:left;transform:rotate(-1deg)}.home-stage-sign b{font:1000 9px/1 'Arial Black',Arial,sans-serif;letter-spacing:.7px}.home-stage-sign small{font-size:5px;font-weight:1000;letter-spacing:1.1px}.home-stage-copy{z-index:5!important;left:13px!important;top:56px!important;gap:2px!important;text-shadow:1px 2px #193d2e!important}.home-stage-copy small{color:#205a48!important;font-size:7px!important;text-shadow:1px 1px #eaffcb}.home-stage-copy b{color:#fff7aa;font:1000 clamp(17px,5vw,26px)/.96 'Arial Black',Arial,sans-serif!important;letter-spacing:-.8px!important;text-shadow:2px 2px #17352b,-1px -1px #17352b}.home-stage-copy span{color:#f1ffdc!important;font-size:8px!important;text-shadow:1px 1px #20563a}.home-stage-party{position:absolute;z-index:4;right:8px;bottom:14px;width:58%;height:170px;pointer-events:none}.home-stage-toon{position:absolute;bottom:0;left:calc((var(--home-i) * 17%) + 2%);width:clamp(52px,14vw,82px);height:156px;display:grid;grid-template-rows:1fr auto;align-items:end;justify-items:center;filter:drop-shadow(3px 5px 0 #17352b) drop-shadow(0 7px 4px #18372277);animation:homeToonArrive .56s calc(var(--home-i) * .1s + .06s) cubic-bezier(.16,1.5,.3,1) both,homeToonIdle 2.6s calc(var(--home-i) * -.32s) ease-in-out infinite}.home-stage-toon:nth-child(2n){bottom:5px}.home-stage-toon:nth-child(3n){bottom:12px}.home-stage-toon.lead{z-index:3;width:clamp(64px,18vw,102px);height:178px;left:calc((var(--home-i) * 16%) + 2%);animation-delay:calc(var(--home-i) * .1s + .06s),-.4s}.home-stage-toon img{width:100%;height:138px;object-fit:contain;object-position:center bottom}.home-stage-toon.lead img{height:160px}.home-stage-toon b{max-width:94%;overflow:hidden;padding:2px 5px;border:2px solid #17352b;border-radius:7px;background:#fff9df;color:#23432f;font-size:6px;text-overflow:ellipsis;white-space:nowrap;box-shadow:1px 2px #2d7645;text-shadow:none}.home-stage-dashboard{position:absolute;z-index:6;left:12px;bottom:12px;display:flex;gap:5px}.home-stage-dashboard>span{display:grid;gap:1px;min-width:56px;padding:4px 6px;border:2px solid #17352b;border-radius:7px;background:#fff9d9e8;box-shadow:1px 2px #2d7545;text-align:left}.home-stage-dashboard small{color:#4b7251;font-size:5px;font-weight:1000;letter-spacing:.65px}.home-stage-dashboard b{color:#d44230;font:1000 10px/1 'Arial Black',Arial,sans-serif}.home-stage-next{position:absolute;z-index:7;right:9px;top:10px;display:grid;gap:1px;min-width:93px;padding:5px 7px;border:3px solid #17352b;border-radius:8px;background:linear-gradient(180deg,#fff37a,#f2bd43);box-shadow:2px 3px #7a3422;color:#243a2c;text-align:left;transform:rotate(1deg)}.home-stage-next small{color:#a5382d;font-size:5px;font-weight:1000;letter-spacing:.9px}.home-stage-next b{font:1000 10px/1 'Arial Black',Arial,sans-serif;white-space:nowrap}.home-stage-next em{color:#46624a;font-size:6px;font-style:normal;white-space:nowrap}.home-stage-edit{z-index:8!important;right:9px!important;bottom:10px!important;top:auto!important;padding:5px 7px!important;border:3px solid #17352b!important;border-radius:7px!important;background:linear-gradient(180deg,#4bc5d5,#2581a0)!important;box-shadow:2px 3px #175267!important;color:#fff!important;font-size:6px!important;text-shadow:1px 1px #185469}.home-stage-edit b{font-size:12px;line-height:.4}.home-spark{z-index:2!important;background:#fff5a6!important;box-shadow:0 0 9px #fff!important}.home-spark.a{right:45%;top:30%}.home-spark.b{right:22%;top:41%}.home-spark.c{right:62%;top:22%;animation-delay:-1.1s}@keyframes homeHubIn{from{opacity:0;transform:translateY(16px) scale(.985)}to{opacity:1;transform:none}}@keyframes homeHubOut{to{opacity:0;transform:translateY(-18px) scale(1.015);filter:brightness(1.15)}}@keyframes homeToonArrive{from{opacity:0;transform:translateX(74px) translateY(18px) scale(.6) rotate(8deg)}to{opacity:1;transform:none}}@keyframes homeToonIdle{0%,100%{translate:0 0;rotate:0deg}50%{translate:0 -4px;rotate:-1deg}}@keyframes homeToonLeave{to{opacity:0;transform:translateX(145px) translateY(-7px) rotate(11deg)}}@keyframes homeSignLeave{to{opacity:0;transform:translateY(-18px) rotate(8deg)}}
@media(max-width:560px){.home-stage{height:214px!important}.home-stage-party{right:3px;width:60%;height:160px}.home-stage-toon{width:clamp(46px,14vw,65px);height:146px}.home-stage-toon img{height:128px}.home-stage-toon.lead{width:clamp(56px,17vw,81px);height:164px}.home-stage-toon.lead img{height:146px}.home-stage-dashboard{bottom:10px;left:9px}.home-stage-dashboard>span{min-width:49px;padding:3px 4px}.home-stage-next{right:7px;top:8px;min-width:83px}.home-stage-copy{left:10px!important;top:53px!important}.home-stage-edit{right:7px!important;bottom:8px!important}}
@media(max-width:390px){.home-stage{height:202px!important}.home-stage-party{height:148px;width:61%}.home-stage-toon{width:45px;height:134px}.home-stage-toon img{height:118px}.home-stage-toon.lead{width:55px;height:150px}.home-stage-toon.lead img{height:132px}.home-stage-copy b{font-size:17px!important}.home-stage-dashboard>span:nth-child(2){display:none}.home-stage-next{min-width:75px}.home-stage-next b{font-size:8px}}
@media(prefers-reduced-motion:reduce){.home-hub.home-hub-enter,.home-hub.home-hub-leaving,.home-stage-toon,.home-stage-rays{animation:none!important}}
.home-stage-toon,.home-stage-toon.lead{left:var(--home-left)}
.home-stage-toon{animation-delay:var(--home-in),var(--home-idle)}.home-stage-toon.lead{animation-delay:var(--home-in),-.4s}.home-hub.home-hub-leaving .home-stage-toon{animation-delay:var(--home-out)}
.home-stage-toon{animation:homeToonArrive .56s var(--home-in) cubic-bezier(.16,1.5,.3,1) both,homeToonIdle 2.6s var(--home-idle) ease-in-out infinite}.home-stage-toon.lead{animation:homeToonArrive .56s var(--home-in) cubic-bezier(.16,1.5,.3,1) both,homeToonIdle 2.6s -.4s ease-in-out infinite}.home-hub.home-hub-leaving .home-stage-toon{animation:homeToonLeave .28s var(--home-out) ease-in forwards}

/* ==== mode-unlocks.css ==== */
/* Progressive mode unlocks keep the early Home hub readable. */
#navbar button.locked{position:relative;opacity:.48;filter:grayscale(.7)}
#navbar button.locked:after{content:"🔒";position:absolute;right:4px;top:3px;font-size:8px;text-shadow:0 1px #000}
.home-play-card.locked,.home-grow-card.locked{filter:grayscale(.7) brightness(.72)}
.home-collect-card.locked{filter:grayscale(.7) brightness(.72);opacity:.72}
.home-play-card.locked>em,.home-grow-card.locked>em{font-size:11px;color:#e8d87d}
.collection-action.locked{filter:grayscale(.75) brightness(.78);opacity:.72}
#modalBox.mode-gate-shell{width:min(92vw,355px);padding:0;overflow:hidden;border-color:#1b2d21;background:linear-gradient(145deg,#415443,#18231d)}
.mode-gate-modal{padding:20px 17px 16px;color:#f7f7e9;text-align:center;background:radial-gradient(circle at 50% 0,#e5ff9a2b,transparent 35%),repeating-linear-gradient(135deg,#fff1 0 2px,transparent 2px 13px)}
.mode-gate-modal>i{display:grid;place-items:center;width:58px;height:58px;margin:0 auto 5px;border:3px solid #1c3323;border-radius:50%;background:#dfff96;box-shadow:0 4px #101a12;color:#263b28;font-size:27px;font-style:normal}
.mode-gate-modal small{display:block;color:#deff8c;font-size:7px;font-weight:1000;letter-spacing:1.6px}
.mode-gate-modal h2{margin:5px 0;color:#fff5c9;font:1000 18px/1.05 "Arial Black",sans-serif}
.mode-gate-modal p{margin:0;color:#d8e4d8;font-size:8px;font-weight:800;line-height:1.4}
.mode-gate-modal .bar{height:11px;margin:12px 0}
.mode-gate-modal .btn{min-height:37px}

/* ==== shop.css ==== */
/* Character-led storefront layered over the existing game UI. */
.shop-screen{
  --shop-cream:#fff5d7;
  --shop-red:#e94c54;
  --shop-yellow:#ffd865;
  --shop-green:#6fd691;
  position:relative;min-height:100%;margin:-10px -10px -18px;padding-bottom:24px;
  background:
    linear-gradient(90deg,rgba(36,17,10,.16) 1px,transparent 1px) 0 0/44px 44px,
    linear-gradient(rgba(36,17,10,.12) 1px,transparent 1px) 0 0/44px 44px,
    linear-gradient(180deg,#a76f48 0 198px,#26202a 198px);
}
/* Keep the storefront flush with the navigation; the shared navbar normally
   draws a green-grey inset highlight along its top edge. */
#app:has(.shop-screen) #navbar{box-shadow:none}
.shop-stage{position:relative;height:226px;overflow:hidden;border-bottom:5px solid #100c0d;
  background:
    radial-gradient(circle at 12% 17%,#ffe491 0 3px,#ffae43 4px 6px,transparent 7px),
    radial-gradient(circle at 31% 12%,#a9efff 0 3px,#48a8d3 4px 6px,transparent 7px),
    radial-gradient(circle at 52% 15%,#ffef8a 0 3px,#ffae43 4px 6px,transparent 7px),
    radial-gradient(circle at 76% 10%,#ff8fa0 0 3px,#d54354 4px 6px,transparent 7px),
    linear-gradient(180deg,#513626 0 8px,transparent 8px),
    linear-gradient(115deg,transparent 48%,rgba(255,255,255,.06) 49% 51%,transparent 52%),
    linear-gradient(180deg,#a97149,#7f4f35);
}
.shop-stage:before{content:"";position:absolute;left:-12px;right:-12px;bottom:0;height:37px;
  background:repeating-linear-gradient(92deg,#4a2a20 0 55px,#2b1916 56px 59px,#60382a 60px 112px);
  border-top:4px solid #160e0c;box-shadow:inset 0 5px #9b6040}
.shop-stage:after{content:"";position:absolute;left:11px;top:58px;width:118px;height:70px;
  border:8px solid #2c1b16;border-radius:4px;background:
  radial-gradient(ellipse at 21px 45px,#6ad187 0 13px,transparent 14px),
  radial-gradient(ellipse at 58px 42px,#e5a641 0 14px,transparent 15px),
  radial-gradient(ellipse at 94px 44px,#8bc6e9 0 13px,transparent 14px),
  linear-gradient(#5a382a 60%,#281a18 61% 66%,#83563a 67%);
  box-shadow:0 5px 0 #382119;opacity:.88}
.shop-sign{position:absolute;z-index:4;top:13px;left:50%;transform:translateX(-50%) rotate(-1deg);
  width:166px;padding:5px 12px 7px;text-align:center;color:#fff7db;letter-spacing:1.5px;
  background:linear-gradient(180deg,#262227,#0e0d10);border:4px solid #080709;border-radius:5px;
  box-shadow:inset 0 0 0 2px #5e565e,0 5px 0 #3c251c;font-size:15px;line-height:1}
.shop-sign small{display:block;margin-top:3px;color:var(--shop-yellow);font-size:7px;letter-spacing:2.4px}
.shop-counter{position:absolute;z-index:2;right:-10px;bottom:22px;width:68%;height:51px;transform:skewX(-5deg);
  background:linear-gradient(180deg,#ac7044 0 16%,#6e402d 17% 73%,#4a2b25 74%);
  border:4px solid #1e1211;box-shadow:inset 0 4px #e3a166,0 7px 0 #251513}
.shopkeeper{position:absolute;z-index:3;left:16px;bottom:24px;height:160px;transform-origin:50% 100%;
  filter:drop-shadow(0 3px 0 #21140f) drop-shadow(0 11px 9px rgba(26,12,8,.55));
  animation:keeperIdle 3.4s ease-in-out infinite}
.shop-screen.talking .shopkeeper{animation:keeperTalk .34s ease-in-out infinite alternate}
.shop-screen.awaiting-intro .shopkeeper,.shop-screen.awaiting-intro .shopkeeper-shadow{opacity:0}
.shop-screen.awaiting-intro .shop-dialogue{opacity:0;transform:translateY(-8px) scale(.96)}
.shop-screen.entering .shopkeeper{animation:keeperEnter 1.65s cubic-bezier(.16,.84,.25,1.12) both}
.shop-screen.entering .shopkeeper-shadow{animation:shadowEnter 1.2s .15s ease-out both}
.shop-screen.entering .shop-dialogue{animation:bubbleEnter .42s .64s cubic-bezier(.2,1.4,.4,1) both}
@keyframes keeperIdle{0%,100%{transform:translateY(0) rotate(-1deg)}50%{transform:translateY(-5px) rotate(1deg)}}
@keyframes keeperTalk{from{transform:translateY(0) rotate(-2deg) scaleY(1)}to{transform:translateY(-4px) rotate(2deg) scaleY(1.025)}}
@keyframes keeperEnter{0%{opacity:0;transform:translateX(-120px) translateY(35px) rotate(-18deg) scale(.65)}48%{opacity:1;transform:translateX(8px) translateY(-22px) rotate(7deg) scale(1.06)}72%{transform:translateX(-3px) translateY(2px) rotate(-3deg) scale(.97)}100%{opacity:1;transform:translate(0) rotate(-1deg) scale(1)}}
@keyframes shadowEnter{from{opacity:0;transform:scale(.2)}to{opacity:1;transform:scale(1)}}
@keyframes bubbleEnter{from{opacity:0;transform:translateY(-8px) scale(.9)}to{opacity:1;transform:none}}
.shopkeeper-shadow{position:absolute;z-index:2;left:20px;bottom:21px;width:120px;height:20px;border-radius:50%;background:#160f0dbb;filter:blur(4px)}
.shop-arrival-fx{position:absolute;z-index:4;left:80px;bottom:75px;width:1px;height:1px;pointer-events:none}
.shop-arrival-fx i{position:absolute;width:9px;height:15px;border-radius:100% 0 100% 0;background:#ffe36d;opacity:0}
.shop-arrival-fx i:nth-child(2){background:#ef5968;transform:rotate(70deg)}.shop-arrival-fx i:nth-child(3){background:#69d891;transform:rotate(140deg)}.shop-arrival-fx i:nth-child(4){background:#7fc8ff;transform:rotate(210deg)}.shop-arrival-fx i:nth-child(5){background:#bd83ef;transform:rotate(280deg)}
.shop-screen.entering .shop-arrival-fx i{animation:petalPop .85s .3s ease-out both}.shop-screen.entering .shop-arrival-fx i:nth-child(2){--x:48px;--y:-38px;animation-delay:.36s}.shop-screen.entering .shop-arrival-fx i:nth-child(3){--x:54px;--y:24px;animation-delay:.29s}.shop-screen.entering .shop-arrival-fx i:nth-child(4){--x:-38px;--y:-42px;animation-delay:.4s}.shop-screen.entering .shop-arrival-fx i:nth-child(5){--x:-46px;--y:19px;animation-delay:.33s}
@keyframes petalPop{0%{opacity:0;transform:translate(0) scale(.2) rotate(0)}25%{opacity:1}100%{opacity:0;transform:translate(var(--x,0),var(--y,-55px)) scale(1) rotate(190deg)}}
.shop-dialogue{position:absolute;z-index:5;top:64px;right:12px;width:61%;min-height:90px;padding:14px 15px 12px 17px;
  color:#282127;background:var(--shop-cream);border:4px solid #100e11;border-radius:14px;
  box-shadow:inset 0 0 0 2px #fff,0 5px 0 #472d25,0 10px 22px #2a141174}
.shop-dialogue:after{content:"";position:absolute;left:-17px;bottom:16px;width:26px;height:23px;background:var(--shop-cream);
  border-left:4px solid #100e11;border-bottom:4px solid #100e11;transform:rotate(40deg);border-radius:0 0 0 5px}
.shop-speaker{position:relative;z-index:1;color:#b43e49;font-size:8px;letter-spacing:1.4px;margin-bottom:5px}
.shop-speech{position:relative;z-index:1;min-height:42px;font-size:13px;line-height:1.28;font-weight:900}
.shop-caret{display:inline-block;width:7px;height:12px;margin-left:2px;vertical-align:-2px;background:#b43e49;animation:shopBlink .7s steps(1) infinite}
@keyframes shopBlink{50%{opacity:0}}
.sr-only{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}.shop-skip-link{position:absolute;z-index:50;left:8px;top:8px;padding:8px 10px;border:3px solid #161013;border-radius:8px;color:#261b16;background:#ffe98b;box-shadow:0 3px #161013;font-size:10px;font-weight:900;transform:translateY(-150%);transition:transform .12s}.shop-skip-link:focus{transform:none}.shop-tab:focus-visible,.shop-refresh:focus-visible,.shop-buy:focus-visible,.shop-upgrade-btn:focus-visible,.gossip-actions button:focus-visible,.gossip-view-tabs button:focus-visible,.gossip-filter:focus-visible,.gossip-case-card:focus-visible,.gossip-toon:focus-visible,.gossip-dandy-take:focus-visible,.gossip-case-close:focus-visible{outline:3px solid #fff4a6;outline-offset:3px;position:relative;z-index:30}

.shop-tabs{position:relative;z-index:7;display:grid;grid-template-columns:repeat(6,1fr);gap:6px;padding:8px 9px 9px;
  background:linear-gradient(180deg,#171318,#29232b);border-bottom:3px solid #0c0a0d;box-shadow:0 5px 12px #0b080a88}
.shop-tab{min-width:0;padding:8px 2px 7px;border:3px solid #0a090b;border-radius:9px;color:#d8d0d5;
  background:linear-gradient(180deg,#4d4651,#29262d);box-shadow:inset 0 2px #fff2,0 3px #0d0b0e;transition:.12s}
.shop-tab i{display:block;font-style:normal;font-size:20px;line-height:1;margin-bottom:3px}.shop-tab span{display:block;font-size:8px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.shop-tab:active{transform:translateY(3px);box-shadow:inset 0 2px #fff2,0 0 #0d0b0e}
.shop-tab.on{color:#2b2020;background:linear-gradient(180deg,#fff0a4,#e5a948);border-color:#21130d;box-shadow:inset 0 2px #fff9,0 3px #4e2e1c}
.shop-tab[data-shop-tab="packs"]{color:#ffcf8c}.shop-tab[data-shop-tab="packs"].on{color:#302116;background:linear-gradient(180deg,#ffe7a1,#ef9d4b);border-color:#4d2815}

.shop-stock{padding:12px 10px 4px;background:
  radial-gradient(circle at 50% 0,#534551 0,transparent 55%),
  repeating-linear-gradient(135deg,#302a33 0 12px,#2b252e 12px 24px)}
.shop-stock-head{display:flex;align-items:center;gap:9px;margin-bottom:10px}.shop-stock-head>div:first-child{flex:1}
.shop-eyebrow{font-size:8px;color:#ffd66a;letter-spacing:1.7px}.shop-stock-title{margin:0;font-size:18px;line-height:1.1;color:#fff9ed}
.shop-stock-tools{display:flex;align-items:center;gap:8px}.shop-refresh{padding:6px 7px;border:3px solid #11202b;border-radius:9px;color:#102333;background:linear-gradient(180deg,#b7efff,#67bddd);box-shadow:inset 0 2px #fff9,0 3px #100d10;font-size:8px;font-weight:900;white-space:nowrap}.shop-refresh:active{transform:translateY(3px);box-shadow:inset 0 2px #fff9,0 0 #100d10}.shop-refresh small{display:block;margin-top:2px;font-size:6px;opacity:.72;letter-spacing:.5px}
.shop-rotation{text-align:right;font-size:8px;color:#c8bcc6}.shop-rotation b{display:block;color:#84e7a5;font-size:9px}
.shop-rotation small{display:block;margin-top:1px;color:#827b80;font-size:6px;letter-spacing:1px}
.shop-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}
.shop-upgrade{display:flex;align-items:center;gap:10px;margin-bottom:10px;padding:9px 10px;border:3px solid #171016;border-radius:12px;color:#fff7df;background:linear-gradient(135deg,#4d3a4b,#29232f);box-shadow:inset 0 2px #fff2,0 3px #100d10}
.shop-upgrade>div{min-width:0;flex:1}.shop-upgrade small,.shop-upgrade b,.shop-upgrade span{display:block}.shop-upgrade small{color:#ffd66a;font-size:7px;letter-spacing:1.35px}.shop-upgrade b{margin:1px 0;font-size:14px}.shop-upgrade span{color:#d8c9d5;font-size:8px}.shop-upgrade-btn{flex:0 0 auto;padding:7px 8px;border:3px solid #160e0c;border-radius:9px;color:#2c2118;background:linear-gradient(180deg,#9cf08a,#58b65e);box-shadow:inset 0 2px #fff8,0 3px #171016;font-size:8px;font-weight:900}.shop-upgrade-btn:active{transform:translateY(3px);box-shadow:none}.shop-upgrade-btn.cant{filter:grayscale(.7);opacity:.72}
.shop-empty{padding:20px 14px;border:3px dashed #675360;border-radius:12px;color:#d8c9d5;background:#211c25aa;text-align:center;font-size:11px;line-height:1.35}
.shop-item{position:relative;min-width:0;overflow:hidden;border:3px solid #0b090c;border-radius:14px;
