/* ==== trials.css ==== */
/* Trials borrows the reference's tall division-card layout while staying in
   Dandy's Heroes' dark terminal/plastic visual language. */
.trials-screen{
  min-height:100%;margin:-10px -10px -18px;padding:9px 0 14px;
  overflow:hidden;background:
    radial-gradient(circle at 50% -15%,rgba(165,242,71,.13),transparent 38%),
    repeating-linear-gradient(90deg,rgba(255,255,255,.025) 0 1px,transparent 1px 22px)
}
.trials-head{position:relative;text-align:center;padding:2px 12px 10px}
.trials-head h1{font:900 28px/1 "Arial Black","Trebuchet MS",sans-serif;letter-spacing:1px;
  color:#fff;-webkit-text-stroke:4px var(--edge);paint-order:stroke fill;text-shadow:0 4px 0 #080b0c}
.trials-kicker,.trials-sub{font-size:8px;font-weight:900;letter-spacing:2px;color:var(--accent)}
.trials-sub{margin-top:5px;color:var(--dim);letter-spacing:1px}.trials-sub b{color:var(--accent);font-size:9px}

.trial-deck{display:grid;grid-auto-flow:column;grid-auto-columns:clamp(156px,31vw,172px);gap:9px;
  height:clamp(350px,calc(100vh - 220px),470px);padding:3px 10px 12px;overflow-x:auto;overflow-y:hidden;
  scroll-snap-type:x mandatory;overscroll-behavior-x:contain;scroll-padding-left:10px;scrollbar-width:thin}
.trial-card{--trial-accent:#a5f247;--trial-deep:#263032;position:relative;isolation:isolate;overflow:hidden;
  height:100%;scroll-snap-align:start;border:3px solid var(--edge);border-radius:15px;background-color:var(--trial-deep);
  background-size:cover;background-position:center;box-shadow:inset 0 0 0 2px var(--trial-accent),0 5px 0 #090d0e,0 9px 16px #0008}
.trial-card:before{content:"";position:absolute;z-index:-1;inset:0;background:
  repeating-linear-gradient(135deg,rgba(255,255,255,.04) 0 5px,transparent 5px 15px),
  linear-gradient(180deg,transparent 40%,rgba(5,7,8,.9) 77%)}
.trial-card-top{position:absolute;z-index:4;inset:0 0 auto;min-height:66px;padding:14px 32px 8px 10px;
  background:linear-gradient(180deg,rgba(8,10,12,.95),rgba(8,10,12,.72),transparent)}
.trial-card-name{font:900 14px/.98 "Arial Black","Trebuchet MS",sans-serif;text-transform:uppercase;
  text-shadow:0 2px 2px #000;-webkit-text-stroke:2px #080b0c;paint-order:stroke fill}
.trial-card-name small{display:block;margin-top:4px;color:var(--trial-accent);font-size:6px;letter-spacing:1.2px;-webkit-text-stroke:1px #080b0c}
.trial-card-endgame{--trial-accent:#ffbd5d!important;--trial-deep:#3d2021!important;border-color:#ffbd5d!important;box-shadow:inset 0 0 0 2px #ff7d5d,0 5px 0 #090d0e,0 0 18px #ff764a55}
.trial-card-endgame .trial-card-top{background:linear-gradient(180deg,#1c1018f5,#24141cba,transparent)}
.trial-card-endgame .trial-play{background:linear-gradient(180deg,#ffd67a,#e56c4e);color:#241316}
.trial-info{position:absolute;top:9px;right:8px;width:24px;height:24px;border-radius:50%;display:grid;place-items:center;
  color:#121719;background:#e8efec;border:2px solid var(--edge);box-shadow:0 2px 0 #080b0c;font:900 13px/1 Georgia,serif}
.trial-info:active{transform:translateY(2px);box-shadow:none}

.trial-art{position:absolute;z-index:2;left:6px;right:6px;top:57px;bottom:128px;display:grid;place-items:center}
.trial-art img{max-width:98%;max-height:100%;object-fit:contain;filter:saturate(1.08) contrast(1.06)
  drop-shadow(0 2px 1px #000) drop-shadow(0 10px 8px #0009)}
.trial-art.locked img{filter:brightness(0) drop-shadow(0 5px 4px #000)}
.trial-art.locked span{position:absolute;color:#fff;font-size:19px;letter-spacing:2px;text-shadow:0 2px 3px #000}

.trial-card-foot{position:absolute;z-index:3;left:8px;right:8px;bottom:9px;display:flex;flex-direction:column;align-items:center;text-align:center}
.trial-rule{width:100%;height:28px;display:-webkit-box;overflow:hidden;-webkit-line-clamp:2;-webkit-box-orient:vertical;
  color:#fff;font-size:9px;line-height:1.25;text-shadow:0 1px 2px #000}
.trial-count{margin-top:2px;color:var(--trial-accent);font-size:7px;letter-spacing:.8px;text-shadow:0 1px #000}
.trial-progress{display:flex;justify-content:center;gap:3px;margin:7px 0 8px}
.trial-progress i{display:block;width:10px;height:5px;border:1px solid #080b0c;border-radius:3px;background:#202628;box-shadow:inset 0 1px #fff2}
.trial-progress i.done{background:var(--trial-accent)}
.trial-progress i.next{background:#fff;box-shadow:0 0 0 2px var(--trial-accent)}
.trial-play{width:100%;min-height:39px;padding:5px 3px;border:3px solid var(--edge);border-radius:99px;color:#101415;
  background:linear-gradient(180deg,#f8fbfa,#aeb8b4);box-shadow:inset 0 2px #fff,0 3px 0 #080b0c;
  font-size:9px;font-weight:900;letter-spacing:.15px}
.trial-play:active{transform:translateY(3px);box-shadow:inset 0 2px #fff}
.trial-play.need{color:#dce3e0;background:linear-gradient(180deg,#5c6764,#343c3d)}
.trial-swipe{text-align:center;padding-top:8px;color:var(--dim);font-size:7px;letter-spacing:1.4px}
.raid-ticket-quantity{display:grid;gap:10px;min-width:min(82vw,340px);padding:8px 2px 2px;text-align:center;color:#eaf4ee}
.raid-ticket-quantity p{margin:0;font-size:11px;font-weight:900}.raid-ticket-quantity small{color:#aebfba;font-size:8px;line-height:1.35}
.raid-ticket-quantity input{width:100%;padding:10px;border:3px solid var(--edge);border-radius:9px;color:#17201e;background:#f2f7f3;text-align:center;font:900 20px/1 Arial,sans-serif;box-shadow:inset 0 2px #fff,0 3px #080c0d}
.raid-ticket-quantity-actions{display:grid;grid-template-columns:1fr 1.5fr;gap:7px}.raid-ticket-quantity-actions .btn{min-height:38px}
.raid-ticket-batch-stats{display:flex;justify-content:center;flex-wrap:wrap;gap:5px;margin:4px 0 8px}.raid-ticket-batch-stats span{padding:5px 7px;border:2px solid #202b2c;border-radius:6px;color:#dce8e1;background:#202a2b;font-size:8px}.raid-ticket-batch-warning{color:#ffd37b!important}
.trials-beginner{min-height:100%;display:flex;flex-direction:column}.trial-grind-card{position:relative;max-width:440px;margin:22px auto 0;padding:24px 16px 16px;border:3px solid #7be0ff;border-radius:18px;color:#f4fbff;text-align:center;background:radial-gradient(circle at 50% 8%,#7be0ff2c,transparent 32%),linear-gradient(150deg,#21485a,#172b3b 58%,#17212d);box-shadow:inset 0 1px #fff5,0 6px #0a1117,0 0 24px #7be0ff22}.trial-grind-icon{display:grid;place-items:center;width:66px;height:66px;margin:-3px auto 9px;border:3px solid #101a20;border-radius:50%;color:#10222b;background:linear-gradient(145deg,#c7f5ff,#63b8dc);box-shadow:inset 0 2px #fff,0 4px #091219,0 0 18px #7be0ff88;font-size:34px;animation:trialGrindPulse 1.7s ease-in-out infinite}.trial-grind-card>small{color:#aeeaff;font-size:8px;font-weight:1000;letter-spacing:2px}.trial-grind-card h2{margin:5px 0;color:#fff4c8;font:1000 25px/.95 Georgia,serif;letter-spacing:.6px;text-shadow:0 3px #153145}.trial-grind-card p{max-width:320px;margin:0 auto 15px;color:#d4e8ef;font-size:9px;line-height:1.45;font-weight:800}.trial-grind-rewards{display:flex;justify-content:center;flex-wrap:wrap;gap:5px;margin:0 auto 12px}.trial-grind-rewards span{padding:5px 7px;border:1px solid #8edfff66;border-radius:6px;color:#e0f8ff;background:#0e2230aa;font-size:8px;font-weight:1000}.trial-grind-note{margin-bottom:12px;color:#a9c8d2;font-size:7px;letter-spacing:.4px}.trial-grind-play{width:100%;min-height:42px;border:3px solid #0d1820;border-radius:9px;color:#10242c;background:linear-gradient(180deg,#d1f8ff,#63c1df);box-shadow:inset 0 2px #fff9,0 3px #081016;font-size:9px;font-weight:1000;letter-spacing:.8px;cursor:pointer}.trial-grind-play:active{transform:translateY(3px);box-shadow:inset 0 2px #fff9,0 0 #081016}.trial-grind-play:disabled{opacity:.45;cursor:default}@keyframes trialGrindPulse{50%{transform:translateY(-3px);filter:brightness(1.12);box-shadow:inset 0 2px #fff,0 4px #091219,0 0 27px #7be0ffbb}}

/* The info modal is deliberately plain and compact; it carries the controls
   removed from the card deck without turning the main screen into a manual. */
.trial-info-summary{padding:9px;border:2px solid var(--edge);border-radius:10px;background:#252e30}
.trial-info-tags{display:flex;gap:4px;flex-wrap:wrap;margin-bottom:6px}
.trial-info-label{margin:12px 2px 6px;color:var(--dim);font-size:8px;letter-spacing:1.3px}
.trial-ready-heroes{display:flex;align-items:center;gap:5px;min-height:44px;overflow-x:auto;padding:2px}
.trial-ready-heroes img{flex:0 0 auto;width:42px;height:42px;object-fit:contain;border:2px solid var(--edge);border-radius:9px;
  background:linear-gradient(180deg,#4d5857,#293132)}
.trial-stage-list{display:grid;gap:7px;max-height:390px;overflow-y:auto;padding:2px 2px 4px}
.trial-stage-row{display:grid;grid-template-columns:78px minmax(0,1fr) auto;align-items:stretch;min-height:68px;overflow:hidden;border:2px solid var(--edge);border-radius:9px;color:#eaf1ec;text-align:left;background:linear-gradient(105deg,#5b6864,#293334 62%);box-shadow:inset 0 1px #fff3,0 3px #101415;transition:transform .12s,filter .12s}
.trial-stage-row:active{transform:translateY(2px);box-shadow:inset 0 1px #fff3,0 1px #101415}
.trial-stage-row.current{outline:2px solid var(--accent);outline-offset:1px}
.trial-stage-row.done{border-color:#bff56c;background:linear-gradient(105deg,#63734f,#293b31 62%)}
.trial-stage-row:disabled{opacity:.3;filter:grayscale(1);cursor:default}
.trial-stage-thumb{position:relative;display:flex;min-height:68px;align-items:flex-end;justify-content:space-between;padding:5px;background-position:center;background-size:cover;border-right:2px solid #101415}
.trial-stage-thumb:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 35%,#080d0fbb)}
.trial-stage-thumb b,.trial-stage-thumb small{position:relative;z-index:1}
.trial-stage-thumb b{font-size:20px;color:#fff4bd;text-shadow:0 2px #000}
.trial-stage-thumb small{padding:2px 3px;border:1px solid #eaffd288;border-radius:3px;color:#eaffd2;background:#16231bcc;font-size:5px;font-weight:1000;letter-spacing:.4px}
.trial-stage-copy{display:flex;min-width:0;flex-direction:column;justify-content:center;padding:7px 6px}
.trial-stage-copy>b{overflow:hidden;color:#fff;font-size:10px;text-overflow:ellipsis;white-space:nowrap}
.trial-stage-copy>small{margin-top:5px;color:#cbd8d1;font-size:6px;white-space:nowrap}
.trial-stage-copy>small em{color:#bff56c;font-style:normal;font-weight:1000}
.trial-stage-copy>i{margin-top:5px;color:#a7e9bc;font-size:6px;font-style:normal;font-weight:900}
.trial-stage-rewards{display:flex;min-width:58px;flex-direction:column;align-items:center;justify-content:center;gap:3px;padding:4px 5px;border-left:2px solid #ffffff16;background:#17202166}
.trial-stage-rewards>small{color:#bff56c;font-size:5px;font-weight:1000;letter-spacing:.7px}
.trial-stage-rewards>i{display:flex;align-items:center;gap:2px;color:#fff;font-size:13px;font-style:normal;line-height:1}
.trial-stage-rewards>i img{width:14px;height:14px;object-fit:contain}
.trial-stage-rewards>i b{color:#d9e5dc;font-size:5px;font-weight:900}

/* Choose Stage previews the actual rule and win condition of each encounter. */
.trial-stage-action-row{--stage-accent:#bff56c}
.trial-stage-action-row .trial-stage-row{min-height:82px;border-color:var(--stage-accent);background:linear-gradient(105deg,color-mix(in srgb,var(--stage-accent) 25%,#273033),#263034 68%)}
.trial-stage-action-row .trial-stage-thumb{min-height:82px}
.trial-stage-action-row .trial-stage-row.current{outline-color:var(--stage-accent)}
.trial-stage-action-row .trial-stage-thumb b{color:var(--stage-accent)}
.trial-stage-action-row .trial-stage-copy{gap:3px;padding-block:6px}
.trial-stage-action-row .trial-stage-copy>b{font-size:11px}
.trial-stage-action-row .trial-stage-copy>i{display:block;margin-top:2px;color:#dcebe5;font-size:8px;line-height:1.3;font-weight:800;font-style:normal;white-space:normal}
.trial-stage-challenge{display:block;width:max-content;max-width:100%;margin-top:3px;padding:3px 5px;border:1px solid var(--stage-accent);border-radius:4px;color:var(--stage-accent);background:#0a1317c9;font-size:7px;font-weight:1000;line-height:1.3;letter-spacing:.25px;white-space:normal}
.trial-stage-pressure{display:block;margin-top:2px;color:#ffe2a1;font-size:7px;font-weight:900;line-height:1.3;letter-spacing:.2px}
.trial-stage-action-row[data-stage-type="SURVIVAL"] .trial-stage-challenge{animation:trialSurvivalPulse 2.5s ease-in-out infinite}
@keyframes trialSurvivalPulse{50%{box-shadow:0 0 8px var(--stage-accent)}}
.accessibility-reduced-effects .trial-stage-challenge{animation:none!important}
@media(prefers-reduced-motion:reduce){.trial-stage-challenge{animation:none!important}}

@media (max-height:650px){
  .trial-deck{height:350px}
  .trials-head h1{font-size:24px}
}

.trial-stage-action-row{display:grid;grid-template-columns:minmax(0,1fr) 52px;gap:5px;align-items:stretch}
.trial-stage-raid{min-width:0;padding:3px;border:2px solid #d6b94d;border-radius:8px;color:#211c0b;background:linear-gradient(180deg,#fff1a7,#c9a43b);box-shadow:inset 0 1px #fff8,0 2px #101415;font-size:7px;font-weight:1000;line-height:1.05}
.trial-stage-raid small{display:block;margin-top:3px;font-size:6px}.trial-stage-raid:active{transform:translateY(2px);box-shadow:inset 0 1px #fff8,0 0 #101415}.trial-stage-raid:disabled{opacity:.42;filter:grayscale(.7)}
.trial-grind-raid{width:100%;min-height:36px;margin-top:7px;border:2px solid #e4c85d;border-radius:9px;color:#211c0b;background:linear-gradient(180deg,#fff0a2,#d2a93d);box-shadow:inset 0 1px #fff9,0 3px #081016;font-size:8px;font-weight:1000;letter-spacing:.55px;cursor:pointer}.trial-grind-raid:active{transform:translateY(3px);box-shadow:inset 0 1px #fff9,0 0 #081016}.trial-grind-raid:disabled{opacity:.45;cursor:default}
.raid-ticket-running,.raid-ticket-result{text-align:center}.raid-ticket-spinner,.raid-ticket-result-icon{display:grid;place-items:center;width:58px;height:58px;margin:0 auto 8px;border:3px solid #d6b94d;border-radius:50%;color:#211c0b;background:linear-gradient(145deg,#fff1a7,#c9a43b);box-shadow:0 0 18px #f6d35f55;font-size:28px}.raid-ticket-spinner{animation:raidTicketPulse .7s ease-in-out infinite}.raid-ticket-running b,.raid-ticket-result h3{display:block;color:#f6d35f;font-size:13px;letter-spacing:1px}.raid-ticket-running p,.raid-ticket-result p{margin:7px 0;color:var(--dim);font-size:8px;line-height:1.4}.raid-ticket-result-icon.win{color:#172516;background:linear-gradient(145deg,#d8ff9d,#76bb52);border-color:#a5f247}.raid-ticket-result-icon.loss{color:#301719;background:linear-gradient(145deg,#ffb2a8,#bf5e62);border-color:#f27b72}.raid-ticket-rewards{display:grid;gap:5px;margin-top:12px;text-align:left}.raid-ticket-rewards span{padding:5px 7px;border:1px solid #ffffff18;border-radius:6px;color:#e8eee9;background:#202a2b;font-size:8px}.raid-ticket-failure{margin-top:12px;padding:8px;border:2px solid #6e3f42;border-radius:7px;color:#ffc2b5;background:#351e22;font-size:8px;font-weight:900}
@keyframes raidTicketPulse{50%{transform:scale(1.06);filter:brightness(1.15)}}

/* ==== phantasia-event.css ==== */
/* Phantasia's permanent mid-game event: a softer star-gate palette on the
   existing event board, with its own coin exchange identity. */
