.event-banner.qom .event-art{display:block;right:0;bottom:0;width:51%;height:100px;background:linear-gradient(0deg,#15121ca8,transparent 28%),repeating-conic-gradient(#b56ee220 0 25%,#3c225121 0 50%) 50% 80%/26px 26px}
