.event-banner.qom .event-art img:nth-child(3){left:41%;transform:scale(.68);transform-origin:bottom left;z-index:1}
.event-banner.qom .event-art img:nth-child(4){left:57%;transform:scale(.80);transform-origin:bottom left;z-index:3}
.event-banner.qom .event-art img:nth-child(5){left:74%;transform:scale(.85);transform-origin:bottom left;z-index:5}
.event-dossier.qom{margin:8px -4px 0;padding:7px;border:2px solid #b9fa73;background:linear-gradient(160deg,#2e1537,#140e1d 57%,#1b1124);box-shadow:inset 0 0 0 2px #d881ee52,0 4px #0d0713}
.event-dossier.qom .event-dossier-hero{min-height:252px;border:2px solid #ad6ac5;background:radial-gradient(ellipse at 25% 0,#ab4ac465,transparent 47%),radial-gradient(ellipse at 77% 0,#78de6850,transparent 42%),linear-gradient(90deg,#140c1b 0 40%,#271732 65%,#101820);box-shadow:inset 0 0 0 2px #d1f87433,0 3px #100a13}
.event-dossier.qom .event-dossier-hero:after{background:radial-gradient(ellipse at 29% 10%,#ce87ff44,transparent 45%),repeating-linear-gradient(45deg,transparent 0 14px,#c97dea14 14px 28px);opacity:.65}
.event-dossier.qom .event-dossier-art{height:225px;overflow:visible}
.event-dossier.qom .event-dossier-art img{position:absolute;bottom:0;width:auto;height:195px;max-height:195px;max-width:none;object-fit:contain;filter:drop-shadow(0 6px 3px #110a17);transform-origin:bottom left}
.event-dossier.qom .event-dossier-art img:nth-child(1){left:0;transform:scale(.56);z-index:2}
.event-dossier.qom .event-dossier-art img:nth-child(2){left:18%;transform:scale(.82);z-index:4}
.event-dossier.qom .event-dossier-art img:nth-child(3){left:42%;transform:scale(.65);z-index:1}
.event-dossier.qom .event-dossier-art img:nth-child(4){left:56%;transform:scale(.72);z-index:3}
.event-dossier.qom .event-dossier-art img:nth-child(5){left:68%;transform:scale(.78);z-index:5}
.event-dossier.qom .event-dossier-copy small,.event-dossier.qom .event-wave-card span{color:#bdf778}
.event-dossier.qom .event-dossier-copy h1{font-family:'Trebuchet MS',sans-serif;font-style:italic;font-size:25px;color:#f5d7ff;text-shadow:2px 2px #27102c}
.event-dossier.qom .event-dossier-copy p{color:#ead8ee}
.event-dossier.qom .event-dossier-prize{background:#1b1024ef;border-color:#a667c5}.event-dossier.qom .event-dossier-prize b{color:#c8fa84}
.event-dossier.qom .event-stage{background:linear-gradient(180deg,#4a2b55,#24142c);border-color:#a565bd}.event-dossier.qom .event-stage.done{background:linear-gradient(180deg,#d5f695,#8ac254);color:#1a1320}
@media(min-width:680px){.event-dossier.qom .event-stage-grid{grid-template-columns:repeat(6,minmax(0,1fr))}}
.event-dossier.qom .event-wave-card,.event-dossier.qom .event-condition,.event-dossier.qom .event-mechanic{background:linear-gradient(180deg,#4b2d57,#25172e);border-color:#9056a7;box-shadow:inset 0 1px #ffffff2a,0 3px #0d0812}
.event-dossier.qom .event-mechanic b{color:#dbf6a3}.event-dossier.qom .event-dossier-fight{background:linear-gradient(180deg,#d7fb8c,#9bd258);color:#201129;border-color:#35203d}
.event-dossier.qom .event-token-shop{border-color:#9558b1;background:#24142d}.event-dossier.qom .event-shop-head{background:#1a1021}.event-dossier.qom .event-shop-head strong{color:#ccfa88}.event-dossier.qom .event-shop-offer{background:#31203b;border-color:#84539a}.event-dossier.qom .event-shop-offer>img{object-fit:contain}
.qom-trinket-head{margin:15px 0 8px;padding:9px 11px;border-top:1px solid #9857af;color:#d5fb91;font-size:12px;font-weight:900;letter-spacing:.12em}
