.qom-trinket-card{display:flex;align-items:center;gap:10px;min-width:0;padding:10px;background:linear-gradient(135deg,#40234d,#21162b);border:1px solid #9a68ac;box-shadow:inset 0 1px #ffffff24,0 2px #130a1c;border-radius:6px}
.qom-trinket-card>img{width:58px;height:58px;flex:none;object-fit:contain;filter:drop-shadow(0 0 8px #b684f788)}
.qom-trinket-card>div{display:flex;flex-direction:column;align-items:flex-start;gap:5px;min-width:0}.qom-trinket-card b{color:#f8eaff;font-size:13px}.qom-trinket-card small{color:#ceb7d9;font-size:11px;line-height:1.35}.qom-trinket-card.sold{border-color:#abdd7b}
#battle.qom-battle #bgLayer{filter:brightness(.72) saturate(1.18) contrast(1.06)}
