#battle.qom-battle #bgLayer:after{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 50% 50%,transparent 35%,#2d0f49a8 100%),linear-gradient(180deg,#7a27ac33,transparent 42%,#46ba191e);pointer-events:none}
#battle.qom-battle #floorLine{box-shadow:0 0 18px #c96dff,0 0 35px #a2d753}
@media(max-width:700px){.event-status.qom-wallet{display:none}.event-dossier.qom .event-dossier-copy h1{font-size:21px}.event-dossier.qom .event-dossier-art img{height:170px;max-height:170px}}
