/* Stage meter: one compact resource strip per Queen of Mischief. */
.unit .qom-meter{position:absolute;left:50%;transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:1px;pointer-events:none;z-index:3;filter:drop-shadow(0 1px 1px #000)}
.unit .qom-meter .qm-pips{display:flex;gap:2px;padding:2px 3px;border-radius:6px;background:#160b1fd9;border:1px solid #5c2e78}
.unit .qom-meter i{display:block;width:5px;height:5px;border-radius:50%;background:#3b2448;transition:background .12s,box-shadow .12s,transform .12s}
.unit .qom-meter i.on{background:#b9f878;box-shadow:0 0 4px #b9f878}
.unit .qom-meter.hot i.on{background:#e3a6ff;box-shadow:0 0 5px #d17cff}
.unit .qom-meter b{font:1000 6px/1 'Trebuchet MS',Arial,sans-serif;letter-spacing:.6px;color:#f3d9ff;text-shadow:0 0 4px #b35df0,1px 1px #1a0a24;white-space:nowrap}
/* Gourdy: four drum heads, the active beat lights and thumps. */
.unit .qom-meter.drums i{width:8px;height:8px;border-radius:50%;background:radial-gradient(circle at 40% 35%,#5b4566,#2a1834);border:1px solid #6b3f80}
.unit .qom-meter.drums i.on{background:radial-gradient(circle at 40% 35%,#f4ffd9,#a7f05f);transform:scale(1.25)}
.unit .qom-meter.drums.hot i.on{background:radial-gradient(circle at 40% 35%,#fff,#d98cff);transform:scale(1.45)}
.unit .qom-meter.thump .qm-pips{animation:qomThump .22s ease-out}
@keyframes qomThump{0%{transform:scale(1.18)}100%{transform:scale(1)}}
/* Eclipse: an amplifier bar of thin segments. */
.unit .qom-meter.amp .qm-pips{gap:1px}
.unit .qom-meter.amp i{width:3px;height:7px;border-radius:1px}
.unit .qom-meter.amp i.on{background:linear-gradient(0deg,#8ee65b,#f4e481)}
.unit .qom-meter.amp.hot i.on{background:linear-gradient(0deg,#b35df0,#ffd8ff)}
.unit .qom-meter.amp.hot .qm-pips{animation:qomHum .5s ease-in-out infinite alternate}
@keyframes qomHum{to{box-shadow:0 0 7px #c66cff}}
/* Ribecca: little bones. */
.unit .qom-meter.bones i{width:7px;height:3px;border-radius:2px}
/* Soulvester: three sword pips. */
.unit .qom-meter.swords i{width:4px;height:9px;border-radius:2px 2px 1px 1px;clip-path:polygon(50% 0,100% 22%,100% 100%,0 100%,0 22%)}
.unit .qom-meter.swords i.on{background:linear-gradient(0deg,#cdb6ff,#fff6d6);box-shadow:0 0 4px #e3d4ff}
/* Connie: eight phantom notes. */
.unit .qom-meter.notes i{width:4px;height:6px;border-radius:50% 50% 50% 0}
.unit .qom-meter.notes i.on{background:#8cf0da;box-shadow:0 0 4px #8cf0da}
.unit .qom-meter.notes.hot i.on{background:#e4b4ff;box-shadow:0 0 5px #e4b4ff}
html.graphics-lite .unit .qom-meter{filter:none}

/* ==== phantasia-shop.css ==== */
