.phantasia-shop-stage:before{content:"";position:absolute;inset:0;background:repeating-linear-gradient(90deg,#ffffff05 0 2px,transparent 2px 24px),linear-gradient(180deg,transparent 0 71%,#0a0710aa 72%);pointer-events:none}
