.phantasia-shop-vent:before{content:"";position:absolute;left:14px;right:14px;top:-20px;height:49px;border:5px solid #09090d;border-radius:9px 9px 20px 20px;background:repeating-linear-gradient(0deg,#606273 0 5px,#292b38 5px 9px);box-shadow:inset 0 0 0 3px #8d91a455,0 5px 0 #110b16}
