.phantasia-shop-sign{position:absolute;z-index:4;top:20px;left:50%;transform:translateX(-16%);width:190px;padding:9px 12px 8px;border:4px solid #0d0911;border-radius:6px;background:linear-gradient(180deg,#d8a8ff,#8856b5);box-shadow:inset 0 2px #fff8,0 5px #0b0710;text-align:center;color:#24152e}
.phantasia-shop-sign small,.phantasia-shop-sign em{display:block;font-style:normal;font-size:7px;font-weight:900;letter-spacing:1.4px}.phantasia-shop-sign small{color:#fff1ff}.phantasia-shop-sign strong{display:block;margin:2px 0;font:1000 30px/.9 "Arial Black",Arial,sans-serif;letter-spacing:2px;text-shadow:0 2px #f4d7ff}.phantasia-shop-sign em{color:#ffe5ff}
