.phantasia-shop-dialogue small{display:block;color:#754d85;font-size:7px;font-weight:1000;letter-spacing:1.2px}.phantasia-shop-dialogue p{min-height:43px;margin-top:5px;font-size:11px;line-height:1.24;font-weight:900}.phantasia-shop-screen.cheknov-talking .phantasia-shop-dialogue{filter:brightness(1.03)}
.phantasia-shop-wallet{display:flex;align-items:baseline;gap:7px;margin-top:9px;padding:9px 11px;border:2px solid #6d4b91;border-radius:8px;background:linear-gradient(90deg,#392450,#211733);box-shadow:inset 0 1px #fff2,0 3px #100a16}.phantasia-shop-wallet span{color:#efc4ff;font-size:9px;font-weight:1000;letter-spacing:1px}.phantasia-shop-wallet b{color:#ffe181;font-size:18px}.phantasia-shop-wallet small{margin-left:auto;color:#bda9c7;font-size:6px;letter-spacing:.7px}
