/* ==========================================================================
   Character Viewer Quality-of-Life & Visual Enhancements
   ========================================================================== */

/* Top Bar: Hero switcher interaction & currency indicators */
.hero-top-name {
  cursor: pointer;
  user-select: none;
  transition: transform .12s ease, opacity .12s ease;
  padding: 2px 4px;
  border-radius: 6px;
}
.hero-top-name:hover {
  background: rgba(255, 255, 255, 0.05);
  transform: translateY(-1px);
}
.hero-top-name:active {
  transform: translateY(1px);
}
.hero-top-caret {
  display: inline-block;
  font-size: 11px;
  color: var(--accent);
  margin-left: 3px;
  transition: transform .2s ease;
  vertical-align: middle;
}
.hero-top-name:hover .hero-top-caret {
  transform: translateY(1px);
}
@media (min-width: 520px) {
  .hero-top-res {
    display: flex !important;
    align-items: center;
  }
}

/* Quick Hero Search Drawer */
.hero-quick-picker {
  position: absolute;
  z-index: 50;
  inset: 0;
  display: flex;
  flex-direction: column;
  background: rgba(14, 19, 21, 0.94);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  animation: heroQuickPickerIn .22s cubic-bezier(0.16, 1, 0.3, 1) both;
  overflow: hidden;
}
@keyframes heroQuickPickerIn {
  from { opacity: 0; transform: translateY(-16px) scale(0.98); }
  to { opacity: 1; transform: none; }
}
.hero-quick-picker-head {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 14px;
  background: linear-gradient(180deg, #1d2527, #131a1b);
  border-bottom: 2px solid #080b0c;
  box-shadow: 0 3px 10px rgba(0, 0, 0, 0.4);
}
.hero-quick-picker-search {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 10px;
  background: #0b0f10;
  border: 1.5px solid #283435;
  border-radius: 8px;
  box-shadow: inset 0 1px 3px rgba(0, 0, 0, 0.5);
  transition: border-color .15s ease, box-shadow .15s ease;
}
.hero-quick-picker-search:focus-within {
  border-color: #a5f247;
  box-shadow: 0 0 8px rgba(165, 242, 71, 0.35);
}
.hero-quick-picker-search i {
  font-style: normal;
  font-size: 13px;
  opacity: 0.7;
}
.hero-quick-picker-search input {
  flex: 1;
  background: transparent;
  border: 0;
  outline: 0;
  color: #f3f7f5;
  font-size: 12px;
  font-weight: 700;
  font-family: inherit;
}
.hero-quick-picker-close {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border: 2px solid #080b0c;
  border-radius: 50%;
  color: #f3f7f5;
  background: linear-gradient(180deg, #4f5d59, #273130);
  font-size: 20px;
  font-weight: 900;
  cursor: pointer;
  box-shadow: inset 0 1px #fff3, 0 2px #080b0c;
  transition: transform .1s;
}
.hero-quick-picker-close:active {
  transform: translateY(2px);
}
.hero-quick-picker-grid {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(132px, 1fr));
  gap: 8px;
}
.hero-quick-picker-empty {
  grid-column: 1 / -1;
  text-align: center;
  padding: 36px 12px;
  color: #8da199;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.5px;
}
.hero-quick-card {
  --rarity-color: #a5f247;
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 6px 8px;
  border: 2px solid #080b0c;
  border-radius: 9px;
  background: linear-gradient(145deg, #323d3f, #1e2627);
  box-shadow: inset 0 1px rgba(255, 255, 255, 0.1), 0 2px rgba(0, 0, 0, 0.4);
  cursor: pointer;
  text-align: left;
  transition: transform .12s ease, border-color .12s ease, box-shadow .12s ease;
}
.hero-quick-card:hover {
  transform: translateY(-2px);
  border-color: var(--rarity-color);
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.5), 0 0 8px color-mix(in srgb, var(--rarity-color) 40%, transparent);
}
.hero-quick-card.current {
  border-color: var(--rarity-color);
  background: linear-gradient(145deg, #3d4a46, #24322e);
  box-shadow: inset 0 0 0 1px var(--rarity-color), 0 2px #080b0c;
}
.hero-quick-card-art {
  position: relative;
  width: 38px;
  height: 38px;
  flex: 0 0 38px;
  border-radius: 7px;
  background: #111718;
  border: 1px solid rgba(255, 255, 255, 0.1);
  overflow: hidden;
  display: grid;
  place-items: center;
}
.hero-quick-card-art img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}
.hero-quick-team-badge {
  position: absolute;
  top: 1px;
  right: 1px;
  width: 14px;
  height: 14px;
  border-radius: 50%;
  background: #76c867;
  color: #111;
  font-size: 9px;
  font-weight: 1000;
  display: grid;
  place-items: center;
  box-shadow: 0 1px 3px #000;
}
.hero-quick-card-info {
  min-width: 0;
  flex: 1;
}
.hero-quick-card-info b {
  display: block;
  font-size: 10px;
  color: #f3f7f5;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.hero-quick-card-info small {
  display: block;
  font-size: 8px;
  color: #aebbb5;
  margin-top: 2px;
}

/* Skill Rail & Preview Interactive Controls */
.hero-skill-pick small {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.skill-preview-btns {
  display: flex;
  align-items: center;
  gap: 4px;
}
.skill-preview-btns .preview-btn {
  padding: 4px 7px;
  min-width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  border: 2px solid #080b0c;
  border-radius: 6px;
  color: #132014;
  background: linear-gradient(180deg, #d4f990, #76c766);
  box-shadow: inset 0 1px #fff8, 0 2px #080b0c;
  font-size: 8px;
  font-weight: 900;
  cursor: pointer;
  transition: transform .08s ease, filter .1s ease;
}
.skill-preview-btns .preview-btn:hover {
  filter: brightness(1.1);
}
.skill-preview-btns .preview-btn:active {
  transform: translateY(2px);
  box-shadow: none;
}
.skill-preview-btns .preview-btn.active {
  background: linear-gradient(180deg, #ffe27a, #e6a93b);
  color: #2b1d05;
}

