/* Unit roster treatment: the collection is an operational screen, not a
   sticker album. Keep the existing layout and interactions, but use the same
   neutral hardware surfaces as the rest of the interface. */
.collection-page{
  --album-ink:#080b0c;
  --album-pink:#a5f247;
  --album-yellow:#c1cbc6;
  --album-blue:#87949a;
  --album-mint:#9ca9a3;
  color:#f4f7f5;
  background:
    repeating-linear-gradient(90deg,#ffffff04 0 1px,transparent 1px 22px),
    repeating-linear-gradient(0deg,#0000000b 0 2px,transparent 2px 7px),
    linear-gradient(180deg,#293234,#202729 58%,#171d1f);
}
.collection-page:before{opacity:.12;background-image:linear-gradient(90deg,#fff 1px,transparent 1px),linear-gradient(#fff 1px,transparent 1px);background-size:28px 28px}
.collection-banner{height:190px;background:linear-gradient(135deg,#4b555b,#30383d 58%,#252d31);border-bottom-color:var(--edge);box-shadow:inset 0 2px #ffffff18,0 5px #111617}
.collection-banner:after{background:linear-gradient(180deg,#667177,#3b454a);border-top-color:#ffffff19}
.collection-sky,.collection-cloud{display:none}
.collection-banner-copy{left:15px;top:25px;text-shadow:0 3px #080b0c}
.collection-banner-copy small{color:var(--accent);text-shadow:2px 2px var(--edge)}
.collection-banner-copy h1{color:#f4f7f5;text-shadow:none;-webkit-text-stroke:4px var(--edge)}
.collection-banner-copy h1 b{color:var(--accent)}
.collection-banner-copy p{color:#c1cbc6;text-shadow:1px 2px var(--edge)}
.collection-count{right:15px;top:19px;color:#f4f7f5;background:linear-gradient(180deg,#4b565a,#2d363a);border-color:var(--edge);box-shadow:inset 0 1px #fff2,0 4px #111617,0 6px var(--edge);transform:none}
.collection-count span{color:#c1cbc6}
.collection-cast{right:10px;bottom:27px}
.collection-cast-icon{border-color:var(--edge);background:linear-gradient(180deg,#647075,#3b4549)!important;box-shadow:inset 0 1px #fff2,0 4px #111617,0 6px var(--edge);transform:none}
.collection-toolbar,.collection-shelf{border-color:var(--edge);border-radius:11px;background:linear-gradient(180deg,#3e494a,#2a3335);box-shadow:inset 0 2px #ffffff17,0 5px #111617,0 7px var(--edge);transform:none}
.collection-action{border-color:var(--edge);color:#f4f7f5;box-shadow:inset 0 2px #fff2,0 3px #111617}
.action-team{background:linear-gradient(180deg,#697772,#3e4a47)}
.action-upgrade{background:linear-gradient(180deg,#7a8588,#454f53)}
.collection-progress{background:#171d1f;border-color:var(--edge)}
.collection-progress i{background:linear-gradient(90deg,#6cbd62,var(--accent));box-shadow:0 0 8px #a5f24766}
.collection-progress-label{color:#c1cbc6}.collection-progress-label b{color:var(--accent)}
.collection-shelf-head{color:#f4f7f5}.collection-shelf-head small{color:var(--accent)}.collection-shelf-head>span{color:#17201c;background:#aeb9b4;border-color:var(--edge);transform:none}
.collection-sort-btn{color:#c1cbc6;background:linear-gradient(180deg,#52605f,#303a3c);border-color:var(--edge);box-shadow:0 2px #111617}.collection-sort-btn.selected{color:#17201c;background:linear-gradient(180deg,#c7d0c9,#7c8982);box-shadow:0 2px #111617;transform:none}
.collection-grid .htile{--album-card:#30393c;background:linear-gradient(180deg,#465154,#2b3437);border-color:var(--edge);box-shadow:inset 0 2px #fff2,0 3px #111617,0 5px var(--edge);transform:none!important}
.collection-grid .htile:hover{transform:translateY(-4px)!important;box-shadow:inset 0 2px #fff2,0 5px #111617,0 8px var(--edge)}
.collection-grid .htile .por{background:radial-gradient(circle at 50% 45%,color-mix(in srgb,var(--rc,#aeb9b4) 22%,transparent),transparent 67%)}
.collection-grid .htile .nm{color:#f4f7f5;background:linear-gradient(transparent,#2b3437 47%);-webkit-text-stroke:2px #2b3437}
.collection-grid .htile .stars{color:#ffd54d;-webkit-text-stroke:2px #2b3437}
.collection-grid .htile .lv{color:#17201c;background:#b8c1bd;border-color:var(--edge)}
.collection-grid .htile .shd{color:#c1cbc6;background:#242d2e;border-color:var(--edge)}
.collection-grid .htile.locked{background:linear-gradient(180deg,#3c4547,#252d30)}
.collection-grid .htile.locked .por:after{background:#87949a}.collection-grid .htile.locked .nm{color:#9ca9a3;background:linear-gradient(transparent,#252d30 47%);-webkit-text-stroke:2px #252d30}
.collection-on-team{outline-color:var(--accent)}.collection-on-team:before{content:"✓";color:var(--accent);text-shadow:1px 1px var(--edge)}
.collection-missing-shelf{background:linear-gradient(180deg,#343e40,#252d30cc)}.collection-missing-shelf .collection-shelf-head small{color:#aeb9b4}
.collection-entering .collection-banner{animation:rosterConsoleIn .66s cubic-bezier(.12,1.25,.3,1) both}
.collection-entering .collection-toolbar{animation:rosterToolbarIn .52s .12s cubic-bezier(.16,1.35,.34,1) both}
.collection-entering .collection-shelf{animation:rosterShelfIn .52s .22s cubic-bezier(.16,1.3,.34,1) both}
.collection-entering .collection-shelf:nth-of-type(4){animation-delay:.34s}
.collection-entering .collection-cast-icon{animation:rosterCastIn .64s calc(var(--cast-i,0) * .08s + .12s) cubic-bezier(.16,1.4,.35,1) both}
.collection-entering .collection-grid .htile{animation:rosterTileIn .48s calc(var(--tile-i,0) * .028s + .25s) cubic-bezier(.16,1.45,.34,1) both}
.collection-leaving .collection-banner{animation:rosterConsoleOut .32s ease-in both}
.collection-leaving .collection-toolbar{animation:rosterToolbarOut .28s .02s ease-in both}
.collection-leaving .collection-shelf{animation:rosterShelfOut .29s .05s ease-in both}
.collection-cast-icon,.collection-grid .htile .por img{animation:none}
@keyframes rosterConsoleIn{0%{opacity:0;transform:translateY(-34px) scale(1.03)}65%{opacity:1;transform:translateY(4px) scale(1)}100%{opacity:1;transform:none}}
@keyframes rosterToolbarIn{from{opacity:0;transform:translateY(23px) rotate(-1deg) scale(.92)}to{opacity:1;transform:none}}
@keyframes rosterShelfIn{from{opacity:0;transform:translateY(28px) scale(.94)}to{opacity:1;transform:none}}
@keyframes rosterCastIn{from{opacity:0;transform:translateY(38px) rotate(11deg) scale(.55)}to{opacity:1;transform:none}}
@keyframes rosterTileIn{from{opacity:0;transform:translateY(18px) rotate(5deg) scale(.78)}to{opacity:1;transform:none}}
@keyframes rosterConsoleOut{to{opacity:0;transform:translateY(-22px) scale(.98)}}
@keyframes rosterToolbarOut{to{opacity:0;transform:translateX(-24px) rotate(-3deg)}}
@keyframes rosterShelfOut{to{opacity:0;transform:translateY(18px) scale(.96)}}

/* Keep the compact recruited-Hero rows authoritative after the neutral
   hardware theme layer above. */
.roster-owned-grid{grid-template-columns:1fr!important;gap:7px!important}
.roster-owned-grid .roster-tile{display:grid!important;grid-template-columns:76px minmax(0,1fr)!important;grid-template-rows:1fr;min-height:84px!important;aspect-ratio:auto!important;padding:5px 8px 5px 5px!important;border-radius:10px!important;transform:none!important;overflow:hidden}
.roster-owned-grid .roster-tile:hover{transform:translateY(-3px)!important}
.roster-owned-grid .roster-tile .por{position:relative!important;inset:auto!important;grid-column:1;grid-row:1;width:68px!important;height:72px!important;padding:4px!important;border:2px solid var(--edge);border-radius:7px;background:radial-gradient(circle at 50% 42%,color-mix(in srgb,var(--rc,#aeb9b4) 34%,transparent),transparent 70%)!important;overflow:hidden}
.roster-owned-grid .roster-tile .por img{width:100%!important;height:100%!important;max-width:none!important;max-height:none!important;animation:none!important;filter:saturate(1.16) contrast(1.05) drop-shadow(0 3px 1px #0006)}
.roster-owned-grid .roster-tile .nm{display:none!important}
.roster-owned-grid .roster-tile .obt{top:3px;left:61px;right:auto}
.roster-owned-grid .roster-tile .lv{top:5px;left:8px;right:auto}
.roster-owned-grid .roster-tile .stars{left:8px;right:auto;bottom:7px}
.roster-card-info{grid-column:2;grid-row:1;min-width:0;padding:1px 0 0 6px;text-align:left}
.roster-card-head{display:flex;align-items:baseline;gap:5px;min-width:0}
.roster-card-head>b{min-width:0;overflow:hidden;color:#f4f7f5;font-size:13px;line-height:1;text-overflow:ellipsis;white-space:nowrap;-webkit-text-stroke:2px var(--edge);paint-order:stroke fill}
.roster-power{flex:0 0 auto;color:var(--accent);font-size:8px;font-weight:1000;white-space:nowrap}
.roster-card-info>small{display:block;margin-top:4px;color:#aebbb5;font-size:7px;font-weight:900;letter-spacing:.65px}
.roster-gear{display:flex;gap:5px;margin-top:9px}
.roster-gear-slot{position:relative;display:grid;place-items:center;width:26px;height:26px;border:2px solid #566561;border-radius:50%;color:#9cafaa;background:radial-gradient(circle at 35% 25%,#64736d,#1d2829 67%);box-shadow:inset 0 1px #ffffff20,0 2px #111617;font-size:17px;font-weight:900;line-height:1}
.roster-gear-slot.filled{border-color:#8eaa88;background:radial-gradient(circle at 35% 25%,#7e9b83,#263b35 68%)}
.roster-gear-slot img{width:20px;height:20px;object-fit:contain;filter:drop-shadow(0 1px 1px #000)}
.roster-gear-slot i{position:absolute;right:-4px;bottom:-4px;padding:1px 2px;border:1px solid var(--edge);border-radius:3px;color:#ffe27a;background:#101718;font-size:5px;font-style:normal;font-weight:1000}
@media(min-width:700px){.roster-owned-grid{grid-template-columns:repeat(2,minmax(0,1fr))!important}}
@media(max-width:345px){.roster-owned-grid .roster-tile{grid-template-columns:68px minmax(0,1fr)!important}.roster-owned-grid .roster-tile .por{width:61px!important}.roster-card-head>b{font-size:11px}.roster-gear-slot{width:23px;height:23px}}

/* Keep the established roster cards while making large collections scannable. */
.roster-find{display:flex;align-items:center;gap:8px;margin-bottom:7px}
.roster-find input{flex:1;min-width:0;height:32px;padding:0 10px;border:2px solid #101717;border-radius:7px;color:#f4f7f5;background:#1b2728;font:800 10px Arial,sans-serif;outline:none}
.roster-find input:focus{border-color:#a5f247;box-shadow:0 0 0 2px #a5f24733}
.roster-find input::placeholder{color:#95a8a0}
.roster-find span{color:#b8d0bf;font-size:7px;font-weight:1000;white-space:nowrap}
.roster-filters{display:flex;gap:5px;margin-bottom:6px;overflow-x:auto}
.roster-filter{flex:none;padding:5px 8px;border:1px solid #69786f;border-radius:6px;color:#bed0c4;background:#344341;font-size:7px;font-weight:1000;cursor:pointer}
.roster-filter[aria-pressed="true"]{border-color:#a5f247;color:#1e3020;background:#c5f48b}
.roster-hidden,.roster-owned-grid .roster-tile.roster-hidden{display:none!important}
.roster-owned-grid.roster-grid-empty:after{content:attr(data-empty-text);grid-column:1/-1;padding:16px 8px;color:#b8cac1;font-size:10px;text-align:center}
.roster-upgrade-cue{display:inline-block;margin-top:3px;padding:2px 4px;border:1px solid #82a86a;border-radius:4px;color:#dcffb0;background:#284432;font-size:6px;font-weight:1000;letter-spacing:.2px}
.roster-owned-grid .roster-tile:has(.roster-upgrade-cue){min-height:93px!important}
.roster-mass-intro{margin-bottom:9px;color:#ccd8cf;font-size:10px;line-height:1.4}
.roster-mass-scope{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:8px}
.roster-mass-scope button{padding:8px 5px;border:2px solid #53635e;border-radius:7px;color:#d0ded2;background:#2b3b38;font-size:9px;font-weight:1000;cursor:pointer}
.roster-mass-scope button.selected{border-color:#b7eb8b;color:#223920;background:#c9ef9f}
.roster-mass-actions{display:grid;gap:5px}
.roster-mass-action{display:flex;align-items:center;gap:8px;padding:8px;border:1px solid #53655b;border-radius:7px;background:#283936;cursor:pointer}
.roster-mass-action input{width:16px;height:16px;accent-color:#a5f247}
.roster-mass-action span{display:grid;flex:1;gap:2px}
.roster-mass-action b{color:#f1f6e5;font-size:10px}
.roster-mass-action small{color:#a9bfb0;font-size:8px}
.roster-mass-action strong{color:#d9ffb2;font-size:10px;white-space:nowrap}
.roster-mass-preview{display:grid;gap:3px;margin:9px 0;padding:9px;border:1px solid #75916e;border-radius:8px;background:#20322c}
.roster-mass-preview b{color:#d9ffb2;font-size:11px}
.roster-mass-preview span{color:#d4ddd4;font-size:9px;line-height:1.4}
.roster-mass-preview details{margin-top:5px;border-top:1px solid #ffffff22}
.roster-mass-preview summary{padding-top:7px;color:#d9ffb2;font-size:8px;font-weight:1000;cursor:pointer}
.roster-mass-preview details>div{display:grid;gap:4px;max-height:140px;margin-top:6px;overflow:auto}
.roster-mass-preview details>div span{display:flex;justify-content:space-between;gap:8px;padding:3px 0;border-bottom:1px solid #ffffff11}
.roster-mass-preview details>div b{color:#f1f7eb;white-space:nowrap}
.roster-mass-apply:disabled{opacity:.45;pointer-events:none}

/* ==== friendship.css ==== */
/* Friendship Campaigns - warm storybook cards inside the game's chunky UI. */
.friendship-screen{position:relative;min-height:100%;margin:-10px -10px -18px;padding:10px 10px 24px;overflow:hidden;background:radial-gradient(circle at 14% 1%,#734b75 0,transparent 27%),radial-gradient(circle at 92% 20%,#3b6d67 0,transparent 25%),linear-gradient(180deg,#2e2639,#1a2428 54%,#172022)}
.friendship-screen:before{content:"";position:absolute;inset:0;pointer-events:none;opacity:.3;background-image:radial-gradient(circle,#fff 0 1px,transparent 1.5px);background-size:23px 23px}
