.team-sort-control{position:relative;min-width:0}.team-sort-control>.team-sort-chips{flex-wrap:nowrap;overflow-x:auto;padding:1px 1px 3px;scrollbar-width:thin}.team-sort-chip,.team-sort-more{flex:0 0 auto;padding:6px 7px;border:2px solid #0a0d0e;border-radius:7px;color:#c9d3ce;background:#34403e;box-shadow:0 2px #101716;font-size:7px;font-weight:1000;white-space:nowrap;cursor:pointer}.team-sort-chip:hover,.team-sort-more:hover{background:#46534f}.team-sort-chip.selected,.team-sort-more.selected{color:#172016;border-color:var(--gold);background:var(--gold)}
.team-sort-menu{position:absolute;z-index:30;top:calc(100% + 5px);left:0;right:0;display:grid;gap:7px;max-height:215px;overflow-y:auto;padding:8px;border:2px solid #0a0d0e;border-radius:9px;background:linear-gradient(180deg,#263536,#111a1b);box-shadow:inset 0 1px #fff2,0 5px #0b1010;animation:teamMenuIn .16s both cubic-bezier(.2,1.3,.4,1)}
