.team-filter-toggle:hover,.team-filter-toggle:focus-visible{border-color:#81948e}.team-filter-toggle.active{border-color:var(--gold);background:linear-gradient(180deg,#3d5438,#263a2c)}
.team-filter-toggle b{font-size:7px;letter-spacing:.7px}.team-filter-toggle small{min-width:0;overflow:hidden;color:#9fb0aa;font-size:5px;font-weight:900;letter-spacing:.4px;text-overflow:ellipsis;white-space:nowrap}.team-filter-toggle strong{color:#ffe27a;font-size:13px;line-height:1}
