/* ==== depths.css ==== */
/* The Ichor Depths deck - chunky, inked cards dealt like cartoon props. */
.depth-deck-panel{width:100%;display:flex;align-items:center;gap:11px;margin-top:9px;padding:8px 10px;
  color:#fff;text-align:left;border:3px solid #090c0d;border-radius:14px;
  background:linear-gradient(115deg,#2b3335 0 62%,#414b4d);box-shadow:inset 0 2px #ffffff24,0 4px #090c0d;
  overflow:hidden;position:relative;transition:transform .14s,filter .14s}
.depth-deck-panel:active{transform:translateY(3px);box-shadow:inset 0 2px #ffffff20,0 1px #090c0d}
.depth-deck-panel.has-draft{background:linear-gradient(115deg,#72468b,#353442 64%,#78dce8);animation:deckReady 1.35s ease-in-out infinite}
.depth-deck-panel.has-draft:after{content:"";position:absolute;inset:-30px -80px;background:linear-gradient(100deg,transparent 38%,#fff7 50%,transparent 62%);animation:deckShine 1.8s infinite}
@keyframes deckReady{50%{filter:brightness(1.14);transform:rotate(-.35deg) scale(1.005)}}
@keyframes deckShine{from{transform:translateX(-70%)}to{transform:translateX(75%)}}
.depth-deck-fan{position:relative;display:block;flex:0 0 58px;height:45px;z-index:1}
.depth-deck-fan img,.depth-deck-fan i{position:absolute;left:17px;top:4px;width:32px;height:38px;object-fit:contain;padding:4px;
  font-style:normal;text-align:center;background:#343638;border:3px solid #f4f4ef;border-radius:6px;box-shadow:0 2px #080a0b;
  transform:translateX(calc((var(--i, 0) - 1.5) * 7px)) rotate(calc((var(--i, 0) - 1.5) * 8deg))}
.depth-deck-fan i{display:grid;place-items:center;font-size:22px}
.depth-deck-copy{display:flex;flex:1;min-width:0;flex-direction:column;position:relative;z-index:2}
.depth-deck-copy b{font:900 15px/1 "Arial Black",sans-serif;letter-spacing:.5px;-webkit-text-stroke:3px #0b0d0e;paint-order:stroke fill}
.depth-deck-copy small{font-size:9px;color:#dfe7e3;margin-top:4px}
.depth-deck-arrow{position:relative;z-index:2;font:900 10px/1 "Arial Black",sans-serif;color:#d8ff73;white-space:nowrap}

#modalBox.depth-draft-modal{width:min(98vw,760px);max-height:96vh;padding:0;border:0;background:transparent;box-shadow:none;overflow:visible}
.depth-draft{position:relative;padding:13px 10px 10px;border:4px solid #080a0b;border-radius:22px;
  background:radial-gradient(circle at 50% 0,#50575a,#202527 67%);box-shadow:inset 0 3px #ffffff30,0 9px #080a0bcc;overflow:hidden}
.depth-draft:before{content:"";position:absolute;inset:0;pointer-events:none;opacity:.16;
  background:repeating-linear-gradient(135deg,#fff 0 1px,transparent 1px 13px)}
.depth-draft-head{position:relative;z-index:2;display:flex;align-items:flex-start;justify-content:space-between;padding:0 4px 10px;text-align:center}
.depth-draft-head>div{display:flex;flex:1;flex-direction:column;gap:2px;padding-left:34px}
.depth-draft-head span{font-size:8px;letter-spacing:2.5px;color:#9eeeff}
.depth-draft-head b{font:900 clamp(19px,5vw,30px)/1 "Arial Black",sans-serif;color:#fff06c;letter-spacing:-1px;
  -webkit-text-stroke:5px #121416;paint-order:stroke fill;text-shadow:0 3px #111}
.depth-draft-head small{font-size:9px;color:#e3e9e6}
.depth-draft-close{flex:0 0 31px;height:31px;border:3px solid #090b0c;border-radius:50%;background:#4d5557;box-shadow:inset 0 2px #fff3,0 3px #090b0c;position:relative;z-index:3}
.depth-draft-close:active{transform:translateY(2px);box-shadow:inset 0 2px #fff3}

.depth-card-row{position:relative;z-index:2;display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;perspective:900px;padding:4px 0 9px}
.depth-draft-card{--card:#f2f1e9;--glow:#fff;position:relative;min-width:0;height:330px;padding:7px 7px 9px;display:flex;align-items:center;flex-direction:column;
  color:#fff;border:5px solid var(--card);border-radius:17px;background:linear-gradient(165deg,#4b4c4e,#292a2c 60%,#18191a);
  box-shadow:inset 0 0 0 3px #090a0b,inset 0 3px #ffffff2e,0 7px 0 #090a0b,0 0 18px color-mix(in srgb,var(--glow) 22%,transparent);
  transform-origin:50% 110%;animation:depthCardDeal .58s calc(var(--deal) * .11s) cubic-bezier(.18,1.5,.35,1) both;
  transition:transform .18s cubic-bezier(.2,1.7,.3,1),filter .18s,opacity .18s}
.depth-draft-card.rarity-rare{--card:#86dcff;--glow:#5dcaff}
.depth-draft-card.rarity-epic{--card:#e0a0ff;--glow:#d87cff;background:linear-gradient(165deg,#674c72,#302735 62%,#18151c)}
@keyframes depthCardDeal{0%{opacity:0;transform:translateY(220px) rotate(calc((var(--deal) - 1) * 22deg)) scale(.35)}70%{opacity:1}100%{transform:translateY(0) rotate(calc((var(--deal) - 1) * 2deg)) scale(1)}}
@media (hover:hover){.depth-draft-card:hover{z-index:4;transform:translateY(-13px) rotate(calc((var(--deal) - 1) * -1deg)) scale(1.045);filter:brightness(1.12)}}
.depth-draft-card:active{transform:translateY(-3px) scale(.97)}
.depth-card-rarity{font:900 8px/1 "Arial Black",sans-serif;letter-spacing:1.5px;color:var(--card);margin-top:3px;text-shadow:0 2px #080a0b}
.depth-card-level{position:absolute;right:8px;top:7px;padding:3px 5px;font-size:7px;color:#111;background:var(--card);border:2px solid #090a0b;border-radius:99px;transform:rotate(3deg)}
.depth-card-art{width:min(83%,130px);aspect-ratio:1;margin:8px 0 5px;display:grid;place-items:center;border:4px solid #090a0b;border-radius:14px;
  background:radial-gradient(circle,#626568 0 42%,#343638 43% 70%,#242527 71%);box-shadow:inset 0 3px #fff2,0 3px #090a0b;overflow:hidden}
.depth-card-art img{width:72%;height:72%;object-fit:contain;filter:drop-shadow(0 3px 0 #090a0b);animation:depthIconBob 1.8s ease-in-out infinite}
@keyframes depthIconBob{50%{transform:translateY(-5px) rotate(-3deg) scale(1.04)}}
.depth-draft-card strong{min-height:42px;display:grid;place-items:center;font:900 clamp(13px,3.1vw,20px)/.95 "Arial Black",sans-serif;text-align:center;
  color:#fff;-webkit-text-stroke:4px #0b0c0d;paint-order:stroke fill;text-shadow:0 2px #0b0c0d}
.depth-card-desc{flex:1;display:grid;place-items:center;font-size:clamp(8px,1.8vw,11px);line-height:1.2;text-align:center;color:#f4f4ef;padding:3px 1px}
.depth-draft-card em{width:100%;padding:6px 2px 4px;font:900 8px/1 "Arial Black",sans-serif;font-style:normal;color:#101214;background:var(--card);border:3px solid #090a0b;border-radius:8px;box-shadow:0 3px #090a0b}
.depth-card-row.choosing{pointer-events:none}
.depth-draft-card.picked{z-index:8;animation:depthCardPick .62s cubic-bezier(.18,1.7,.28,1) forwards}
.depth-draft-card.discarded{animation:depthCardToss .42s ease-in forwards}
@keyframes depthCardPick{35%{transform:translateY(-22px) rotate(-3deg) scale(1.12)}65%{filter:brightness(1.8);transform:translateY(4px) scale(.96)}100%{opacity:0;transform:translateY(-130px) scale(1.28)}}
@keyframes depthCardToss{to{opacity:0;filter:grayscale(1);transform:translateY(90px) rotate(calc((var(--deal) - 1) * 20deg)) scale(.7)}}
.depth-draft-foot{position:relative;z-index:2;display:flex;align-items:center;justify-content:space-between;gap:8px;padding:4px 3px 1px;color:#bfc8c4;font-size:9px}
.depth-reroll{padding:6px 11px!important;border-radius:99px!important}.depth-reroll:disabled{opacity:.35;filter:grayscale(1);pointer-events:none}

.depth-deck-list{display:grid;gap:7px}
.depth-deck-row{--card:#eff4ef;display:flex;align-items:center;gap:9px;padding:7px 9px;border:3px solid #090b0c;border-left:6px solid var(--card);border-radius:12px;background:linear-gradient(180deg,#4a5153,#292f30);box-shadow:inset 0 2px #ffffff20}
.depth-deck-row.rarity-rare{--card:#83d9ff}.depth-deck-row.rarity-epic{--card:#e3a7ff}
.depth-deck-row img{width:40px;height:40px;object-fit:contain;filter:drop-shadow(0 2px #080a0b)}
.depth-deck-row div{display:flex;min-width:0;flex-direction:column}.depth-deck-row b{font-size:12px}.depth-deck-row small{font-size:8px;color:#d2dbd7}
.depth-deck-row>i{font-style:normal;font-size:8px;color:#111;background:var(--card);border:2px solid #090b0c;border-radius:99px;padding:3px 6px;white-space:nowrap}
.depth-resonance-note{display:flex;flex-direction:column;gap:3px;margin-top:5px;padding:9px;border:2px dashed #87d8ff;border-radius:11px;background:#162a32;color:#dff7ff}
.depth-resonance-note b{font-size:10px}.depth-resonance-note span{font-size:8px;color:#b9dce5}

@media (max-width:420px){
  #modal{padding:5px}.depth-draft{padding:9px 5px 7px;border-radius:17px}.depth-card-row{gap:4px}
  .depth-draft-card{height:304px;padding:5px 4px 7px;border-width:4px;border-radius:13px}
  .depth-card-art{width:88%;margin-top:10px;border-width:3px}.depth-draft-card strong{min-height:38px}
  .depth-card-desc{font-size:8px}.depth-draft-head small{font-size:8px}.depth-draft-foot{padding-inline:2px}
}
@media (prefers-reduced-motion:reduce){.depth-deck-panel,.depth-deck-panel:after,.depth-draft-card,.depth-card-art img{animation:none!important}}

/* ============================================================
   ENDLESS RUN
   A brighter, more characterful descent screen: friendly sticker colors,
   wet ichor accents, and a dark corridor silhouette behind the route. */
.endless-page{--er-ink:#071115;--er-panel:#17272b;--er-panel2:#233b3e;--er-blue:#78dcff;--er-mint:#baf47a;--er-pink:#ff8da6;--er-ichor:#ff5f87;position:relative;isolation:isolate;min-height:100%;margin:-10px -10px -18px;padding:0 10px 26px;overflow:hidden;color:#f6fbf7;background:
  radial-gradient(circle at 88% 4%,#34607155,transparent 27%),
  radial-gradient(circle at 7% 48%,#b53e6540,transparent 32%),
  linear-gradient(180deg,#0c1c22 0,#101b20 38%,#111719 100%)}
.endless-page:before{content:"";position:absolute;z-index:-2;inset:0;opacity:.38;background:repeating-linear-gradient(90deg,transparent 0 27px,#d9ffff08 28px 29px),repeating-linear-gradient(0deg,transparent 0 35px,#0008 36px 37px);pointer-events:none}
.endless-page:after{content:"";position:absolute;z-index:-1;left:-20%;right:-20%;top:392px;height:320px;background:radial-gradient(ellipse,#ff5f8730 0,transparent 62%);filter:blur(18px);pointer-events:none}
.endless-page.leaving{pointer-events:none;animation:endlessPageLeave .47s cubic-bezier(.55,.06,.85,.25) both}
@keyframes endlessPageLeave{to{opacity:0;transform:translateY(34px) scale(.97);filter:brightness(1.45) saturate(.7)}}

.endless-hero{position:relative;height:255px;margin:0 -10px;overflow:hidden;border-bottom:4px solid var(--er-ink);background:
  linear-gradient(180deg,#07151dcc 0,#07151d6e 40%,#071014f2 100%),
  radial-gradient(circle at 70% 24%,#7be5ff65,transparent 30%),#132e39;box-shadow:0 7px 20px #000b}
