  linear-gradient(90deg,#061216e8 0 19%,transparent 57%,#071216bd 100%);opacity:.42;filter:saturate(.82) contrast(1.08);mix-blend-mode:screen}
.endless-hero:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 45%,#071014 100%),repeating-linear-gradient(0deg,transparent 0 6px,#d5ffff09 7px 8px);pointer-events:none}
.endless-hero-stain{position:absolute;right:-5%;bottom:-36px;width:270px;height:116px;border-radius:50%;background:radial-gradient(ellipse,#ff5f875c 0 23%,#7e255455 43%,transparent 72%);filter:blur(4px);transform:rotate(-8deg)}
.endless-hero-stain:before,.endless-hero-stain:after{content:"";position:absolute;background:#ff6b8d99;border-radius:50% 50% 45% 55%;filter:blur(1px)}
.endless-hero-stain:before{left:25%;top:-15px;width:19px;height:37px;transform:rotate(22deg)}
.endless-hero-stain:after{left:42%;top:-24px;width:10px;height:23px;transform:rotate(-19deg)}
.endless-hero-top{position:absolute;z-index:3;top:11px;left:13px;right:13px;display:flex;justify-content:space-between;align-items:center;color:#dffcff;font-size:7px;font-weight:1000;letter-spacing:2px}
.endless-hero-top span{color:var(--er-blue)}.endless-hero-top b{padding:4px 7px;border:2px solid #8fe7ff88;border-radius:99px;background:#07171ccc;color:#c8f7ff;font-size:6px;letter-spacing:1px}
.endless-title{position:absolute;z-index:3;left:16px;bottom:24px;text-shadow:0 3px #03090b}
.endless-title small{display:block;color:var(--er-mint);font-size:8px;letter-spacing:3px;font-weight:1000}
.endless-title h1{margin:3px 0 4px;font:1000 clamp(31px,9vw,53px)/.78 "Arial Black","Trebuchet MS",sans-serif;letter-spacing:-2px;-webkit-text-stroke:4px var(--er-ink);paint-order:stroke fill;transform:rotate(-2deg)}
.endless-title h1 b{color:var(--er-pink);font-size:1.12em}
.endless-title p{max-width:230px;color:#d4e9e5;font-size:8px;line-height:1.35;font-weight:700}
.endless-floor-stamp{position:absolute;z-index:4;right:14px;top:65px;width:92px;height:92px;display:grid;place-items:center;align-content:center;transform:rotate(7deg);border:4px solid var(--er-ink);border-radius:50%;background:linear-gradient(145deg,#eafec1,#83cf7f);box-shadow:inset 0 2px #fff9,0 5px #03090b,0 0 20px #9eef9b55;color:#10231c;text-align:center}
