.machine-intro-floor{position:absolute;inset:44% -10% -20%;background:repeating-linear-gradient(90deg,transparent 0 44px,#ffffff0a 45px 47px),repeating-linear-gradient(0deg,transparent 0 23px,#ffffff08 24px 26px);transform:perspective(220px) rotateX(54deg);transform-origin:50% 0}.machine-intro-scan{position:absolute;z-index:1;left:0;right:0;top:40%;height:2px;background:#f5d76b;box-shadow:0 0 14px 3px #f5d76b99;opacity:0;transform:translateY(-120px)}
.machine-intro-team{position:absolute;z-index:4;left:7px;bottom:48px;width:53%;height:145px}.machine-intro-toon{position:absolute;bottom:0;left:calc(var(--i) * 20px);width:78px;height:139px;display:flex;flex-direction:column;align-items:center;justify-content:end;filter:drop-shadow(0 5px 2px #050707);transform:translateX(-180px) rotate(-8deg);opacity:0}.machine-intro-toon img{width:76px;height:115px;object-fit:contain;object-position:center bottom}.machine-intro-toon b{max-width:76px;overflow:hidden;color:#fff;text-shadow:0 2px #080b0b;font-size:7px;text-overflow:ellipsis;white-space:nowrap}.machine-intro-awake .machine-intro-toon{animation:machineToonEnter .72s calc(var(--i) * .12s) cubic-bezier(.16,1.45,.35,1) forwards}.machine-intro-awake .machine-intro-toon:nth-child(2n){bottom:7px}.machine-intro-awake .machine-intro-toon:nth-child(3n){bottom:15px}
