@media(max-width:390px){.machine-intro{min-height:430px;padding:10px 8px 8px}.machine-intro-stage{height:312px}.machine-intro-title b{font-size:26px}.machine-intro-team{bottom:46px;transform:scale(.82);transform-origin:left bottom}.machine-intro-machine{right:-10px;bottom:41px;width:59%;height:245px}.machine-intro-machine img{width:150px;height:215px}.machine-intro-machine:before{inset:20px 5px 17px}.machine-intro-caption{left:7px;right:7px}.machine-intro-caption span{font-size:7px}}

/* ==== machine-battle.css ==== */
/* The Ichor Machine is a battle-stage prop, not a modal. It sits above the
   arena while the room is paused, then disappears as the cast runs its normal
   entrance after an alerted check. */
.machine-battle-prop{position:absolute;z-index:2;width:108px;height:148px;display:grid;place-items:center;pointer-events:none;filter:drop-shadow(0 8px 5px #000b)}
.machine-battle-prop:before{content:"";position:absolute;inset:8px 6px 17px;border:2px dashed #e1c55d88;border-radius:48%;box-shadow:0 0 22px #e4c65b44;animation:machineBattleSpin 11s linear infinite}
