.machine-battle-alert{margin:6px auto 0;width:max-content;max-width:100%;padding:4px 7px;border:1px solid #e2bd58;border-radius:4px;background:#1a201bd9;color:#ffe89a;font-size:7px;font-weight:900;letter-spacing:.6px}
.machine-battle-check{width:min(390px,100%);margin:8px auto 0;padding:7px;border:3px solid #0b0d0d;border-radius:7px;background:linear-gradient(180deg,#4c5753f2,#1e2926f2);box-shadow:inset 0 1px #fff2,0 5px 12px #000b;pointer-events:auto}
