.machine-battle-track{position:relative;width:100%;height:27px;display:block;overflow:hidden;border:2px solid #080b0b;border-radius:4px;background:#808887;box-shadow:inset 0 2px 4px #0008;cursor:crosshair}.machine-battle-track i{position:absolute;top:4px;height:15px;border-radius:2px}.machine-battle-silver{background:linear-gradient(#f5f8f3,#b8c2bb);box-shadow:inset 0 1px #fff,0 0 4px #e9f5ee}.machine-battle-gold{top:6px!important;height:11px!important;background:linear-gradient(#fff1a5,#dfa62b);box-shadow:inset 0 1px #fff8,0 0 7px #ffdf5b}.machine-battle-cursor{top:0!important;width:3px;background:#fff;border-radius:0!important;box-shadow:0 0 6px #fff,0 0 3px #050707;transform:translateX(-1px)}
