/* Beat the shared #screen child animation so pass refreshes and departures use
   their own choreography. Keep the two toolbar actions comfortably tappable. */
#screen>.battle-pass-page.entering{animation:none}
#screen>.battle-pass-page.updating{animation:passRefresh .2s ease-out}
#screen>.battle-pass-page.leaving{pointer-events:none;animation:passPageExit .4s cubic-bezier(.55,.05,.75,.3) forwards}
