/* ==== launcher.css ==== */
/* Title screen: the room and original game logo do the visual work. */
#launcher {
  position: fixed;
  inset: 0;
  z-index: 950;
  overflow: hidden;
  color: #f5e9ce;
  background: #171411;
  opacity: 0;
  pointer-events: none;
  transition: opacity .2s ease;
}
#launcher[hidden] { display: none; }
#launcher.visible { opacity: 1; pointer-events: auto; }
#launcher.leaving { opacity: 0; pointer-events: none; }
.launcher-backdrop {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, #08070655, #08070620 45%, #080706b8), url('../assets/uploads/launcher-room.webp') 55% center / cover no-repeat;
}
.launcher-card {
  position: relative;
  display: flex;
  min-height: 100vh;
  min-height: 100dvh;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: clamp(50px, 11vh, 105px);
  padding: 24px 20px max(24px, env(safe-area-inset-bottom));
}
.launcher-logo {
  display: block;
  width: min(78vw, 570px);
  max-height: 35vh;
  object-fit: contain;
  filter: drop-shadow(0 8px 10px #050403bb);
}
.launcher-actions {
  display: grid;
  justify-items: center;
  gap: 14px;
  width: min(75vw, 270px);
}
.launcher-play {
  width: 100%;
  min-height: 60px;
  border: 2px solid #1b1713;
  border-radius: 5px;
  background: #f1dfb9;
  box-shadow: 0 4px 0 #100d0b;
  color: #251d16;
  font: 900 21px/1 Arial, sans-serif;
  cursor: pointer;
  transition: background .15s ease, transform .15s ease, box-shadow .15s ease;
}
.launcher-play:hover { background: #fff0cd; transform: translateY(-2px); box-shadow: 0 6px 0 #100d0b; }
.launcher-play:active { transform: translateY(3px); box-shadow: 0 1px 0 #100d0b; }
.launcher-play:disabled { cursor: wait; opacity: .8; }
.launcher-settings {
  padding: 7px 10px;
  border: 0;
  background: transparent;
  color: #f5e9ce;
  font: 700 14px/1 Arial, sans-serif;
  text-decoration: underline;
  text-decoration-color: #f5e9ce77;
  text-underline-offset: 4px;
  cursor: pointer;
}
.launcher-settings:hover { color: #fff; text-decoration-color: currentColor; }
.launcher-settings:disabled { cursor: wait; opacity: .55; }
.launcher-status { color: #f5e9ce; font: 700 12px/1.3 Arial, sans-serif; text-align: center; text-shadow: 0 2px 4px #000; }
.launcher-play:focus-visible, .launcher-settings:focus-visible { outline: 3px solid #fff; outline-offset: 4px; }
@media (max-width: 600px) {
  .launcher-backdrop { background-position: 60% center; }
  .launcher-logo { width: min(90vw, 460px); max-height: 32vh; }
  .launcher-actions { width: min(68vw, 270px); }
}
@media (max-height: 540px) and (min-width: 650px) {
  .launcher-card { flex-direction: row; gap: 6vw; }
  .launcher-logo { width: min(50vw, 500px); max-height: 70vh; }
  .launcher-actions { width: min(28vw, 240px); }
}
@media (prefers-reduced-motion: reduce) {
  #launcher, .launcher-play { transition: none; }
}
.accessibility-first-run { display: grid; gap: 12px; max-width: 420px; }
.accessibility-first-run p { font-size: 15px; line-height: 1.4; }
.accessibility-first-run small { color: var(--dim); font-size: 10px; line-height: 1.45; }
.accessibility-first-run-actions { flex-wrap: wrap; }
.accessibility-first-run-actions .btn { min-width: 0; }

