/* ==== audio-settings.css ==== */
.settings-audio {
  padding: 10px 11px 9px;
  border: 2px solid #263a34;
  border-radius: 10px;
  background: linear-gradient(145deg, #354946, #202d2d);
  box-shadow: inset 0 1px #fff2, 0 2px #101617;
}

.settings-audio-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 7px;
  color: #efffd1;
  font-size: 12px;
}

.settings-audio-value {
  color: #dfff83;
  font-size: 11px;
}

.settings-audio input[type="range"] {
  display: block;
  width: 100%;
  height: 28px;
  margin: 0;
  accent-color: #b9ed67;
  cursor: pointer;
}

.settings-audio small {
  display: block;
  margin-top: 4px;
  color: #b8cbc1;
  font-size: 8px;
  line-height: 1.3;
}

.settings-menu-music-panel {
  grid-column: 1 / -1;
  padding: 10px;
  border: 2px solid #3d5a57;
  border-radius: 11px;
  background: linear-gradient(145deg, #263b3d, #1d292b);
  box-shadow: inset 0 1px #fff1, 0 3px #0d1517;
}

.settings-music-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 6px;
}

.settings-music-btn {
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-height: 58px;
  padding: 8px 8px;
  cursor: pointer;
}

.settings-music-btn b {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 9.5px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.settings-music-btn small {
  margin-top: 3px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.settings-music-btn.active {
  border-color: #d5ff76;
  background: linear-gradient(145deg, #3d5e43, #223a34);
  box-shadow: inset 0 0 0 1px #d5ff7644, 0 0 0 1px #d5ff7644;
}

.settings-music-btn.active b {
  color: #fff4c9;
}

.settings-music-btn.active small {
  color: #c9eed2;
}

@media (max-width: 620px) {
  .settings-music-row {
    grid-template-columns: 1fr 1fr;
  }
}


