.settings-preset-row{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.settings-preset{min-width:0;min-height:55px;padding:7px 5px;border:2px solid #415b59;border-radius:8px;color:#d9e9de;background:#1d2e30;text-align:left;box-shadow:inset 0 1px #fff1,0 2px #0c1314;transition:transform .12s,filter .12s,border-color .12s}.settings-preset:hover{filter:brightness(1.12)}.settings-preset:active{transform:translateY(2px)}.settings-preset.active{border-color:#d5ff76;background:linear-gradient(145deg,#3d5e43,#223a34);box-shadow:inset 0 0 0 1px #d5ff7644,0 0 0 1px #d5ff7644}.settings-preset b,.settings-preset small{display:block}.settings-preset b{font-size:9px;color:#f1ffd5}.settings-preset small{margin-top:3px;color:#a9c5b8;font-size:7px;line-height:1.2}
