/* ==== nav-overhaul.css ==== */
/* Bottom navigation overhaul: a compact, high-contrast dock with one clear
   primary action and generous touch targets. This is loaded last so the dock
   stays consistent across the older phone/tablet nav rules. */
#navbar {
  position: relative;
  z-index: 20;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 5px;
  padding: 9px 8px calc(9px + var(--safe-b));
  background:
    linear-gradient(180deg, #0d1316 0%, #172124 58%, #101719 100%);
  border-top: 2px solid #71817b66;
  box-shadow: inset 0 3px 0 #0008, 0 -8px 22px #0005;
}

#navbar button {
  position: relative;
  min-width: 0;
  min-height: 67px;
  display: grid;
  grid-template-rows: 42px auto;
  align-content: center;
  justify-items: center;
  gap: 4px;
  padding: 3px 2px 1px;
  border: 2px solid transparent;
  border-radius: 14px;
  color: #aabbb4;
  background: transparent;
  transition: transform .14s, color .14s, background .14s, border-color .14s;
  -webkit-tap-highlight-color: transparent;
}

#navbar button i {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border: 2px solid #070b0d;
  border-radius: 12px;
  color: #d8e8e1;
  background: linear-gradient(145deg, #526261, #293638);
  box-shadow: inset 0 2px #ffffff20, 0 3px 0 #06090a;
  font-size: 20px;
  font-style: normal;
  line-height: 1;
  transition: transform .14s, background .14s, box-shadow .14s;
}

#navbar button span {
  min-width: 0;
  display: block;
  overflow: hidden;
  color: inherit;
  font-size: 10px;
  font-weight: 1000;
  line-height: 1;
  letter-spacing: .25px;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
  -webkit-text-stroke: 1.5px var(--edge);
  paint-order: stroke fill;
}

#navbar button span b {
  display: block;
  font-size: inherit;
  font-weight: 1000;
}

#navbar button span small {
  display: block;
  margin-top: 3px;
  color: #9daea8;
  font-size: 7px;
  font-weight: 900;
  letter-spacing: .35px;
  text-transform: uppercase;
  -webkit-text-stroke: 1px var(--edge);
}

#navbar button:after {
  content: '';
  position: absolute;
  right: 24%;
  bottom: 1px;
  left: 24%;
  height: 3px;
  border-radius: 99px;
  background: transparent;
  transition: background .14s, box-shadow .14s;
}

#navbar button:hover,
#navbar button:focus-visible {
  color: #f4fff8;
  background: #ffffff0b;
  outline: none;
}

#navbar button:focus-visible {
  border-color: #dfff9b;
}

#navbar button:active {
  transform: translateY(2px);
}

#navbar button:active i {
  transform: translateY(2px);
  box-shadow: inset 0 2px #ffffff18, 0 1px 0 #06090a;
}

#navbar button.on {
  color: #f5ffd5;
  background: linear-gradient(180deg, #9bde4b1c, #7acb4010);
  border-color: #c7f57a55;
}

#navbar button.on i {
  color: #152718;
  background: linear-gradient(145deg, #e3ff87, #67bf58);
  box-shadow: inset 0 2px #ffffff9c, 0 3px 0 #132217, 0 0 15px #9be35a33;
  transform: translateY(-2px);
}

#navbar button.on:after {
  background: #dfff83;
  box-shadow: 0 0 9px #caff69;
}

#navbar .nav-main {
  min-height: 76px;
  margin-top: -15px;
  padding-top: 7px;
  border-color: #d7ff7c66;
  background: linear-gradient(180deg, #394a3c, #1f2f2c);
  box-shadow: inset 0 2px #ffffff2c, 0 5px 0 #070c0b, 0 0 18px #b8f56a18;
}

#navbar .nav-main i {
  width: 53px;
  height: 53px;
  border-color: #162317;
  color: #172818;
  background: linear-gradient(145deg, #f3ff9b, #76cb5b);
  box-shadow: inset 0 3px #ffffffad, 0 4px 0 #0b160e, 0 0 17px #b9ff703d;
  font-size: 27px;
}

#navbar .nav-main.on {
  border-color: #efffb2;
  background: linear-gradient(180deg, #506941, #2b4733);
}

#navbar .nav-main.on i {
  transform: translateY(-3px) scale(1.04);
}

#navbar .nav-main:active {
  transform: translateY(2px);
}

#navbar .nav-main:active i {
  transform: translateY(1px) scale(1.02);
}

.lab-settings-btn {
  color: #f0ddff;
  background: linear-gradient(180deg, #8965a8, #4e3a68);
  border-color: #271a36;
}

@media (max-width: 430px) {
  #navbar {
    gap: 2px;
    padding: 7px 4px calc(7px + var(--safe-b));
  }

  #navbar button {
    min-height: 62px;
    grid-template-rows: 37px auto;
    gap: 3px;
    border-radius: 11px;
  }

  #navbar button i {
    width: 37px;
    height: 37px;
    border-radius: 10px;
    font-size: 18px;
  }

  #navbar button span {
    font-size: 9px;
    letter-spacing: 0;
    -webkit-text-stroke-width: 1px;
  }

  #navbar button span small {
    display: none;
  }

  #navbar .nav-main {
    min-height: 70px;
    margin-top: -12px;
    padding-top: 5px;
  }

  #navbar .nav-main i {
    width: 47px;
    height: 47px;
    font-size: 24px;
  }
}

@media (prefers-reduced-motion: reduce) {
  #navbar button,
  #navbar button i,
  #navbar button:after {
    transition: none;
  }
}

/* ==== battle-ui-reference.css ==== */
/* Reference-inspired battle HUD.
   The screenshot's useful ideas are the hierarchy and readability: a calm
   status rail at the top, an unobstructed arena, and chunky role-colored
   character cards at the bottom. Keep the project's dark Dandy materials and
   outlined type, and leave special collaboration/world battle skins alone. */

#battle:not(.kh-battle):not(.unknown-world-battle){
  background:#0b1113;
  box-shadow:0 0 0 3px #080b0c,0 0 60px #000;
}

#battle:not(.kh-battle):not(.unknown-world-battle) #battleHud{
  padding:calc(9px + env(safe-area-inset-top,0px)) 9px calc(10px + env(safe-area-inset-bottom,0px));
}

#battle:not(.kh-battle):not(.unknown-world-battle) #hudTop{
  position:relative;
  z-index:12;
  align-items:center;
  gap:5px;
  min-height:42px;
  padding:4px;
  border:2px solid #080b0c;
  border-radius:13px;
  background:linear-gradient(180deg,#172123d9,#0b1113e8);
  box-shadow:inset 0 1px #f1fff21c,0 4px 12px #0008;
}

#battle:not(.kh-battle):not(.unknown-world-battle) #waveInfo,
#battle:not(.kh-battle):not(.unknown-world-battle) #hudTimer{
  min-height:31px;
  padding:5px 9px;
  border:2px solid #344547;
  border-radius:9px;
  background:linear-gradient(180deg,#334446e8,#182325e8);
  box-shadow:inset 0 1px #ffffff18,0 2px #050708;
  text-shadow:0 1px #050708;
}

#battle:not(.kh-battle):not(.unknown-world-battle) #waveInfo{
  border-left:3px solid var(--accent);
  letter-spacing:.3px;
}

#battle:not(.kh-battle):not(.unknown-world-battle) #waveInfo i{
  color:var(--accent);
}

#battle:not(.kh-battle):not(.unknown-world-battle) #hudTimer{
  color:#d9f2ff;
  border-color:#496b75;
}

#battle:not(.kh-battle):not(.unknown-world-battle) #hudTimer i{
  color:#85dfff;
}

#battle:not(.kh-battle):not(.unknown-world-battle) #hudBtns{
  gap:4px;
}

#battle:not(.kh-battle):not(.unknown-world-battle) #hudBtns button{
  width:34px;
  height:32px;
  border:2px solid #344547;
  border-radius:10px;
  background:linear-gradient(180deg,#4b5b5b,#263335);
  box-shadow:inset 0 1px #ffffff20,0 2px #050708;
}

#battle:not(.kh-battle):not(.unknown-world-battle) #hudBtns button:first-child{
  color:#d7f2dc;
}

#battle:not(.kh-battle):not(.unknown-world-battle) #hudBtns button.on{
  border-color:#e8cc70;
  background:linear-gradient(180deg,#f4da79,#aa752b);
}

#battle:not(.kh-battle):not(.unknown-world-battle) #hudBtns button:last-child{
  color:#ffb0b0;
  border-color:#78484b;
  background:linear-gradient(180deg,#713c42,#3b2228);
}

#battle:not(.kh-battle):not(.unknown-world-battle) #logBox{
  left:10px;
  right:auto;
  bottom:130px;
  max-width:340px;
  max-height:56px;
  padding:4px 8px;
  border-left:3px solid var(--accent);
  border-radius:6px;
  background:rgba(9,15,20,0.8);
  backdrop-filter:blur(4px);
  box-shadow:0 3px 8px rgba(0,0,0,0.5);
}

#battle:not(.kh-battle):not(.unknown-world-battle) #logBox div{
  font-size:10px;
  line-height:1.25;
  color:#f1f5f9;
  font-weight:700;
  text-shadow:0 1px 2px #000, 0 1px 3px rgba(0,0,0,0.85);
  -webkit-text-stroke:0;
}
#battle:not(.kh-battle):not(.unknown-world-battle) #logBox div b{
  color:#fde047;
  font-weight:900;
}

#battle:not(.kh-battle):not(.unknown-world-battle) #allyDock{
  left:8px;
  right:8px;
  bottom:calc(8px + env(safe-area-inset-bottom,0px));
  justify-content:center;
  gap:5px;
  padding:14px 6px 6px;
  border:3px solid #080b0c;
  border-radius:14px;
  background:linear-gradient(180deg,#253234e8,#11191aeF);
  box-shadow:inset 0 2px #d7eee51b,0 4px #050708,0 0 18px #0008;
}

#battle:not(.kh-battle):not(.unknown-world-battle) #allyDock:before{
  content:'TEAM // AUTO-BATTLE';
  position:absolute;
  top:4px;
  left:8px;
  padding:2px 7px;
  border:1px solid #526662;
  border-radius:4px;
  color:#a8d4bd;
  background:#142020e8;
  font-size:6px;
  font-weight:1000;
  letter-spacing:1px;
  text-shadow:0 1px #050708;
}

#battle:not(.kh-battle):not(.unknown-world-battle) .unitcard{
  width:60px;
  flex:0 1 60px;
  min-width:0;
  padding:4px 4px 5px;
  border:3px solid #080b0c;
  border-radius:9px;
  background:linear-gradient(180deg,var(--card-top,#5a6967),var(--card-bottom,#2b3939));
  box-shadow:inset 0 2px #ffffff32,0 3px #050708;
  transform:translateY(0);
  transition:transform .12s,opacity .3s,filter .3s;
}

#battle:not(.kh-battle):not(.unknown-world-battle) .unitcard:hover{
  transform:translateY(-3px);
}

#battle:not(.kh-battle):not(.unknown-world-battle) .unitcard.role-damage{
  --card-top:#d86b68;
  --card-bottom:#813a46;
}

#battle:not(.kh-battle):not(.unknown-world-battle) .unitcard.role-support{
  --card-top:#69c995;
  --card-bottom:#2d765f;
}

#battle:not(.kh-battle):not(.unknown-world-battle) .unitcard.role-tank{
  --card-top:#6fb8d2;
  --card-bottom:#315f78;
}

#battle:not(.kh-battle):not(.unknown-world-battle) .unitcard.role-control{
  --card-top:#b184d3;
  --card-bottom:#5c3f83;
}

#battle:not(.kh-battle):not(.unknown-world-battle) .uc-port{
  width:52px;
  height:52px;
  border:2px solid #080b0c;
  border-radius:6px;
  background:#edf2d8;
  box-shadow:inset 0 1px #fff8,0 2px #1a2525;
}

#battle:not(.kh-battle):not(.unknown-world-battle) .uc-port img{
  width:94%;
  height:94%;
}

#battle:not(.kh-battle):not(.unknown-world-battle) .uc-lv{
  top:-6px;
  left:-5px;
  padding:1px 4px;
  border:2px solid #080b0c;
  border-radius:5px;
  background:#1c2829;
  color:#ffe27a;
  font-size:8px;
}

#battle:not(.kh-battle):not(.unknown-world-battle) .uc-stars{
  margin-top:3px;
  color:#ffe27a;
  font-size:8px;
}

#battle:not(.kh-battle):not(.unknown-world-battle) .uc-hpwrap,
#battle:not(.kh-battle):not(.unknown-world-battle) .uc-enwrap{
  width:52px;
  height:6px;
  border:2px solid #080b0c;
  border-radius:2px;
  background:#152021;
}

#battle:not(.kh-battle):not(.unknown-world-battle) .uc-hp{
  background:linear-gradient(180deg,#d8ff8b,#4dbb65);
}

#battle:not(.kh-battle):not(.unknown-world-battle) .uc-en{
  background:linear-gradient(90deg,#55d8ee,#b591ed);
}

#battle:not(.kh-battle):not(.unknown-world-battle) .unitcard.ult-ready{
  border-color:#ffe17c;
}

#battle:not(.kh-battle):not(.unknown-world-battle) .unitcard.ko{
  filter:grayscale(.8);
}

@media(max-width:430px){
  #battle:not(.kh-battle):not(.unknown-world-battle) #hudTop{min-height:38px;padding:3px}
  #battle:not(.kh-battle):not(.unknown-world-battle) #waveInfo,
  #battle:not(.kh-battle):not(.unknown-world-battle) #hudTimer{min-height:28px;padding:4px 7px;font-size:10px}
  #battle:not(.kh-battle):not(.unknown-world-battle) #hudBtns button{width:30px;height:29px}
  #battle:not(.kh-battle):not(.unknown-world-battle) #allyDock{left:5px;right:5px;gap:3px;padding-inline:3px}
  #battle:not(.kh-battle):not(.unknown-world-battle) .unitcard{width:calc((100vw - 42px) / 5);flex-basis:calc((100vw - 42px) / 5);padding-inline:2px}
  #battle:not(.kh-battle):not(.unknown-world-battle) .uc-port,
  #battle:not(.kh-battle):not(.unknown-world-battle) .uc-hpwrap,
  #battle:not(.kh-battle):not(.unknown-world-battle) .uc-enwrap{width:100%}
  #battle:not(.kh-battle):not(.unknown-world-battle) .uc-port{height:calc((100vw - 42px) / 5)}
  #battle:not(.kh-battle):not(.unknown-world-battle) #logBox{bottom:119px}
}

/* ==== vee-ad-popups.css ==== */
/* Vee's battle callouts are broadcast ads, not generic status boxes. The
   supplied Vee stills carry the noisy warning-card language; this frame gives
   them a readable stage position and keeps the combat palette intact. */
.vee-ad-popup{position:absolute;z-index:11;min-height:122px;padding:4px;border:4px solid #07100f;border-radius:10px;overflow:hidden;color:#f2fff1;background:#07100f;box-shadow:inset 0 0 0 2px var(--vee-accent),0 4px #050a0a,0 0 18px color-mix(in srgb,var(--vee-accent),transparent 42%);opacity:0;transform:scale(.42) rotate(-4deg);transform-origin:50% 70%;pointer-events:none;will-change:transform,opacity;transition:transform .26s cubic-bezier(.15,1.45,.3,1),opacity .14s ease-out}
.vee-ad-popup.is-live{opacity:.98;transform:scale(1) rotate(1deg)}
.vee-ad-popup.is-leaving{opacity:0;transform:scale(1.08) rotate(4deg);transition:transform .24s ease-in,opacity .2s ease-in}
.vee-ad-popup:before{content:"";position:absolute;z-index:4;inset:0;pointer-events:none;background:repeating-linear-gradient(0deg,transparent 0 4px,#b9ffd112 5px 6px),linear-gradient(115deg,transparent 0 42%,#d9fff32c 48%,transparent 55%)}
.vee-ad-top{position:relative;z-index:5;display:flex;justify-content:space-between;align-items:center;gap:4px;height:15px;padding:0 4px;border-bottom:2px solid #07100f;color:#b7ff70;background:linear-gradient(90deg,#173b30,#0a1716);font:1000 6px/1 Arial,sans-serif;letter-spacing:.55px}
.vee-ad-top span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.vee-ad-top i{flex:none;color:#ffdd67;font-size:5px;font-style:normal;letter-spacing:.2px}
.vee-ad-art{position:relative;height:58px;overflow:hidden;background:#020707}.vee-ad-art img{width:100%;height:100%;display:block;object-fit:cover;object-position:center 42%;}.vee-ad-art:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,#02070718 0 52%,#020707d8 100%),linear-gradient(90deg,#75e65f14,transparent 50%,#7be0ff18)}.vee-ad-art b{position:absolute;z-index:2;left:5px;right:5px;bottom:3px;color:#eaff9c;font:1000 10px/.9 "Arial Black",Arial,sans-serif;letter-spacing:.3px;text-shadow:2px 2px #07100f,-1px -1px #07100f;white-space:nowrap}
.vee-ad-copy{position:relative;z-index:5;display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:center;gap:1px 4px;min-height:30px;padding:4px 5px 3px;background:linear-gradient(180deg,#152926,#081313)}.vee-ad-copy small{grid-column:1/-1;overflow:hidden;color:var(--vee-accent);font:1000 5px/1 monospace;letter-spacing:.7px;text-transform:uppercase;white-space:nowrap}.vee-ad-copy strong{overflow:hidden;color:#f1fff2;font:1000 9px/.95 "Arial Black",Arial,sans-serif;text-overflow:ellipsis;white-space:nowrap}.vee-ad-copy em{overflow:hidden;color:#91b6a2;font:700 5px/1 Arial,sans-serif;font-style:normal;text-align:right;text-overflow:ellipsis;white-space:nowrap}.vee-ad-meter{position:absolute;z-index:6;right:6px;bottom:4px;left:6px;height:2px;overflow:hidden;background:#203d34}.vee-ad-meter i{display:block;width:0;height:100%;background:var(--vee-accent);box-shadow:0 0 7px var(--vee-accent);transition:width var(--vee-ad-life) ease-out}
.vee-ad-popup-small{min-height:78px;padding:3px;border-width:3px;border-radius:8px}.vee-ad-popup-small .vee-ad-top{height:11px;padding-inline:3px;font-size:4px}.vee-ad-popup-small .vee-ad-top i{font-size:4px}.vee-ad-popup-small .vee-ad-art{height:35px}.vee-ad-popup-small .vee-ad-art b{left:3px;bottom:2px;font-size:7px}.vee-ad-popup-small .vee-ad-copy{min-height:20px;padding:3px 4px 2px}.vee-ad-popup-small .vee-ad-copy small{font-size:4px}.vee-ad-popup-small .vee-ad-copy strong{font-size:7px}.vee-ad-popup-small .vee-ad-copy em{display:none}.vee-ad-popup-small .vee-ad-meter{right:4px;bottom:3px;left:4px;height:1px}

@media(max-width:430px){.vee-ad-popup{transform:scale(.38) rotate(-4deg)}.vee-ad-popup.is-live{transform:scale(.88) rotate(1deg)}.vee-ad-popup.is-leaving{transform:scale(.96) rotate(4deg)}}
html.graphics-low .vee-ad-popup:before{display:none}html.graphics-low .vee-ad-popup{box-shadow:inset 0 0 0 2px var(--vee-accent),0 3px #050a0a}
html.graphics-lite .vee-ad-popup:before{background:repeating-linear-gradient(0deg,transparent 0 4px,#b9ffd112 5px 6px)}html.graphics-lite .vee-ad-popup{box-shadow:inset 0 0 0 2px var(--vee-accent),0 3px #050a0a,0 0 8px color-mix(in srgb,var(--vee-accent),transparent 68%)}
@media(prefers-reduced-motion:reduce){.vee-ad-popup{transition:none}}

/* ==== home-reference.css ==== */
/* Home hub reference notes: a scenic command map, clear named locations,
   compact resource pills, and one obvious route forward. Keep the hand-built
   Gardenview palette and the existing actions underneath. */
#topbar{background:linear-gradient(180deg,#101719f5,#1a2527f5);border-bottom-color:#070d0f;box-shadow:inset 0 -2px #78918a55,inset 0 2px #ffffff0d,0 3px 13px #0007}
.tb-right{gap:4px}.res{border-radius:99px;padding:3px 8px 3px 6px;background:linear-gradient(180deg,#455454,#202b2d);box-shadow:inset 0 1px #ffffff26,0 2px #070b0c}
.res i{font-size:12px}.res span{font-size:10px}

.home-stage{isolation:isolate!important;background:
  radial-gradient(circle at 84% 19%,#f7efaa2c 0 4%,transparent 5%),
  radial-gradient(circle at 18% 34%,#8fe7ff2d 0 9%,transparent 22%),
  linear-gradient(180deg,#252c64 0 34%,#496c8c 35% 52%,#5ca778 53% 100%)!important;
  box-shadow:inset 0 0 0 3px #f2e79c,inset 0 0 0 6px #ffffff35,0 6px #203b43,0 12px 22px #0a191f99!important;
  cursor:pointer;transition:transform .14s cubic-bezier(.16,1.4,.3,1),filter .14s}
.home-stage:hover{filter:brightness(1.04)}
.home-stage:active{transform:translateY(3px);filter:brightness(.97)}
.home-stage:before{content:"";position:absolute;z-index:0;inset:0;pointer-events:none;background:
  radial-gradient(ellipse at 76% 52%,#d5f3c34d 0 7%,transparent 23%),
  linear-gradient(126deg,transparent 0 19%,#a5e0d329 19.2% 20%,transparent 20.3% 51%,#f6e7a92b 51.2% 51.8%,transparent 52%),
  repeating-linear-gradient(90deg,transparent 0 41px,#d1f4d30e 42px 44px),
  repeating-linear-gradient(0deg,transparent 0 28px,#d1f4d30c 29px 31px)}
.home-stage-sky{z-index:0!important;opacity:.64;background:
  radial-gradient(ellipse at 14% 15%,#e8fbff 0 3%,transparent 4%),
  radial-gradient(ellipse at 57% 19%,#e8fbffbb 0 2%,transparent 3%),
  linear-gradient(180deg,#7587c7 0,#2d4078 58%,transparent 59%)!important}
.home-stage-floor{z-index:1!important;top:43%;background:
  radial-gradient(ellipse at 60% 6%,#eff7c966 0 4%,transparent 19%),
  repeating-linear-gradient(90deg,#fff3 0 2px,transparent 2px 34px),
  repeating-linear-gradient(0deg,transparent 0 25px,#173e3c26 26px 29px),
  linear-gradient(180deg,#94d69a,#4d9b6e 57%,#24604e)!important;opacity:.9}
.home-stage-rays{z-index:2!important;opacity:.38!important;background:repeating-conic-gradient(from 7deg at 68% 85%,#fff7 0 3deg,transparent 3deg 18deg)!important}

/* Scenic cartoon clouds */
.home-stage-cloud{position:absolute;pointer-events:none;z-index:1;border-radius:99px;background:#ffffff1f;filter:blur(0.5px)}
.home-stage-cloud:before,.home-stage-cloud:after{content:"";position:absolute;border-radius:50%;background:inherit}
.home-stage-cloud.a{width:68px;height:18px;top:20px;left:18%;animation:homeCloudDrift 42s linear infinite}
.home-stage-cloud.a:before{width:28px;height:28px;top:-12px;left:14px}
.home-stage-cloud.a:after{width:20px;height:20px;top:-8px;right:12px}
.home-stage-cloud.b{width:54px;height:15px;top:42px;right:22%;animation:homeCloudDrift 48s linear -21s infinite}
.home-stage-cloud.b:before{width:22px;height:22px;top:-9px;left:10px}
.home-stage-cloud.b:after{width:16px;height:16px;top:-6px;right:9px}
@keyframes homeCloudDrift{from{transform:translateX(-100px)}to{transform:translateX(560px)}}

.home-stage-copy{z-index:6!important;top:58px!important;max-width:55%;padding:5px 7px;border-left:3px solid #fff09a;border-radius:0 7px 7px 0;background:#101d2e75;text-shadow:1px 2px #102033!important}
.home-stage-copy b{font-size:clamp(16px,4.7vw,24px)!important;color:#fff6bc!important}
.home-lead-star{color:#ffe46b;font-style:normal;margin-right:2px;display:inline-block;animation:leadStarGlow 2s ease-in-out infinite}
@keyframes leadStarGlow{0%,100%{transform:scale(1);filter:drop-shadow(0 0 2px #ffe46b)}50%{transform:scale(1.22);filter:drop-shadow(0 0 5px #fff)}}

.home-stage-party{z-index:5!important}
.home-stage-toon{cursor:pointer;pointer-events:auto;transition:transform .18s cubic-bezier(.16,1.4,.3,1)}
.home-stage-toon:hover{transform:translateY(-5px) scale(1.05);filter:drop-shadow(3px 7px 0 #17352b) drop-shadow(0 9px 8px #18372299)}
.home-stage-toon.cheer{animation:homeToonCheer .42s cubic-bezier(.16,1.8,.3,1) both!important}
@keyframes homeToonCheer{0%{transform:scale(1)}35%{transform:translateY(-14px) scale(1.12) rotate(-3deg)}70%{transform:translateY(-2px) scale(0.96) rotate(2deg)}100%{transform:none}}

.home-toon-badges{position:absolute;top:6px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:3px;z-index:6}
.home-toon-crown{display:grid;place-items:center;width:15px;height:15px;border-radius:50%;background:#ffe77d;border:1.5px solid #17352b;box-shadow:0 1px 2px #0006;font-size:9px;font-style:normal;animation:crownBob 1.6s ease-in-out infinite}
@keyframes crownBob{0%,100%{transform:translateY(0)}50%{transform:translateY(-3px)}}
.home-toon-role{display:grid;place-items:center;width:13px;height:13px;border-radius:50%;background:#ffffffdc;border:1px solid #17352b;font-size:7px;box-shadow:0 1px 2px #0004}
.home-toon-pill{display:flex;flex-direction:column;align-items:center;gap:1px;max-width:96%;z-index:5}
.home-toon-pill b{max-width:100%;overflow:hidden;padding:1px 5px;border:2px solid #17352b;border-radius:7px;background:#fff9df;color:#23432f;font-size:6.5px;text-overflow:ellipsis;white-space:nowrap;box-shadow:1px 2px #2d7645;text-shadow:none}
.home-toon-pill small{padding:0 3px;border-radius:4px;background:#17352bdd;color:#d8ffd0;font-size:5.5px;font-weight:900;letter-spacing:.3px}

.home-stage-sign{z-index:8!important;background:linear-gradient(180deg,#ff7655,#c83a37)!important;box-shadow:2px 3px #70261e,0 0 0 2px #ffe77e55!important}
.home-stage-next{z-index:8!important;min-width:104px!important;background:linear-gradient(180deg,#fff4a2,#efbd4b)!important;box-shadow:2px 3px #733a28,0 0 0 2px #fff3a733!important;animation:homeSignSway 4.5s ease-in-out infinite}
@keyframes homeSignSway{0%,100%{transform:rotate(1.2deg)}50%{transform:rotate(-0.8deg)}}
.home-stage-next b{display:flex;align-items:center;gap:3px;font:1000 10px/1 'Arial Black',Arial,sans-serif;color:#243a2c}
.home-next-icon{font-style:normal;font-size:11px;display:inline-block}

.home-stage-dashboard{z-index:8!important}
.home-stage-edit{z-index:8!important;display:flex!important;align-items:center!important;gap:4px!important;transition:transform .12s,box-shadow .12s}
.home-stage:hover .home-stage-edit{transform:scale(1.06);box-shadow:2px 4px #103b4a,0 0 8px #4bc5d588!important}

.home-map-labels{position:absolute;z-index:4;inset:0;pointer-events:none}.home-map-label{position:absolute;display:grid;grid-template-columns:19px auto;grid-template-rows:auto auto;align-items:center;column-gap:3px;min-width:57px;padding:2px 4px 2px 2px;color:#fff9dd;text-shadow:2px 2px #152039,-1px -1px #152039;transform:rotate(-2deg);filter:drop-shadow(0 2px 1px #13242c)}.home-map-label:after{content:"";position:absolute;left:8px;right:0;bottom:-4px;height:2px;background:#fff5b566;box-shadow:0 0 5px #fff5b533}.home-map-label i{grid-row:1/3;display:grid;place-items:center;width:18px;height:18px;border:2px solid #17242c;border-radius:50%;color:#18383a;background:linear-gradient(145deg,#efff9e,#63bd78);box-shadow:0 2px #193c35;font-size:9px;font-style:normal;text-shadow:none}.home-map-label b{font:1000 8px/.95 "Arial Black",Arial,sans-serif;letter-spacing:.3px;white-space:nowrap}.home-map-label small{color:#d9f5ce;font-size:4px;font-weight:1000;letter-spacing:.7px;white-space:nowrap}.home-map-run{left:39%;top:16%;transform:rotate(-4deg)}.home-map-events{right:7%;top:34%;transform:rotate(3deg)}.home-map-trials{left:8%;top:48%;transform:rotate(-3deg)}.home-map-crates{right:24%;top:51%;transform:rotate(2deg)}.home-map-heroes{left:44%;top:69%;transform:rotate(-2deg)}

.home-buds{border-radius:10px!important;background:linear-gradient(115deg,#fff6a6,#b5eb75 56%,#62b88b)!important;box-shadow:inset 0 2px #fff,0 4px #0d1612,0 0 0 2px #f0ff9a44!important;transition:transform .12s,filter .12s;cursor:pointer}
.home-buds:hover{transform:translateY(-2px);filter:brightness(1.05)}
.home-buds:active{transform:translateY(2px)}

/* Primary Continue Button */
.home-continue{display:flex;align-items:center;gap:10px;width:100%;padding:9px 12px;border:3px solid #0b1710;border-radius:13px!important;color:#fcffe9;text-align:left;background:linear-gradient(135deg,#bbf760,#65c059 48%,#357f4b)!important;box-shadow:inset 0 2px #fff9,0 4px 0 #163d23,0 8px 18px #133c2155!important;transition:transform .12s cubic-bezier(.16,1.4,.3,1),box-shadow .12s,filter .12s;cursor:pointer}
.home-continue:hover{transform:translateY(-2px);box-shadow:inset 0 2px #fff,0 6px 0 #163d23,0 12px 24px #133c2177!important;filter:brightness(1.06)}
.home-continue:active{transform:translateY(3px);box-shadow:inset 0 1px #fff9,0 1px 0 #163d23!important}
.home-continue-icon{position:relative;display:grid;place-items:center;width:38px;height:38px;border:2.5px solid #173622;border-radius:50%;background:#e8ffae;color:#2d7138;font-size:17px;box-shadow:inset 0 2px #fff,0 2px 4px #0b1a1066}
.home-continue-icon:before{content:"";position:absolute;inset:-3px;border-radius:50%;border:1.5px dashed #e8ffae77;animation:homeContinueHalo 6s linear infinite}
@keyframes homeContinueHalo{to{transform:rotate(1turn)}}
.home-continue small{color:#144425;font-size:7.5px;font-weight:1000;letter-spacing:.9px}
.home-continue b{font-size:14.5px;letter-spacing:.3px;color:#fff;text-shadow:1px 2px #184c27}
.home-continue em{color:#eaffd4;font-size:8px;font-style:normal;display:flex;align-items:center;gap:5px;flex-wrap:wrap}
.home-next-pill{display:inline-flex;align-items:center;gap:2px;padding:1px 5px;border-radius:99px;background:#143e2488;border:1px solid #75d97f66;color:#ddffd3;font-size:7px;font-style:normal;font-weight:900}
.home-continue-end{display:flex;align-items:center;gap:6px;margin-left:auto}
.home-kbd-hint{display:inline-block;padding:2px 5px;border:1.5px solid #1b4d2a;border-radius:5px;background:#153d23cc;color:#cbf7b7;font:900 7px/1 monospace;box-shadow:0 1px 0 #0d2817}
.home-continue strong{font-size:25px;font-style:normal;color:#efffd9;text-shadow:0 2px #184c27;line-height:1}

.home-section header{padding:3px 5px 4px;border-bottom:2px solid #76908555}
