.arena-live{position:relative;max-width:760px;margin:0 auto 13px;padding:11px;border:2px solid #d5a75f99;border-radius:12px;color:#fff3d0;background:linear-gradient(135deg,#182c2bdf,#253c35ed 48%,#172322e8);box-shadow:inset 0 1px #fff3,0 5px 13px #080b0a99;animation:arenaCard .62s .16s both}.arena-live-head{display:flex;justify-content:space-between;align-items:center;gap:10px}.arena-live-head small{display:block;color:#a9ec9c;font-size:7px;font-weight:1000;letter-spacing:1.6px}.arena-live-head h2{margin:2px 0 0;color:#fff1c8;font:1000 17px Georgia,serif;text-shadow:0 2px #0d211d}.arena-live-count{display:flex;align-items:center;gap:5px;padding:4px 7px;border:1px solid #9ae79577;border-radius:7px;background:#0b1b1a99}.arena-live-count b{color:#dfff9d;font:1000 22px Georgia,serif}.arena-live-count span{color:#b6d7c0;font-size:6px;font-weight:1000;line-height:1.1;letter-spacing:.6px}.arena-live-grid{display:grid;grid-template-columns:1fr auto;gap:9px;margin-top:9px}.arena-live-roster{display:flex;flex-wrap:wrap;gap:5px;min-height:42px}.arena-live-player{position:relative;display:flex;align-items:center;gap:5px;min-width:112px;padding:4px 6px;border:1px solid #a5c7ad44;border-radius:7px;background:#10201d99}.arena-live-player.self{border-color:#ffdc826e;background:#342414b3}.arena-live-player.fighting{animation:arenaLivePulse 1.3s ease-in-out infinite}.arena-live-player img{width:28px;height:30px;object-fit:contain}.arena-live-player span{min-width:0}.arena-live-player b,.arena-live-player small{display:block;max-width:88px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.arena-live-player b{color:#fff1cf;font-size:8px}.arena-live-player small{margin-top:2px;color:#a9d1bb;font-size:6px;font-weight:1000;letter-spacing:.5px}.arena-live-player>i{position:absolute;right:3px;top:-6px;padding:2px 3px;border:1px solid #c9fa9677;border-radius:3px;color:#dcffb5;background:#2f6b45;font-size:5px;font-style:normal;font-weight:1000}.arena-live-empty{align-self:center;color:#9db9ac;font-size:8px;font-weight:800}.arena-live-actions{display:grid;gap:5px;min-width:112px}.arena-live-actions button{padding:6px 7px;border:1px solid #d4a95e;border-radius:6px;color:#301606;background:linear-gradient(180deg,#ffe79b,#da923e);box-shadow:inset 0 1px #fff,0 3px #251007;font:1000 7px Georgia,serif;cursor:pointer}.arena-live-actions button:active{transform:translateY(3px);box-shadow:inset 0 1px #fff,0 0 #251007}.arena-live-actions button:disabled{cursor:wait;opacity:.5;filter:grayscale(.5)}.arena-live-actions button small{display:block;margin-top:2px;color:#6c3d18;font:1000 6px sans-serif;letter-spacing:.3px}.arena-live-actions .arena-live-cheer{color:#d9ffd0;border-color:#77c895;background:linear-gradient(180deg,#397c54,#20503c);box-shadow:inset 0 1px #fff4,0 3px #0c241c}.arena-live-actions .arena-live-cheer small{color:#b9efaf}.arena-live-meter{margin-top:8px}.arena-live-meter>div{display:flex;justify-content:space-between;color:#b9d8c2;font-size:7px;font-weight:1000;letter-spacing:1px}.arena-live-meter b{color:#f8d986}.arena-live-meter>i{display:block;height:7px;margin-top:4px;overflow:hidden;border:1px solid #0a1513;border-radius:5px;background:#0a1715;box-shadow:inset 0 1px #0008}.arena-live-meter em{display:block;height:100%;border-radius:4px;background:linear-gradient(90deg,#6ecb79,#ffe17e,#f39b52);box-shadow:0 0 10px #a9ed8b99;transition:width .3s ease}.arena-live-feed{display:grid;gap:3px;margin:8px 0 0;padding:7px 0 0;border-top:1px solid #a7d4a633;list-style:none}.arena-live-feed li{display:flex;gap:6px;align-items:baseline;color:#a9c7b4;font-size:7px;line-height:1.25}.arena-live-feed li i{display:grid;place-items:center;flex:0 0 15px;color:#f5cf7d;font-style:normal;font-size:10px}.arena-live-feed li b{color:#f1e0b9}.arena-live-feed li.empty{color:#839d90}.arena-live-feed li.empty i{color:#83c990}.arena-live-feed li:nth-child(n+4){opacity:.72}
