.arena-quest-copy{min-width:0}.arena-quest-copy small,.arena-quest-prize small{display:block;color:#b4e69a;font-size:7px;font-weight:1000;letter-spacing:1.5px}.arena-quest-copy b{display:block;margin:2px 0;color:#fff6d5;font:1000 15px Georgia,serif}.arena-quest-copy span{display:block;color:#c4d9c6;font-size:8px;font-weight:800}.arena-quest-copy>i{display:block;height:5px;max-width:390px;margin-top:6px;overflow:hidden;border-radius:4px;background:#0b1511;box-shadow:inset 0 1px #000}.arena-quest-copy>i em{display:block;height:100%;border-radius:4px;background:linear-gradient(90deg,#78c979,#dff18b);box-shadow:0 0 9px #b8ee8e77;transition:width .4s}.arena-quest-prize{min-width:130px;padding-left:12px;border-left:1px solid #b5e6a755}.arena-quest-prize b{display:block;margin-top:4px;color:#ffdfa0;font-size:10px;white-space:nowrap}
.arena-challenges{grid-template-columns:repeat(auto-fit,minmax(min(100%,340px),1fr));gap:11px}
.arena-challenge{grid-template-columns:minmax(0,1fr) 116px;gap:8px 11px;min-height:158px;padding:11px;border-color:#d4aa6c77;border-left-width:4px;background:linear-gradient(135deg,#172220ef,#24342fee 62%,#191f1ded);box-shadow:inset 0 1px #fff2,0 5px 12px #05080799}
.arena-challenge:hover{transform:translateY(-2px);border-color:#f6d995}
.arena-challenge.beaten{opacity:.68;filter:saturate(.7)}
.arena-challenge.featured-rival{border-color:#b7e981;border-left-color:#d7f392;background:linear-gradient(125deg,#213827f5,#35502ff2 54%,#222b20f5);box-shadow:inset 0 1px #fff3,0 0 0 1px #e2f4ac33,0 7px 18px #080c0877}
.arena-challenge-head{min-height:17px;gap:5px}.arena-challenge-head small{color:#e6cb91;font-size:7px;letter-spacing:1px}.featured-rival .arena-challenge-head small{color:#e8ffb4}.arena-tag-featured{border-color:#d7ef9c;color:#344522;background:#d4e99c}
.arena-challenger b{font-size:16px}.arena-challenger span{color:#c0d3c7;font-size:8px}
.arena-opponent-roster{gap:6px;align-items:center;flex-wrap:wrap}.arena-fighter{width:45px;height:49px;background:#14201d}.arena-fighter>img{border-color:#d4bd82;background:#1b2a25}.arena-fight{grid-column:2;grid-row:2 / span 2;align-self:stretch;display:grid;place-content:center;min-width:0;padding:8px 7px;border-color:#493118;color:#38200c;background:linear-gradient(180deg,#f7df95,#dba347);box-shadow:inset 0 1px #fff8,0 4px #25180d;font-size:9px;line-height:1.2;letter-spacing:.3px}.featured-rival .arena-fight:not(.rematch){color:#263318;border-color:#40512a;background:linear-gradient(180deg,#edffb1,#a4d46e);box-shadow:inset 0 1px #fff9,0 4px #1b2a18}.arena-fight.rematch{color:#dce9dd;background:linear-gradient(180deg,#55695c,#2e4036)}
.arena-exchange{margin-top:20px;padding:13px;border-color:#8a754c;background:linear-gradient(135deg,#1c2723f0,#293c33ef,#1a2521f0)}.arena-exchange header small{color:#b9e18f}.arena-exchange h2{font-size:19px}.arena-exchange-offers{grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px}.arena-exchange-offer{padding:8px;background:linear-gradient(180deg,#35473c,#202b26);border-color:#9ab47a55}.arena-exchange-offer span b{font-size:8px}
@media(max-width:520px){.arena-marquee{grid-template-columns:31px minmax(0,1fr) 90px;gap:4px}.arena-title h1{font-size:clamp(26px,8vw,36px)}.arena-laurel{font-size:26px}.arena-record{min-height:54px}.arena-record b{font-size:18px}.arena-daily-quest{grid-template-columns:34px minmax(0,1fr);gap:8px;padding:9px}.arena-quest-mark{width:32px;height:32px}.arena-quest-copy b{font-size:13px}.arena-quest-prize{grid-column:2;padding:0;border:0}.arena-challenge{grid-template-columns:minmax(0,1fr) 88px;padding:9px;gap:7px}.arena-fight{font-size:8px}.arena-fighter{width:39px;height:43px}.arena-briefing{align-items:flex-start}.arena-refresh{min-width:69px;padding:5px;font-size:16px}.arena-refresh small{font-size:5px}.arena-exchange-offers{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(prefers-reduced-motion:reduce){.arena-quest-copy>i em{transition:none}}
.arena-record{min-width:126px;padding:6px 4px;border-left-color:#d6c47b99;background:linear-gradient(90deg,#0000,#1a251cbf);text-shadow:0 1px #10120a}
.arena-record .arena-league-name{font:1000 13px/1.1 Georgia,serif;color:#e4f0c5;text-shadow:0 2px #18231a}
.arena-record>span{display:block;margin-top:3px;color:#dfebcf;font-size:6px;font-weight:1000}
.arena-record .arena-league-meter{display:block;height:5px;margin:5px 3px 2px;overflow:hidden;border:1px solid #111911;border-radius:5px;background:#101710}
.arena-record .arena-league-meter em{display:block;width:0;height:100%;margin:0;padding:0;border:0;border-radius:4px;background:linear-gradient(90deg,#83c873,#e2ef9b);box-shadow:0 0 8px #c9ef8a66}
.arena-record .arena-promotion-hint{display:block;color:#c6d7a4;font-size:6px;letter-spacing:.2px}
.arena-league-silver .arena-league-name{color:#e5e7ec}.arena-league-gold .arena-league-name{color:#ffe28f}.arena-league-platinum .arena-league-name{color:#a7f0dd}.arena-league-diamond .arena-league-name{color:#93dcff}.arena-league-master .arena-league-name{color:#d8afff}.arena-league-champion .arena-league-name{color:#ffd1a0;text-shadow:0 0 10px #ff9d62aa}
@media(max-width:520px){.arena-record{min-width:90px;padding:5px 2px}.arena-record .arena-league-name{font-size:10px}.arena-record>span,.arena-record .arena-promotion-hint{font-size:5px}.arena-record em{margin-top:2px}}

/* ==== crates.css ==== */
/* Dyle's depot: compact crate controls and a physical opening sequence. */
.crate-switch { display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:7px;margin-bottom:8px; }
.crate-choice { min-width:0;display:grid;grid-template-columns:25px minmax(0,1fr);grid-template-rows:1fr 1fr;align-items:center;gap:0 5px;min-height:54px;padding:6px 7px;border:2px solid #0b1112;border-radius:10px;color:#b8c5c1;background:#222d2e;box-shadow:0 3px #111819;text-align:left;transition:transform .14s,border-color .14s,background .14s; }
.crate-choice[data-kind=gold] { --crate-accent:#eac36c; }
.crate-choice[data-kind=diamond] { --crate-accent:#80d5ec; }
.crate-choice[data-kind=main] { --crate-accent:#d6aaed; }
.crate-choice[data-kind=collab] { --crate-accent:#73d8ff; }
.crate-choice:hover { transform:translateY(-2px); }
.crate-choice:active { transform:translateY(2px);box-shadow:none; }
.crate-choice.active { border-color:var(--crate-accent);color:#fffaf0;background:#394543; }
.crate-choice-mark { grid-row:1/3;display:grid;place-items:center;width:24px;height:29px;border:2px solid var(--crate-accent);border-radius:2px;color:var(--crate-accent);background:#182522;font:900 10px/1 ui-monospace,monospace;letter-spacing:-.5px;transform:rotate(-4deg); }
.crate-choice-name { overflow:hidden;white-space:nowrap;text-overflow:ellipsis;font-size:10px;font-weight:900; }
.crate-choice-count { color:var(--crate-accent);font-size:12px;line-height:1; }

.crate-stage { --crate-accent:#d9b875;--crate-face:#9f744c;--crate-dark:#704b30;--crate-lid:#c09461;--crate-strap:#d0ae75;--crate-paper:#e9d6aa;position:relative;overflow:hidden;padding:14px 14px 12px;border:3px solid #121b19;border-radius:9px;background:linear-gradient(#35443e,#25332f);box-shadow:inset 0 2px #65736a,0 4px #111918; }
.crate-stage[data-kind=diamond] { --crate-accent:#9bd3dc;--crate-face:#668b94;--crate-dark:#3c626b;--crate-lid:#a4cbd0;--crate-strap:#aac8c9;--crate-paper:#e3edf0; }
.crate-stage[data-kind=main] { --crate-accent:#d0afd8;--crate-face:#80658d;--crate-dark:#59416a;--crate-lid:#ae92b5;--crate-strap:#d7b775;--crate-paper:#efdfbd; }
.crate-stage:before { content:'';position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0 47px,#fff1 47px 48px);opacity:.25;pointer-events:none; }
.crate-stage>* { position:relative; }
.crate-stage-top { display:flex;justify-content:space-between;align-items:start;gap:10px; }
.crate-eyebrow { display:block;color:var(--crate-accent,#c1cbc6);font-size:8px;font-weight:900;letter-spacing:1.4px; }
.crate-stage h2 { margin:2px 0 0;color:#f1f0e3;font-size:clamp(18px,5vw,24px);line-height:1.1;letter-spacing:-.5px; }
.crate-level { flex:0 0 auto;min-width:47px;color:#c9d5cf;font-size:10px;font-weight:900;text-align:right; }
.crate-level i { display:block;width:47px;height:5px;margin-top:5px;border-radius:4px;background:linear-gradient(90deg,var(--crate-accent) var(--progress),#111919 var(--progress));box-shadow:inset 0 0 0 1px #0c1111; }

.crate-scene { width:min(100%,300px);height:177px;margin:3px auto 0;border-bottom:4px solid #18231f; }
.crate-scene:after { content:'';position:absolute;left:0;right:0;bottom:-7px;height:3px;background:#59675b;opacity:.45; }
.crate-dyle { position:absolute;z-index:4;left:1px;bottom:6px;width:105px;height:139px;transform-origin:53% 92%;pointer-events:none; }
.crate-dyle img { display:block;width:100%;height:100%;object-fit:contain;filter:drop-shadow(2px 3px 0 #111b19); }
.crate-object { position:absolute;right:0;top:24px;display:block;width:230px;height:149px;margin:0;padding:0;transform-origin:50% 85%;transition:transform .16s ease; }
.crate-object:hover:not(:disabled) { transform:translateY(-3px); }
.crate-object:active:not(:disabled) { transform:translateY(2px); }
.crate-object:disabled { cursor:default;opacity:.82; }
.crate-object>span { position:absolute;display:block; }
.crate-shadow { left:30px;right:21px;bottom:0;height:13px;border-radius:50%;background:#0d1816a8;filter:blur(4px); }
.crate-body { z-index:2;left:42px;top:67px;width:160px;height:80px;border:3px solid #17211e;border-bottom-width:5px;border-radius:3px 3px 6px 6px;background:repeating-linear-gradient(0deg,#ffffff0d 0 2px,transparent 2px 17px),linear-gradient(90deg,var(--crate-dark),var(--crate-face) 13%,var(--crate-face) 87%,var(--crate-dark));box-shadow:inset 0 3px #ffffff40,0 3px #0d1715; }
.crate-stage[data-kind=diamond] .crate-body { background:linear-gradient(108deg,#ffffff35 0 9%,transparent 9% 29%,#ffffff17 29% 32%,transparent 32%),linear-gradient(90deg,var(--crate-dark),var(--crate-face) 13%,var(--crate-face) 87%,var(--crate-dark)); }
.crate-stage[data-kind=main] .crate-body { background:repeating-linear-gradient(90deg,#ffffff0e 0 2px,transparent 2px 27px),linear-gradient(90deg,var(--crate-dark),var(--crate-face) 13%,var(--crate-face) 87%,var(--crate-dark)); }
.crate-body:before,.crate-body:after { content:'';position:absolute;top:0;bottom:0;width:10px;border-inline:2px solid #17231f88;background:linear-gradient(90deg,#fff5,var(--crate-strap),#14201d33); }
.crate-body:before { left:8px; }.crate-body:after { right:8px; }
.crate-band { position:absolute;left:0;right:0;top:17px;height:10px;border-block:2px solid #17231f99;background:var(--crate-strap);box-shadow:inset 0 2px #fff5; }
.crate-inlay { position:absolute;inset:31px 25px 7px;border:2px solid #25352e99;background:#10231a20; }
.crate-body b { position:absolute;z-index:3;left:50%;top:30px;display:flex;flex-direction:column;align-items:center;justify-content:center;width:82px;height:35px;border:2px solid #1c2b25;color:#243128;background:var(--crate-paper);box-shadow:2px 2px #17231f70;transform:translateX(-50%) rotate(-2deg);font:900 11px/1 Arial,sans-serif;letter-spacing:.8px; }
.crate-body b small { margin-top:3px;font:700 7px/1 ui-monospace,monospace;letter-spacing:1px; }
.crate-rivet { position:absolute;z-index:4;width:5px;height:5px;border:1px solid #25312b;border-radius:50%;background:#e8d9ad; }
.rivet-a { left:23px;top:7px; }.rivet-b { right:23px;top:7px; }.rivet-c { left:23px;bottom:6px; }.rivet-d { right:23px;bottom:6px; }
.crate-lid { z-index:3;left:36px;top:40px;width:172px;height:38px;border:3px solid #17211e;border-radius:5px 5px 2px 2px;background:linear-gradient(#ffffff4a,transparent 22%),var(--crate-lid);box-shadow:inset 0 -6px #15231f3d,0 3px #101a18;transform-origin:11% 82%; }
.crate-lid:before { content:'';position:absolute;inset:9px 9px 7px;border-top:2px solid #26362e9c;border-bottom:2px solid #fff7; }
.crate-lid i { position:absolute;left:50%;top:-3px;bottom:-3px;width:28px;border-inline:2px solid #17231f88;background:var(--crate-strap);transform:translateX(-50%); }
.crate-lid em { position:absolute;left:50%;top:-7px;width:42px;height:8px;border:3px solid #17211e;border-bottom:0;border-radius:5px 5px 0 0;transform:translateX(-50%);background:var(--crate-lid); }
.crate-catch { z-index:5;left:48px;top:76px;width:28px;height:28px;border:4px solid #17211e;border-radius:50%;background:var(--crate-strap);box-shadow:inset 0 0 0 2px #f6e5bd88,0 2px #111b18;transform-origin:50% 50%; }
.crate-catch i { position:absolute;left:50%;top:2px;width:3px;height:12px;background:#16251f;transform:translateX(-50%); }
.crate-tag { z-index:6;left:83px;top:67px;display:grid!important;place-items:center;width:19px;height:27px;border:2px solid #17211e;color:#182720;background:var(--crate-paper);box-shadow:2px 2px #112019;font:900 8px/1 ui-monospace,monospace;transform:rotate(8deg); }
.crate-opening .crate-object { pointer-events:none; }
.crate-opening .crate-dyle { animation:dyleTurn .9s ease-in-out both; }
.crate-opening .crate-catch { animation:crateDial .9s ease-in-out both; }
.crate-opening .crate-tag { animation:crateTag .9s ease-out both; }
.crate-opening .crate-lid { animation:crateLidDyle .9s cubic-bezier(.2,.7,.2,1) both; }
.crate-opening .crate-body { animation:crateKnock .9s ease both; }
@keyframes dyleTurn { 0%,22% { transform:translate(0,0) rotate(0); } 42% { transform:translate(14px,-2px) rotate(5deg); } 54% { transform:translate(25px,0) rotate(8deg); } 73% { transform:translate(17px,-3px) rotate(-3deg); } 100% { transform:translate(0,0) rotate(0); } }
@keyframes crateDial { 0%,40% { transform:rotate(0); } 56%,83% { transform:rotate(100deg); } 100% { transform:rotate(0); } }
@keyframes crateTag { 0%,43% { opacity:1;transform:translate(0,0) rotate(8deg); } 60% { opacity:1;transform:translate(-8px,-19px) rotate(-20deg); } 100% { opacity:0;transform:translate(-37px,38px) rotate(-86deg); } }
@keyframes crateLidDyle { 0%,50% { transform:translate(0,0) rotate(0); } 68%,84% { transform:translate(-14px,-36px) rotate(-31deg); } 100% { transform:translate(0,0) rotate(0); } }
@keyframes crateKnock { 0%,48%,100% { transform:translateY(0); } 59% { transform:translateY(4px); } 68% { transform:translateY(-4px); } }
@media(max-width:390px) { .crate-dyle { left:-5px;width:95px;height:132px; }.crate-object { right:-5px; } }

.crate-stage-meta { display:flex;align-items:center;justify-content:space-between;gap:8px;max-width:338px;margin:-1px auto 12px;color:#c4d0cc;font-size:10px; }
.crate-stage-meta span:last-child { color:var(--crate-accent);font-weight:900; }
.crate-actions { display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;max-width:440px;margin:auto; }
.crate-actions[data-count="2"] { grid-template-columns:repeat(2,minmax(0,1fr)); }
.crate-actions[data-count="1"] { grid-template-columns:1fr; }
.crate-actions button { min-width:0;min-height:39px;padding:6px 8px;border:2px solid #0b1112;border-radius:8px;color:#f5f7ef;background:#354344;box-shadow:0 3px #111819;font-size:11px;font-weight:900;transition:transform .12s,background .12s; }
.crate-actions button:hover:not(:disabled) { background:#455653;transform:translateY(-2px); }
.crate-actions button:active:not(:disabled) { transform:translateY(2px);box-shadow:none; }
.crate-actions button:disabled { opacity:.45;cursor:default; }
.crate-actions .crate-open-one { color:#172021;background:var(--crate-accent); }
.crate-actions .crate-open-one:hover:not(:disabled) { background:#f3e0a7; }
.crate-actions .crate-buy { grid-column:1/-1;min-height:34px;color:#bfcfca;background:#1c2829; }
.crate-actions .currency-icon { display:inline-block;width:15px;height:15px;object-fit:contain;vertical-align:-3px;margin-left:4px; }
.crate-opening .crate-actions { pointer-events:none;opacity:.68; }

.crate-results { --crate-accent:#a5f247;margin-top:10px;padding:11px;border:2px solid #0b1112;border-left:4px solid #a5f247;border-radius:10px;background:#1e2929;box-shadow:0 3px #111819;transition:opacity .18s,transform .18s; }
.crate-results-pending { opacity:0;transform:translateY(8px); }
.crate-results-pending .crate-find { animation-play-state:paused; }
.crate-results-head { display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:9px; }
.crate-results-head h3 { color:#f0f4e7;font-size:19px;line-height:1.1; }
.crate-results-head strong { padding:4px 6px;border-radius:4px;color:#1e2523;background:#b4e7a0;font-size:9px;white-space:nowrap; }
.crate-find-grid { display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px; }
.crate-find { display:flex;align-items:center;gap:7px;min-width:0;min-height:55px;padding:5px 7px;border:1px solid #5a6a64;border-left:3px solid var(--find-color,#8b9c91);border-radius:6px;background:#2c3938;animation:crateFindIn .28s var(--delay) backwards cubic-bezier(.2,1,.4,1); }
.crate-find-new { border-color:var(--find-color,#a5f247);background:#35463b; }
.crate-find-new:first-child { grid-column:1/-1;min-height:68px; }
.crate-find-new:first-child .crate-find-art { flex-basis:53px;width:53px;height:54px; }
.crate-find-new:first-child .crate-find-art img { width:51px;height:52px; }
.crate-find-new:first-child .crate-find-copy b { font-size:13px; }
.crate-find-art,.crate-find-resource { flex:0 0 40px;display:grid;place-items:center;width:40px;height:41px;border-radius:4px;background:#192322;font-size:25px; }
.crate-find-art img { width:38px;height:39px;object-fit:contain; }
.crate-find-resource .currency-icon { width:28px;height:28px;object-fit:contain; }
.crate-find-copy { flex:1;min-width:0; }
.crate-find-copy b,.crate-find-copy span { display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap; }
.crate-find-copy b { color:#f1f6ee;font-size:10px; }.crate-find-copy span { color:#bdcfc4;font-size:9px; }
.crate-find em { align-self:start;padding:2px 3px;border-radius:2px;color:#162018;background:#b4e7a0;font-size:8px;font-style:normal;font-weight:900; }
@keyframes crateFindIn { from { opacity:0;transform:translateY(9px) scale(.97); } }
.crate-more,.crate-cache { margin-top:9px;border-top:1px solid #4a5c55; }
.crate-more summary,.crate-cache summary { padding:8px 2px 0;color:#cfdfd4;font-size:10px;font-weight:900;cursor:pointer; }
.crate-cache summary span { margin-left:4px;color:#8da498;font-weight:700; }
.crate-more .crate-find-grid { margin-top:8px; }
.crate-supplies { display:flex;flex-wrap:wrap;gap:5px;margin-top:8px; }
.crate-supplies>span { padding:4px 6px;border:1px solid #516159;border-radius:4px;color:#cedbd1;background:#2a3733;font-size:9px; }
.crate-supplies .currency-icon { display:inline-block;width:12px;height:12px;object-fit:contain;vertical-align:-2px; }
.crate-supplies b { color:#fff7dc; }

.crate-pool { margin:10px 0 4px;border:1px solid #52625e;border-radius:8px;background:#263130; }
.crate-pool>summary { padding:10px 12px;color:#cbd9d0;font-size:11px;font-weight:900;cursor:pointer; }
.crate-pool>summary span { margin-left:5px;color:#91aa9a; }
.crate-pool-grid { display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:6px;padding:0 8px 9px; }
.crate-pool-hero { min-width:0;padding:4px;border:1px solid var(--pool-color);border-radius:5px;background:#1b2525;text-align:center;opacity:.75; }
.crate-pool-hero[role=button] { cursor:pointer;opacity:1;transition:transform .12s,background .12s; }
.crate-pool-hero[role=button]:hover { transform:translateY(-3px);background:#354443; }
.crate-pool-hero img { width:100%;height:46px;object-fit:contain; }
