.leaderboard-row:hover{transform:translateX(2px);border-color:#97bd8a}
.leaderboard-row.you{border-color:#e2d879;background:linear-gradient(100deg,#414b35,#2a3732)}
.leaderboard-rank{display:grid;place-items:center;width:29px;height:29px;border:1px solid #556d60;border-radius:8px;background:#172420;color:#d3dcb4;font-size:10px}
.leaderboard-meter{height:7px;overflow:hidden;border:1px solid #8295814f;border-radius:9px;background:#101d20}
.leaderboard-meter i{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#7dc091,#e5d87d);box-shadow:0 0 8px #9ee49b52}
.leaderboard-score{display:grid;justify-items:end;color:#fff1b5}
