/* Battle is the hottest view: it keeps a full stage of filtered cutouts,
   status chrome and animated FX alive at once. On handheld touch screens,
   keep the silhouettes readable but remove the most expensive continuous
   compositor work. The simulation and one-shot skill effects still run. */
@media(pointer:coarse) and (max-width:700px){
  #battle .unit .body img{filter:saturate(1.04) contrast(1.02) drop-shadow(0 4px 3px #0009)}
  #battle .unit .shadow{filter:none}
  #battle .unit .hpmini.low{animation:none}
  #battle .unit .barnaby-companion{animation:none}
  #battle .unit.delilah-sample .body:after{animation:none;box-shadow:inset 0 0 8px #bd82ff55,0 0 7px #bd82ff99}
  #battle .poppy-sprite-bubble{animation:poppyBubbleIn .28s cubic-bezier(.15,1.5,.35,1) both}
  #battle #vignette{box-shadow:inset 0 0 80px 24px rgba(0,0,0,.72)}
  #battle .collab-boss-intro:before{animation:none}
}

/* Keep the painted detail, but stop continuous decorative motion from
   competing with scrolling and battle rendering on touch devices. */
@media(pointer:coarse){
  .home-stage-cloud,.home-lead-star,.home-toon-crown,
  .home-stage-next,.home-continue-icon:before,.home-collect-card.ready,
  .home-collect-badge,.home-mastery .bar>div,
