/* ==== battle-mutations.css ==== */
/* Combat modifier panels shared by events, Endless, and battle. */
.event-mutation-stage,.event-mutation-guide,.endless-mutation-preview{box-sizing:border-box}
.event-banner-mutation{display:inline-block;width:max-content;max-width:100%;margin-top:7px;padding:4px 7px;border:1px solid #8c90a5;border-radius:5px;color:#dce4ee;background:#252b3d;font-size:9px;font-weight:800;letter-spacing:.05em}
.event-mutation-stage{margin:15px 0;padding:14px;border:1px solid #727d99;border-radius:12px;color:#f3f5fa;background:#242b3e;box-shadow:0 8px 22px #090d1c55}
.event-mutation-stage-head{display:flex;align-items:flex-start;gap:12px;margin-bottom:12px}
.event-mutation-stage-head>div{min-width:0;flex:1}
.event-mutation-stage-head small{display:block;color:#b8c5db;font-size:10px;font-weight:800;letter-spacing:.08em}
.event-mutation-stage-head h2{margin:3px 0 0;color:#fff;font-size:19px;line-height:1.2}
.event-mutation-stage-head p{margin:5px 0 0;color:#bac4d5;font-size:11px;line-height:1.4}
.event-mutation-stage-head strong{flex:none;padding:5px 8px;border:1px solid #a7b5ce;border-radius:5px;color:#e6edf9;background:#303a51;font-size:10px;white-space:nowrap}
.event-mutation-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}
.mutation-card{min-width:0;padding:10px;border:1px solid #515e78;border-radius:7px;color:#f5f7fa;background:#30394f}
.mutation-card small{display:block;color:#acbbd4;font-size:9px;font-weight:800;letter-spacing:.06em}
.mutation-card b{display:block;margin:2px 0 3px;font-size:12px;line-height:1.2}
.mutation-card p{margin:0;color:#d4dce9;font-size:11px;line-height:1.35}
.mutation-card.compact{padding:7px}
.mutation-card.compact b{font-size:11px}
.mutation-card.compact p{font-size:10px}
.event-mutation-route{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin:12px 0}
.event-mutation-route.solo{grid-template-columns:minmax(0,1fr)}
.event-mutation-route>div{min-width:0;padding:9px;border:1px solid #5f6d88;border-radius:7px;background:#292f43;color:#e6ecf6}
.event-mutation-route small{display:block;margin-bottom:4px;color:#b8c5db;font-size:9px;font-weight:800;letter-spacing:.08em}
.event-mutation-route b{display:block;font-size:10px;line-height:1.4;font-weight:650}
.event-mutation-guide{margin:10px 0 17px;border:1px solid #5f6d88;border-radius:7px;background:#252b3e;color:#e9eef7}
.event-mutation-guide summary{padding:11px;cursor:pointer;font-size:11px;font-weight:800;list-style:none}
.event-mutation-guide summary::-webkit-details-marker{display:none}
.event-mutation-guide summary span{float:right}
.event-mutation-guide[open] summary span{transform:rotate(180deg)}
.event-mutation-guide>.event-mutation-cards{max-height:330px;overflow:auto;padding:9px;border-top:1px solid #5f6d88}
.stage-mutation-count{display:block;margin-top:4px;color:#d1dbed;font-size:9px;font-weight:800}
.cookie-stages button em{display:block;margin-top:4px;color:#ead5b6;font-size:9px;font-style:normal;font-weight:800}
.cookie-stages button.selected em{color:#502b37}
.cookie-stage-threat{padding:4px 7px;border:1px solid #aa967f;border-radius:5px;background:#4d3c42;color:#f1daba;font-size:9px;font-weight:800}
.cookie-mutation-stage{margin-top:12px}
.endless-mutation-preview{margin:10px 0;padding:10px;border:1px solid #8b91aa;border-radius:8px;background:#2b3042;color:#edf1f7}
.endless-mutation-preview>strong{display:block;margin-bottom:8px;font-size:10px;letter-spacing:.06em}
.endless-mutation-preview>div{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}
.endless-mutation-hint{margin:8px 0;padding:8px 9px;border:1px solid #69738c;border-radius:7px;color:#d7dfed;background:#2b3042;font-size:10px;line-height:1.4}
.mutation-live{position:absolute;z-index:35;left:8px;right:8px;top:calc(53px + env(safe-area-inset-top,0px));max-width:420px;margin:auto;pointer-events:auto;color:#f3f6fb}
.mutation-live summary{display:flex;align-items:center;gap:8px;width:max-content;max-width:100%;margin:auto;padding:6px 10px;border:1px solid #9eacc4;border-radius:6px;background:#242d42e8;box-shadow:0 3px 11px #090d1c9c;cursor:pointer;list-style:none;font-size:10px;font-weight:800;letter-spacing:.05em}
.mutation-live summary::-webkit-details-marker{display:none}
.mutation-live summary i{font-size:13px;font-style:normal}
.mutation-live[open] summary i{transform:rotate(180deg)}
.mutation-live-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;max-height:210px;overflow:auto;margin-top:7px;padding:8px;border:1px solid #74839e;border-radius:8px;background:#20283bf2;box-shadow:0 5px 16px #050511b8}
.mutation-battle-pop{position:absolute;z-index:60;min-width:70px;padding:5px 8px;border:1px solid #7d93b8;border-radius:5px;color:#f1f6ff;background:#2a3854;box-shadow:0 2px 8px #101522aa;font-size:10px;font-weight:800;text-align:center;white-space:nowrap;pointer-events:none;transform:translateX(-50%);animation:mutationBattlePop 1.15s ease-out forwards}
@keyframes mutationBattlePop{0%{opacity:0;transform:translate(-50%,8px)}20%{opacity:1;transform:translate(-50%,-4px)}75%{opacity:1}100%{opacity:0;transform:translate(-50%,-34px)}}
@media(max-width:430px){.event-mutation-stage-head h2{font-size:17px}.event-mutation-cards,.event-mutation-route,.endless-mutation-preview>div,.mutation-live-list{grid-template-columns:1fr}.event-mutation-route{gap:5px}}
@media(prefers-reduced-motion:reduce){.mutation-battle-pop{animation:none}}

/* ==== event-interiors.css ==== */
/* Event interiors: compact navigation, clear battle handoff, distinct reward views. */
