/* The drawing event reads as a sketchbook workspace instead of a pile of cards. */
.draw-event-page{max-width:1020px;margin-bottom:35px;padding:0 2px;color:#f4ebf8}.draw-header{position:relative;margin-bottom:8px;padding:12px;border:2px solid #b784c7;border-radius:13px;background:linear-gradient(110deg,#552e58,#28233e);box-shadow:0 4px #1b1930}.draw-title-group h1{font-size:clamp(17px,4vw,23px)}.draw-event-status{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:7px;margin:0 0 10px}.draw-event-status>div{display:grid;gap:2px;padding:8px 10px;border:2px solid #9a729f;border-radius:9px;background:linear-gradient(145deg,#493254,#2d2c47);box-shadow:0 3px #171828}.draw-event-status small{font-size:8px;font-weight:1000;letter-spacing:.7px;color:#d6b7da}.draw-event-status b{color:#ffe3ac;font-size:17px}.draw-main-grid{gap:10px}.draw-sketch-board{border:3px solid #ba8aaf;background:linear-gradient(#443047,#251e36);box-shadow:inset 0 2px #ffffff25,0 5px #171525}.draw-gourdy-box{margin-bottom:10px}.draw-rates-card,.draw-hero-preview-card{border-radius:12px}
