@media(max-width:520px){.event-dossier-topbar{margin:-10px -10px 8px;padding:7px 8px}.event-dossier-back-btn{padding:5px 8px;font-size:9px}.event-dossier-pager-btn{width:30px;height:31px}.event-interior-panel{padding:9px}.event-interior-tab{min-height:41px;gap:4px;font-size:10px}.event-interior-tab i{font-size:15px}.event-interior-battle .event-stage-controls{flex-wrap:wrap}.event-interior-battle .event-dossier-fight-bar{grid-template-columns:1fr}.event-interior-battle .event-raid-ticket{max-width:none;min-height:32px}.event-interior-reward-summary b{font-size:14px}.cookie-event-summary{gap:4px;padding:7px}.cookie-event-summary>div{padding:6px}.cookie-event-summary b{font-size:15px}.cookie-event-summary small{font-size:6px}.cookie-room{padding:10px}.draw-event-status{gap:4px}.draw-event-status>div{padding:6px}.draw-event-status b{font-size:14px}.draw-event-status small{font-size:6px}}
