  .ff7-member { flex: 1 1 140px; }
  .ff7-member img { width: 44px; height: 44px; }
  .ff7-member u { max-width: 70px; }
  .ff7-commands button, .ff7-modes button { font-size: 15px; }
  .ff7-place { min-width: 110px; }
  .ff7-bust { bottom: 160px; height: 44vh; }
  .ff7-bust.toon { height: 34vh; }
