}

/* ---------- FF7 party members only: battle status windows ---------- */
#battle .unitcard.ff7-card {
  width: 74px; flex: 0 1 74px; padding: 3px 4px 4px; border-radius: 5px;
  border: 2px solid #d9dbe4 !important;
  background: linear-gradient(162deg, #3c4fd0 0%, #2232a8 38%, #121c78 72%, #070c48 100%) !important;
  box-shadow: 0 0 0 2px #3b3d4c, inset 0 0 0 1px #6c74b8 !important;
