}
#battle .unitcard.ff7-card .uc-lv, #battle .unitcard.ff7-card .uc-stars { display: none; }
#battle .unitcard.ff7-card .uc-port { width: 40px; height: 40px; border-radius: 2px; border: 1px solid #c8cad8; background: #0b0f3a; box-shadow: none; order: 0; }
#battle .unitcard.ff7-card .uc-port img { width: 100%; height: 100%; object-fit: cover; object-position: 50% 15%; filter: none; }
.ff7c-name { order: 1; font: 700 10px var(--ff7-font); line-height: 1.1; margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; }
.ff7c-hp { order: 2; display: flex; justify-content: space-between; width: 100%; font: 700 9px var(--ff7-font); line-height: 1.1; }
