#battle .unitcard.ff7-card .uc-hpwrap { order: 3; width: 100%; height: 3px; border: 0; border-radius: 0; background: #1a2058; margin-top: 1px; }
#battle .unitcard.ff7-card .uc-hp { background: linear-gradient(90deg, #5ee6ff, #b9f3ff); }
.ff7c-limit { order: 4; align-self: flex-start; font: 800 7px var(--ff7-font); letter-spacing: .08em; color: #ff9fd6; margin-top: 2px; line-height: 1; }
#battle .unitcard.ff7-card .uc-enwrap { order: 5; width: 100%; height: 4px; border: 0; border-radius: 0; background: #1a2058; margin-top: 1px; box-shadow: none; }
#battle .unitcard.ff7-card .uc-enwrap::before { display: none; }
#battle .unitcard.ff7-card .uc-en { border-radius: 0; background: linear-gradient(90deg, #ff6ab0, #ffd0ea); }
#battle .unitcard.ff7-card.ff7-limit-ready .uc-en { animation: ff7-limit-flash .5s steps(2) infinite; }
#battle .unitcard.ff7-card.ff7-limit-ready .ff7c-limit { color: #fff; }
@keyframes ff7-limit-flash { 50% { background: linear-gradient(90deg, #ffffff, #ffe27a); } }
#battle .unitcard.ff7-card .uc-sts { order: 6; width: 100%; }
