.unit.ff7-unit .nameplate {
  font: 700 10px var(--ff7-font); color: #fff; text-shadow: 1px 1px 0 #1a1a26; padding: 1px 6px;
  background: linear-gradient(162deg, #3c4fd0, #121c78); border: 1px solid #d9dbe4; border-radius: 3px;
}
