/* ---------- FF7 victory screens ---------- */
#battleEnd.ff7-victory { background: #000 !important; display: flex; align-items: center; justify-content: center; cursor: pointer; padding: 14px 10px; }
.ff7v-page { width: min(600px, 100%); display: flex; flex-direction: column; gap: 6px; animation: ff7-fade-in .35s ease; font-family: var(--ff7-font); }
