.ff7v-exp s { display: block; height: 100%; width: 0; background: linear-gradient(180deg, #ffb0b8, #d04a5a); transition: width 1s ease; }
.ff7v-items p { display: flex; align-items: center; gap: 8px; margin: 3px 0; font-size: 14px; }
.ff7v-items span { flex: 1; }
.ff7v-bag { width: 14px; height: 14px; border-radius: 50% 50% 40% 40%; background: radial-gradient(circle at 35% 30%, #d8d8d8, #6a6a6a); }

/* ---------- FF7 hero profile ---------- */
.hero-profile.ff7-profile { font-family: var(--ff7-font); background: radial-gradient(ellipse at 50% 0%, #1a1440, #07061a 70%) !important; }
.hero-profile.ff7-profile :is(section, article, header, .hero-profile-top) {
