/* KH-BEGIN */
/* ============================================================
   KINGDOM HEARTS · HALLOWEEN TOWN
   KH2-style menus: royal-blue backdrop, slanted command bars with a
   chevron tip, HP gauges and an Information bar, in Halloween orange.
   ============================================================ */
:root {
  --kh-font: "Trebuchet MS", "Segoe UI", Arial, sans-serif;
  --kh-ink: #eef3ff; --kh-dim: #8d9bd8; --kh-cyan: #7fe3ff; --kh-gold: #ffd54a; --kh-orange: #ff8a1f; --kh-night: #040720;
  --kh-edge: #6f95ff;
  --kh-slant: polygon(0 0, calc(100% - 14px) 0, 100% 50%, calc(100% - 14px) 100%, 0 100%);
}
@keyframes kh-sheen { 0% { transform: translateX(-120%); } 60%, 100% { transform: translateX(220%); } }
@keyframes kh-float { 0% { transform: translateY(20px) scale(.6); opacity: 0; } 20% { opacity: .9; } 100% { transform: translateY(-110vh) scale(1.1); opacity: 0; } }
@keyframes kh-pulse { 50% { filter: brightness(1.35); } }
@keyframes kh-nudge { 50% { transform: translateX(3px); } }

/* ---------- screen shell ---------- */
.kh-event { position: relative; min-height: 100%; padding: 10px; font-family: var(--kh-font); color: var(--kh-ink); overflow: hidden;
  background: radial-gradient(ellipse at 18% -8%, #3050ee 0%, #17209a 34%, #090d4c 68%, #04061f 100%) fixed; }
.kh-event::before { content: ""; position: absolute; inset: 0; pointer-events: none; opacity: .3; filter: saturate(1.2);
  background: linear-gradient(180deg, #04061f 0%, transparent 38%, rgba(255, 126, 24, .28) 100%), url("../assets/kh/bg/town.png") center bottom / cover no-repeat; }
.kh-event > * { position: relative; }
.kh-sky { position: absolute !important; inset: 0; pointer-events: none; overflow: hidden; z-index: 0; }
.kh-sky i { position: absolute; bottom: -20px; width: 7px; height: 7px; border-radius: 50%; background: #ffb347; box-shadow: 0 0 10px 2px rgba(255, 150, 40, .7); animation: kh-float 9s linear infinite; }
.kh-sky i:nth-child(1) { left: 8%; animation-delay: 0s; } .kh-sky i:nth-child(2) { left: 26%; animation-delay: 2.4s; width: 5px; height: 5px; }
.kh-sky i:nth-child(3) { left: 47%; animation-delay: 5s; } .kh-sky i:nth-child(4) { left: 66%; animation-delay: 1.2s; background: #a9c4ff; box-shadow: 0 0 10px 2px rgba(130, 170, 255, .8); }
.kh-sky i:nth-child(5) { left: 82%; animation-delay: 3.6s; width: 5px; height: 5px; } .kh-sky i:nth-child(6) { left: 94%; animation-delay: 6.4s; background: #a9c4ff; }
.kh-head { position: relative; z-index: 1; margin-bottom: 10px; }
.kh-grid { position: relative; z-index: 1; display: grid; grid-template-columns: 236px minmax(0, 1fr); gap: 12px; align-items: start; }
.kh-side { display: flex; flex-direction: column; gap: 10px; min-width: 0; }
.kh-mainwrap { display: flex; flex-direction: column; gap: 10px; min-width: 0; max-width: 100%; }
.kh-main, .kh-main-inner, .kh-detail, .kh-info, .kh-head, .kh-party-win { box-sizing: border-box; min-width: 0; max-width: 100%; }
.kh-event, .kh-grid { box-sizing: border-box; max-width: 100%; }

.kh-win, .kh-main, .kh-party-win, .kh-head {
  background: linear-gradient(180deg, rgba(10, 16, 78, .92), rgba(4, 7, 36, .94)); border: 2px solid var(--kh-edge); border-radius: 10px;
  box-shadow: 0 0 0 2px #05072a, inset 0 0 0 1px rgba(190, 210, 255, .28), 0 8px 22px rgba(0, 0, 0, .5); }

/* ---------- opening curtain ---------- */
.kh-intro { position: absolute !important; inset: 0; z-index: 50; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; pointer-events: none;
  background: radial-gradient(ellipse at 50% 55%, #1a1f9a 0%, #060830 70%, #020316 100%); animation: kh-intro 2.3s ease forwards; }
.kh-intro b { font: 900 clamp(26px, 8vw, 46px) var(--kh-font); letter-spacing: .16em; color: #fff; text-shadow: 0 0 26px rgba(255, 138, 31, .95), 0 3px 0 #02041a; animation: kh-introtext 2.3s ease forwards; }
.kh-intro small { font: 800 12px var(--kh-font); letter-spacing: .5em; text-transform: uppercase; color: #ffb878; }
.kh-intro-moon { width: 96px; height: 96px; border-radius: 50%; background: radial-gradient(circle at 36% 32%, #fff6c8, #ffd36b 55%, #e08a1d); box-shadow: 0 0 60px 14px rgba(255, 170, 60, .55); animation: kh-moonrise 2.3s ease-out forwards; }
@keyframes kh-intro { 0%, 70% { opacity: 1; } 100% { opacity: 0; visibility: hidden; } }
@keyframes kh-introtext { 0% { opacity: 0; letter-spacing: .5em; } 35% { opacity: 1; letter-spacing: .16em; } }
@keyframes kh-moonrise { 0% { transform: translateY(70px) scale(.6); opacity: 0; } 40% { opacity: 1; } 100% { transform: translateY(-4px) scale(1); } }

/* ---------- command menu ---------- */
.kh-cmd-title small { display: inline-block; padding: 2px 18px 2px 8px; font: 800 10px var(--kh-font); letter-spacing: .24em; color: #cfe0ff;
  background: linear-gradient(90deg, #1a2bb8, #0a1058); clip-path: var(--kh-slant); border-left: 3px solid var(--kh-gold); }
.kh-cmd { display: flex; flex-direction: column; gap: 5px; }
.kh-cmd button, .kh-row, .kh-classic-back, .kh-btn {
  position: relative; display: flex; align-items: center; gap: 8px; width: 100%; text-align: left; cursor: pointer; color: var(--kh-ink);
  font: 800 15px var(--kh-font); letter-spacing: .06em; text-transform: uppercase; text-shadow: 0 2px 0 #02041a;
  background: linear-gradient(180deg, #0c1164 0%, #04062a 55%, #0a1060 100%); border: 0; border-left: 4px solid #8fb2ff; padding: 9px 22px 9px 10px; min-height: 40px;
  clip-path: var(--kh-slant); overflow: hidden; transition: filter .15s, transform .12s; }
.kh-cmd button::after, .kh-row::after { content: ""; position: absolute; inset: 0; background: linear-gradient(100deg, transparent 35%, rgba(255, 255, 255, .22) 50%, transparent 65%); transform: translateX(-120%); pointer-events: none; }
.kh-cmd button:hover::after, .kh-row:hover:not(:disabled)::after { animation: kh-sheen .8s ease; }
.kh-cmd button:hover, .kh-row:hover:not(:disabled), .kh-btn:hover:not(:disabled) { filter: brightness(1.25); transform: translateX(3px); }
.kh-cmd button.on, .kh-row.sel { background: linear-gradient(180deg, #33b5ff 0%, #1262e8 48%, #0a3cc0 100%); border-left-color: var(--kh-gold); color: #fff; box-shadow: inset 0 0 18px rgba(160, 230, 255, .45); animation: kh-pulse 1.6s ease-in-out infinite; }
.kh-cmd .kh-ic { width: 22px; text-align: center; filter: drop-shadow(0 0 4px rgba(255, 170, 60, .8)); }
.kh-cmd .kh-exit { border-left-color: #ff8a5a; color: #ffd0c0; }
.kh-chev { position: absolute; right: 7px; top: 50%; width: 9px; height: 9px; margin-top: -5px; border-top: 3px solid var(--kh-gold); border-right: 3px solid var(--kh-gold); transform: rotate(45deg); opacity: .35; }
.kh-cmd button.on .kh-chev, .kh-row.sel .kh-chev, .kh-btn .kh-chev { opacity: 1; animation: kh-nudge .8s ease infinite; }
.kh-btn .kh-chev { position: static; margin: 0 2px 0 0; flex: 0 0 9px; }

/* ---------- party gauges (the Sora-face HP gauge) ---------- */
.kh-party-win { padding: 10px; max-height: 58vh; overflow-y: auto; scrollbar-color: #6f95ff #060a38; }
.kh-party { display: flex; flex-direction: column; gap: 10px; }
.kh-member { display: flex; gap: 8px; align-items: center; }
.kh-face { position: relative; flex: 0 0 54px; width: 54px; height: 54px; border-radius: 50%; overflow: hidden; background: radial-gradient(circle at 40% 30%, #4a5ad0, #0b1050); border: 3px solid #cfdcff; box-shadow: 0 0 0 2px #05072a, 0 0 10px rgba(110, 160, 255, .55); }
.kh-face img { width: 100%; height: 100%; object-fit: contain; object-position: 50% 80%; image-rendering: auto; }
.kh-gauge-box { min-width: 0; flex: 1; }
.kh-gauge-box b { display: block; font: 800 13px var(--kh-font); letter-spacing: .05em; text-shadow: 0 2px 0 #02041a; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.kh-gauge { display: flex; align-items: center; gap: 4px; margin-top: 2px; }
.kh-gauge span { font: 900 9px var(--kh-font); color: #fff; background: #1a2370; border: 1px solid #aebfff; padding: 0 3px; border-radius: 2px; }
.kh-gauge u { flex: 1; height: 8px; background: #2a2f4e; border: 1px solid #0a0d2c; border-radius: 4px 0 0 4px; overflow: hidden; clip-path: polygon(0 0, 100% 0, calc(100% - 6px) 100%, 0 100%); }
.kh-gauge s { display: block; height: 100%; width: 100%; background: linear-gradient(180deg, #d7ffa5, #7fe03a 50%, #3f9d1d); }
.kh-gauge-box small { font: 700 11px var(--kh-font); color: var(--kh-cyan); }
.kh-gauge-box small i { font-style: normal; color: var(--kh-gold); }
.kh-gauge-box small em { font-style: normal; font-size: 9px; color: #ffb4e2; border: 1px solid #ffb4e2; padding: 0 3px; border-radius: 3px; margin-left: 3px; }

/* ---------- header, main, information ---------- */
.kh-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 8px 16px; background: linear-gradient(90deg, rgba(255, 138, 31, .24), rgba(10, 16, 78, .92) 40%); }
.kh-logo b { display: block; font: 900 22px var(--kh-font); letter-spacing: .12em; color: #fff; text-shadow: 0 0 12px rgba(255, 138, 31, .8), 0 2px 0 #02041a; }
.kh-logo small { font: 700 11px var(--kh-font); letter-spacing: .2em; text-transform: uppercase; color: #ffb878; }
.kh-wallet { display: flex; gap: 14px; }
.kh-wallet span { display: flex; align-items: baseline; gap: 6px; font: 900 18px var(--kh-font); color: #fff; }
.kh-wallet small { font: 700 9px var(--kh-font); letter-spacing: .16em; color: var(--kh-gold); }
.kh-munny { display: inline-block; width: 15px; height: 15px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #fff6b0, #ffc928 55%, #b97a00); box-shadow: 0 0 6px rgba(255, 210, 60, .8); vertical-align: -2px; }
.kh-heart { color: #ff5a78; font-style: normal; text-shadow: 0 0 8px rgba(255, 70, 110, .8); }
.kh-main { padding: 12px 14px; min-height: 280px; }
.kh-main-inner { display: flex; flex-direction: column; gap: 12px; }
.kh-info { padding: 8px 14px 10px; background: linear-gradient(180deg, #02030f, #0a0e3a); border: 2px solid #4f6fe0; border-radius: 12px; box-shadow: inset 0 0 0 2px #05072a, 0 0 14px rgba(70, 110, 255, .35); }
.kh-info small { font: 900 10px var(--kh-font); letter-spacing: .26em; color: var(--kh-cyan); }
.kh-info p { margin: 2px 0 0; min-height: 20px; font: 600 14px/1.4 var(--kh-font); color: #e8eeff; }

/* ---------- lists ---------- */
.kh-list { display: flex; flex-direction: column; gap: 5px; max-height: 340px; overflow-y: auto; padding: 2px 8px 2px 2px; scrollbar-color: #6f95ff #060a38; }
.kh-row { font-size: 14px; }
.kh-row.locked, .kh-row:disabled { color: #5d68a8; cursor: default; filter: saturate(.4); border-left-color: #3a4580; }
.kh-row img { width: 38px; height: 38px; object-fit: contain; object-position: 50% 85%; flex: 0 0 38px; border-radius: 50%; background: radial-gradient(circle at 40% 30%, #4a5ad0, #0b1050); border: 2px solid #b9cbff; }
.kh-row { min-width: 0; } .kh-label { overflow: hidden; }
.kh-kind { width: 20px; text-align: center; }
.kh-row.battle .kh-kind { filter: hue-rotate(-30deg); }
.kh-label { flex: 1; display: flex; flex-direction: column; min-width: 0; }
.kh-label small { font: 600 11px var(--kh-font); letter-spacing: .02em; text-transform: none; color: #b7c3f3; }
.kh-count { display: flex; gap: 6px; align-items: center; font: 800 12px var(--kh-font); color: var(--kh-gold); white-space: nowrap; margin-right: 10px; }
.kh-count em { font-style: normal; width: 20px; height: 20px; display: grid; place-items: center; border: 1px solid #5865a8; border-radius: 3px; color: #7f8ccc; font-size: 11px; }
.kh-count em.ok { border-color: #8bf5a6; color: #8bf5a6; } .kh-count em.ok.hard { border-color: #ff8a8a; color: #ff8a8a; }
.kh-shop .kh-row, .kh-cast .kh-row { cursor: default; }
.kh-cast .kh-row { cursor: pointer; }
.kh-shop .kh-btn { width: auto; flex: 0 0 auto; margin-right: 10px; min-height: 32px; padding: 4px 22px 4px 10px; font-size: 12px; }
.kh-shop .kh-label, .kh-cast .kh-label { font-size: 13px; }
.kh-shop .kh-row { min-height: 52px; } .kh-shop .kh-label small { white-space: normal; line-height: 1.25; }
.kh-shop .kh-btn { gap: 5px; }

.kh-detail { border-top: 2px solid rgba(143, 178, 255, .35); padding-top: 10px; display: flex; flex-direction: column; gap: 9px; }
.kh-detail h3, .kh-result h3 { margin: 0; font: 900 21px var(--kh-font); letter-spacing: .08em; text-transform: uppercase; color: #fff; text-shadow: 0 0 10px rgba(255, 138, 31, .7), 0 2px 0 #02041a; }
.kh-detail p { margin: 0; }
.kh-sub { margin: 0; font: 600 12px var(--kh-font); color: #aab8ee; }
.kh-lore { font: 600 14px/1.5 var(--kh-font); color: #dfe7ff; border-left: 3px solid var(--kh-orange); padding-left: 10px; }
.kh-modes { display: flex; gap: 8px; }
.kh-modes button { flex: 0 0 auto; display: inline-flex; gap: 6px; align-items: center; min-height: 34px; padding: 4px 22px 4px 14px; color: #c5d1ff; cursor: pointer;
  font: 800 13px var(--kh-font); letter-spacing: .08em; text-transform: uppercase; background: #070b3c; border: 0; border-left: 3px solid #5a74d8; clip-path: var(--kh-slant); }
.kh-modes button.on { background: linear-gradient(180deg, #ff9a3a, #d6540c); color: #fff; border-left-color: var(--kh-gold); }
.kh-modes button:disabled { opacity: .4; cursor: default; }
.kh-modes small { color: var(--kh-gold); font-size: 10px; }
.kh-enemies, .kh-drops { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fill, minmax(190px, 1fr)); gap: 5px 12px; }
.kh-enemies li, .kh-drops li { display: flex; align-items: center; gap: 8px; padding: 3px 8px; background: rgba(6, 10, 60, .7); border: 1px solid #3a4fb0; border-radius: 6px; cursor: pointer; font: 700 13px var(--kh-font); }
.kh-enemies li:hover { border-color: var(--kh-gold); }
.kh-enemies img, .kh-drops img { width: 34px; height: 34px; object-fit: contain; object-position: 50% 85%; }
.kh-enemies span, .kh-drops span { flex: 1; }
.kh-enemies i { font-style: normal; font-size: 9px; color: #ff9a8a; border: 1px solid; padding: 0 3px; border-radius: 3px; margin-left: 3px; }
.kh-reward { font: 600 13px var(--kh-font); color: #dbe4ff; }
.kh-reward em, .kh-result em { font-style: normal; color: var(--kh-gold); font-weight: 900; }
.kh-btn { max-width: 100%; white-space: normal; width: auto; align-self: flex-start; min-height: 40px; padding: 8px 26px 8px 12px; background: linear-gradient(180deg, #ffab48, #e0600c 55%, #a83a08); border-left-color: #fff2a8; color: #fff; }
.kh-btn:disabled { opacity: .4; cursor: default; filter: saturate(.4); }
.kh-btn.kh-kits { background: linear-gradient(180deg, #33b5ff, #1262e8 60%, #0a3cc0); }

/* beasts */
.kh-beast { position: relative; }
.kh-beast-art { display: grid; place-items: center; height: 170px; border-radius: 10px; background: radial-gradient(ellipse at 50% 80%, rgba(255, 138, 31, .35), transparent 65%), linear-gradient(180deg, #0a0e46, #04061f); border: 1px solid #3a4fb0; }
.kh-beast-art img { max-height: 150px; max-width: 80%; object-fit: contain; filter: drop-shadow(0 10px 12px rgba(0, 0, 0, .7)); animation: kh-bob 2.6s ease-in-out infinite; }
@keyframes kh-bob { 50% { transform: translateY(-6px); } }
.kh-skillnames { list-style: none; margin: 0; padding: 0; display: flex; flex-wrap: wrap; gap: 6px; }
.kh-skillnames li { display: flex; align-items: center; gap: 6px; padding: 3px 10px; border: 1px solid var(--rc); border-radius: 12px; font: 700 12px var(--kh-font); background: rgba(5, 8, 40, .8); }
.kh-skillnames i { width: 8px; height: 8px; border-radius: 50%; background: var(--rc); }
.kh-classic-art { display: flex; justify-content: center; gap: 8px; height: 130px; align-items: flex-end; border-radius: 10px; background: linear-gradient(180deg, #0a0e46, #04061f); border: 1px solid #3a4fb0; padding-top: 10px; }
.kh-classic-art img { height: 110px; width: 110px; object-fit: contain; object-position: 50% 100%; image-rendering: pixelated; filter: drop-shadow(0 6px 8px rgba(0, 0, 0, .7)); }

/* ---------- modals ---------- */
.kh-team, .kh-result, .kh-kit { display: flex; flex-direction: column; gap: 10px; padding: 12px 14px; color: var(--kh-ink); font-family: var(--kh-font);
  background: linear-gradient(180deg, #0c1370, #04062a); border: 2px solid var(--kh-edge); border-radius: 10px; box-shadow: 0 0 0 2px #05072a, 0 0 18px rgba(80, 120, 255, .4); }
.kh-team-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(112px, 1fr)); gap: 8px; }
.kh-team-grid button { position: relative; display: flex; flex-direction: column; align-items: center; gap: 2px; padding: 8px 6px; cursor: pointer; color: var(--kh-ink);
  background: rgba(6, 10, 60, .75); border: 2px solid #3a4fb0; border-radius: 8px; font: 700 12px var(--kh-font); }
.kh-team-grid button.on { border-color: var(--kh-gold); background: linear-gradient(180deg, rgba(255, 138, 31, .3), rgba(10, 16, 78, .8)); box-shadow: 0 0 10px rgba(255, 190, 70, .45); }
.kh-team-grid img { width: 60px; height: 60px; object-fit: contain; object-position: 50% 85%; }
.kh-team-grid small { color: var(--kh-cyan); font-size: 10px; }
.kh-team-foot { display: flex; align-items: center; gap: 10px; }
.kh-team-foot span { margin-right: auto; font: 900 15px var(--kh-font); }
.kh-kit header { display: flex; gap: 12px; align-items: center; }
.kh-kit header img { width: 76px; height: 76px; object-fit: contain; border-radius: 50%; border: 3px solid #cfdcff; background: radial-gradient(circle at 40% 30%, #4a5ad0, #0b1050); }
.kh-kit header p { margin: 0; font-size: 13px; }
.kh-skill { border-top: 1px solid rgba(143, 178, 255, .3); padding-top: 8px; }
.kh-skill h4 { margin: 2px 0 4px; font: 900 16px var(--kh-font); letter-spacing: .05em; }
.kh-skill .sk-desc-root { font-size: 12.5px; line-height: 1.45; color: #e2e8ff; }
.kh-result p { margin: 2px 0; font: 700 15px var(--kh-font); }

/* ---------- event board banner ---------- */
.event-banner.kh-banner-card { background: linear-gradient(90deg, rgba(4, 6, 36, .94) 0 46%, rgba(255, 120, 20, .22)), url("../assets/kh/bg/square.png") center 40% / cover; border-color: #6f95ff; box-shadow: inset 0 0 0 2px #05072a, 0 0 0 1px #aabfff, 0 4px #05071b; }
.event-banner.kh-banner-card::after { content: "HALLOWEEN"; position: absolute; z-index: 5; left: 8px; top: 6px; padding: 2px 18px 2px 6px; color: #ffe946; background: linear-gradient(90deg, #172b91, #11184f); border: 1px solid #758eff; font-size: 6px; font-weight: 900; letter-spacing: 1.6px; clip-path: polygon(0 0, 100% 0, 83% 100%, 0 100%); }
.event-banner.kh-banner-card .event-crest { background: #ff8a1f; color: #2a0f00; border-color: #ffd28a; }
.event-banner.kh-banner-card .event-copy small { color: #ffb878; }
.event-banner.kh-banner-card .event-copy strong { font-family: var(--kh-font); font-style: italic; letter-spacing: -.4px; }
.event-banner.kh-banner-card .event-meter u { background: linear-gradient(90deg, #ff8a1f, #ffe08a); }
.event-banner.kh-banner-card .kh-art img { image-rendering: pixelated; height: 100px; max-width: 36%; }
.event-banner.kh-banner-card .kh-art { width: 56%; }

/* ---------- classic Door Opens, in the new coat of paint ---------- */
.kh-classic-back { position: absolute; right: 60px; top: 6px; width: auto; min-height: 30px; padding: 4px 22px 4px 10px; font-size: 11px; background: linear-gradient(180deg, #ffab48, #c8500b); border-left-color: #fff2a8; z-index: 3; }
.event-dossier-topbar { position: relative; }
.event-banner.kh-classic-banner { border-color: #ff9a3a; background: linear-gradient(90deg, rgba(4, 6, 36, .95) 0 47%, rgba(255, 120, 20, .25) 70%, rgba(4, 6, 36, .85)), url("../assets/kh/bg/hill.png") center 50% / cover; box-shadow: inset 0 0 0 2px #05072a, 0 0 0 1px #ffc78a, 0 4px #05071b; }
.event-banner.kh-classic-banner::after { content: "CLASSIC"; color: #2a0f00; background: linear-gradient(90deg, #ffb347, #ff8a1f); border-color: #ffd9a0; }
.event-dossier.collab.kh-classic { background: radial-gradient(ellipse at 15% -10%, #2f4be8, #121a82 40%, #060a40 85%); border-color: #6f95ff; font-family: var(--kh-font); }
.event-dossier.collab.kh-classic .event-dossier-hero { background: linear-gradient(90deg, rgba(4, 6, 36, .94) 0 45%, rgba(255, 120, 20, .22)), url("../assets/kh/bg/hill.png") center / cover; border-color: #6f95ff; }
.event-dossier.collab.kh-classic .event-dossier-copy small, .event-dossier.collab.kh-classic .event-dossier-prize b, .event-dossier.collab.kh-classic .event-wave-card span { color: #ffb878; }
.event-dossier.collab.kh-classic h2.sec { border-left-color: var(--kh-orange); background: linear-gradient(90deg, #2a40c8, #101873 72%, transparent); }
.event-dossier.collab.kh-classic .event-stage.selected { background: linear-gradient(180deg, #ff9a3a, #c8500b); }
.event-dossier.collab.kh-classic .event-dossier-fight { background: linear-gradient(180deg, #ffab48, #d1560c 60%, #8c2e06); border-color: #fff2a8; }

/* ---------- battle: banner, Heartless KO, overlays, targeting ---------- */
.kh-banner { position: absolute; z-index: 60; top: 74px; left: 50%; transform: translateX(-50%); min-width: 230px; padding: 7px 40px 7px 22px; pointer-events: none; text-align: center;
  background: linear-gradient(180deg, #0c1370, #03052a); border: 2px solid var(--kh-edge); border-left: 6px solid var(--kh-gold); clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 50%, calc(100% - 18px) 100%, 0 100%); animation: kh-banner .3s ease-out; }
.kh-banner b { font: 900 17px var(--kh-font); letter-spacing: .12em; text-transform: uppercase; color: #fff; text-shadow: 0 0 10px rgba(255, 190, 70, .8), 0 2px 0 #02041a; }
.kh-banner.oogie { border-left-color: #6dff7a; } .kh-banner.oogie b { text-shadow: 0 0 10px rgba(80, 255, 120, .9), 0 2px 0 #02041a; }
.kh-banner.jack { border-left-color: #ff8a1f; } .kh-banner.lsb { border-left-color: #ff7ac8; } .kh-banner.donald { border-left-color: #6fb6ff; }
.kh-banner.enemy { border-left-color: #ff5a5a; background: linear-gradient(180deg, #4a0c1a, #1a0208); }
@keyframes kh-banner { from { opacity: 0; transform: translateX(-50%) translateY(-14px) scale(.9); } }
.kh-ko { position: absolute; z-index: 60; width: 0; height: 0; pointer-events: none; }
.kh-ko i { position: absolute; left: -9px; top: -9px; width: 18px; height: 18px; border-radius: 50%; background: radial-gradient(circle, #1a1626 0 55%, transparent 72%); opacity: 0; animation: kh-puff .85s ease-out forwards; animation-delay: var(--d); }
.kh-ko.boss i { width: 28px; height: 28px; left: -14px; top: -14px; }
@keyframes kh-puff { 0% { opacity: .95; transform: translate(0, 0) scale(.4); } 100% { opacity: 0; transform: translate(var(--dx), var(--dy)) scale(2.2); } }
.kh-ko b { position: absolute; left: -16px; top: -22px; font: 400 32px/1 var(--kh-font); color: #ff3b5e; text-shadow: 0 0 12px rgba(255, 50, 90, .95); opacity: 0; animation: kh-heartup 1.3s ease-out .2s forwards; }
@keyframes kh-heartup { 0% { opacity: 0; transform: translateY(0) scale(.5); } 25% { opacity: 1; } 100% { opacity: 0; transform: translateY(-86px) scale(1.25); } }
.kh-sprite { position: absolute; pointer-events: none; image-rendering: pixelated; background-repeat: no-repeat; filter: drop-shadow(0 4px 6px rgba(0, 0, 0, .6)); }
.kh-present, .kh-duck { position: absolute; z-index: 61; font-size: 48px; line-height: 1; margin: -48px 0 0 -24px; pointer-events: none; transition: left .075s linear; filter: drop-shadow(0 6px 5px rgba(0, 0, 0, .55)); }
.kh-present { animation: kh-drop .5s ease-out; } @keyframes kh-drop { from { transform: translateY(-80px) rotate(-30deg); opacity: 0; } }
.kh-duck { font-size: 64px; margin: -64px 0 0 -32px; animation: kh-waddle .16s ease-in-out infinite alternate; text-shadow: 0 0 16px rgba(255, 60, 60, .9); }
.kh-duck.flip { transform: scaleX(-1); } @keyframes kh-waddle { to { translate: 0 -8px; rotate: 6deg; } }
.kh-sack { position: absolute; z-index: 61; width: 0; height: 0; pointer-events: none; transition: opacity .25s; }
.kh-sack span { position: absolute; left: -58px; top: -118px; font-size: 118px; line-height: 1; transform: scale(var(--k, 1)); transform-origin: 50% 100%; filter: drop-shadow(0 8px 8px rgba(0, 0, 0, .6)) hue-rotate(-20deg); animation: kh-sackwobble .32s ease-in-out infinite alternate; }
.kh-sack.out { opacity: 0; } @keyframes kh-sackwobble { from { rotate: -6deg; } to { rotate: 6deg; } }
.kh-jackbox { position: absolute; z-index: 40; width: 52px; margin: -40px 0 0 -26px; pointer-events: none; filter: drop-shadow(0 4px 4px rgba(0, 0, 0, .6)); animation: kh-drop .4s ease-out; }
.kh-jackbox.pop { animation: kh-pop .5s ease-out forwards; } @keyframes kh-pop { 30% { transform: scale(1.8, 1.3) translateY(-20px); } 100% { transform: scale(2.4); opacity: 0; } }
.kh-pick { position: absolute; inset: 0; z-index: 90; background: rgba(2, 3, 20, .5); cursor: pointer; }
.kh-pick-label { position: absolute; top: 74px; left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; padding: 6px 36px 6px 22px; pointer-events: none;
  background: linear-gradient(180deg, #ffab48, #c8500b); clip-path: polygon(0 0, calc(100% - 18px) 0, 100% 50%, calc(100% - 18px) 100%, 0 100%); }
.kh-pick-label b { font: 900 16px var(--kh-font); letter-spacing: .12em; text-transform: uppercase; } .kh-pick-label small { font: 700 10px var(--kh-font); letter-spacing: .16em; text-transform: uppercase; }
.kh-pick-target { position: absolute; background: rgba(255, 190, 70, .12); border: 2px dashed #ffd54a; border-radius: 12px; cursor: pointer; color: #fff; animation: kh-pulse 1s ease-in-out infinite; }
.kh-pick-target:hover { background: rgba(255, 190, 70, .35); border-style: solid; }
