.depth-door.elite,.depth-door.boss{border-color:#7a3a44}.depth-door.elite em,.depth-door.boss em{color:#fff;background:linear-gradient(180deg,#ff7a86,#c63b4c)}
.depth-door-foes{display:flex;align-items:center;gap:2px}.depth-door-foes img{width:22px;height:22px;object-fit:contain;border-radius:3px;background:#0006}.depth-door-foes i{margin-left:4px;color:var(--rz-warn,#f0c85a);font-size:8px;font-style:normal;font-weight:900}
.depth-door-power{color:#b9edb4;font-size:8px;font-weight:900;line-height:1.35}.depth-door-power.under{color:#ffb6a4}
.depth-door-mutations{display:grid;gap:4px;align-self:stretch;padding:7px;border:1px solid #8b91aa;border-radius:5px;background:#242b3b;color:#d7dfed;font-size:9px;line-height:1.35}
.depth-door-mutations>b{color:#ffe08a;font-size:8px;letter-spacing:.06em}
.depth-door-mutations>span>strong{font-size:inherit;line-height:inherit}
.depth-pack{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:0 0 10px;padding:10px 12px;border:1px solid #384448;border-radius:4px;color:var(--rz-text,#f5f6ed);background:linear-gradient(180deg,var(--rz-card,#465255),var(--rz-card2,#354145));box-shadow:0 5px 12px #0008}
.depth-gumballs{display:flex;align-items:center;gap:5px}.depth-gumballs img{width:30px;height:30px;object-fit:contain}.depth-gumballs b{font-size:18px}.depth-gumballs small{color:var(--rz-muted,#b7c4c0);font-size:8px;font-weight:800}
.depth-pockets{display:flex;gap:6px;flex:1;justify-content:flex-end}
.depth-pocket{display:flex;flex-direction:column;align-items:center;justify-content:center;width:60px;height:60px;padding:4px;border:1px solid #56666a;border-radius:6px;color:var(--rz-text,#f5f6ed);background:var(--rz-card2,#354145);cursor:pointer}
.depth-pocket img{width:30px;height:30px;object-fit:contain}.depth-pocket small{max-width:100%;overflow:hidden;font-size:7px;font-weight:800;white-space:nowrap;text-overflow:ellipsis}
.depth-pocket.empty{border-style:dashed;opacity:.45;cursor:default}.depth-pocket:not(.empty):hover{border-color:var(--rz-accent,#8ee65e)}
.depth-armed{display:flex;align-items:center;gap:4px;width:100%}.depth-armed small{color:var(--rz-warn,#f0c85a);font-size:8px;font-weight:900;letter-spacing:1px;text-transform:uppercase}.depth-armed img{width:20px;height:20px;object-fit:contain}
.depth-map{display:flex;align-items:center;gap:4px;padding:6px 2px;overflow-x:auto}
.depth-step{display:flex;flex-direction:column;gap:5px;flex:none}
.depth-node{display:grid;place-items:center;width:34px;height:34px;border:1px solid #56666a;border-radius:50%;color:var(--rz-text,#f5f6ed);background:var(--rz-card2,#354145);font-size:15px}
.depth-node.hidden{color:var(--rz-muted,#b7c4c0);font-weight:900;font-size:13px}
.depth-node.skipped{opacity:.28}.depth-node.taken{border-color:#7fc497;background:#365648}
