.depth-elevator-head small{color:#8ee65e;font-size:9px;font-weight:900;letter-spacing:1.5px}.depth-elevator-head h2{margin:2px 0 4px;font-size:22px}.depth-elevator-head p{margin:0;color:#cfd8d6;font-size:12px;font-style:italic}
.depth-elevator-bar{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:12px 0 8px}
.depth-elevator-pockets{display:flex;gap:4px}.depth-elevator-pockets img,.depth-elevator-pockets i{width:26px;height:26px;border:1px solid #56666a;border-radius:4px;object-fit:contain}.depth-elevator-pockets i{border-style:dashed;opacity:.4}
