.depth-report-cards{display:flex;flex-wrap:wrap;gap:4px;margin-top:10px}.depth-report-cards span{position:relative}.depth-report-cards img{width:34px;height:34px;object-fit:contain}.depth-report-cards i{position:absolute;right:-2px;bottom:-2px;padding:0 3px;border-radius:3px;background:#000;font-size:9px;font-style:normal}
.depth-report-bonus{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:12px;padding:8px;border-radius:6px;background:#ffd34d18}.depth-report-bonus small{width:100%;color:#ffd34d;font-size:9px;font-weight:900;letter-spacing:1.5px}
