/* DEPTHS-OVERHAUL-END */

/* TEAM-PICKER-BEGIN: squad strip, readout, compact roster */
.tp{display:flex;flex-direction:column;gap:10px;color:#eef3ef}
.tp-hp{display:block;height:4px;margin-top:2px;background:#0b1214;border-radius:3px;overflow:hidden}
