.tp-row.down{opacity:.55}
.tp-row img{width:44px;height:44px;object-fit:contain}
.tp-row-main{display:flex;flex-direction:column;gap:2px;min-width:0}.tp-row-main b{font-size:13px}
.tp-row-main small{color:#a9b9b6;font-size:10px;line-height:1.3}
