.tp-tags{display:flex;flex-wrap:wrap;gap:3px}.tp-tags i{padding:1px 5px;border:1px solid var(--tag,#cfd8d6);border-radius:3px;color:var(--tag,#cfd8d6);font-size:8px;font-style:normal;font-weight:800;letter-spacing:.3px}
