/* roster rows: colour by role, glow by rarity, a power bar to compare at a glance */
.tp-row{position:relative;overflow:hidden;border-left:4px solid var(--role,#56666a);transition:transform .12s,border-color .12s,box-shadow .12s}
.tp-row:hover{transform:translateX(3px)}
.tp-row:after{content:"";position:absolute;left:0;bottom:0;height:3px;width:var(--pw,0%);background:linear-gradient(90deg,var(--role,#56666a),transparent);opacity:.8}
