/* TEAM-PICKER-END */

/* SETTINGS-BEGIN: plain rows, real contrast, readable sizes */
#modalBox.st-modal{width:min(96vw,640px);max-height:92dvh;overflow-y:auto;padding:14px 16px 18px;border:1px solid #4a585c;border-radius:12px;background:#182023;color:#eef3ef;box-shadow:0 14px 40px #000a}
