/* EVENT-BANNER-BEGIN: one clean card for every event */
.eb{position:relative;display:flex;align-items:stretch;width:100%;min-height:128px;margin:0 0 12px;padding:0;overflow:hidden;text-align:left;color:#f4f7f5;border:1px solid #3a474b;border-left:5px solid var(--eb);border-radius:10px;background:linear-gradient(100deg,color-mix(in srgb,var(--eb) 22%,#161e21) 0,#161e21 58%);font:inherit;cursor:pointer;transition:transform .14s,border-color .14s,box-shadow .14s}
.eb:hover{transform:translateY(-2px);box-shadow:0 8px 20px #0009;border-color:var(--eb)}
.eb:focus-visible{outline:3px solid #ffe27a;outline-offset:2px}
.eb-body{position:relative;z-index:2;display:flex;flex-direction:column;justify-content:center;gap:4px;width:62%;min-width:0;padding:14px 4px 14px 16px}
