/* Plush story: goofy manga pages */
.plv{position:fixed;inset:0;z-index:9000;overflow:hidden;background:#000;cursor:pointer;user-select:none;font-family:"Trebuchet MS","Comic Sans MS",sans-serif;border:8px solid #000;animation:plvIn .3s ease}
.plv.closing{animation:plvOut .3s ease forwards}
@keyframes plvIn{from{opacity:0}}@keyframes plvOut{to{opacity:0}}
.plv-bg{position:absolute;inset:0;background:#fff center/cover no-repeat;filter:contrast(1.15) saturate(1.2)}
.plv-tone{position:absolute;inset:0;pointer-events:none;background:radial-gradient(#0000002e 1.2px,transparent 1.6px) 0 0/7px 7px;mix-blend-mode:multiply}
.plv-lines{position:absolute;inset:0;pointer-events:none;opacity:0;transition:opacity .15s;background:repeating-conic-gradient(from 0deg at 50% 46%,#000 0 .6deg,transparent .6deg 4deg);-webkit-mask:radial-gradient(circle at 50% 46%,transparent 24%,#000 78%);mask:radial-gradient(circle at 50% 46%,transparent 24%,#000 78%)}
.plv.speed .plv-lines{opacity:.5;animation:plvLines .12s steps(2) infinite}
@keyframes plvLines{50%{transform:scale(1.03) rotate(.6deg)}}
.plv.wipe .plv-ink{animation:plvWipe .5s ease-out}
.plv-ink{position:absolute;inset:0;background:#000;transform:translateX(110%);pointer-events:none;z-index:9}
@keyframes plvWipe{0%{transform:translateX(-110%) skewX(-12deg)}50%{transform:translateX(0) skewX(-12deg)}100%{transform:translateX(110%) skewX(-12deg)}}
.plv-stage{position:absolute;inset:0}
.plv-cast{position:absolute;bottom:0;height:min(50vh,420px);display:flex;align-items:flex-end;justify-content:center;opacity:0;transform:translateX(-50%);transition:left .35s,filter .2s}
.plv-cast img{max-height:100%;max-width:28vw;object-fit:contain;transform-origin:50% 100%;filter:drop-shadow(4px 0 0 #000) drop-shadow(-4px 0 0 #000) drop-shadow(0 4px 0 #000) drop-shadow(0 -4px 0 #000)}
.plv-cast.in{opacity:1}
.plv-cast.from-l.in{animation:plvInL .5s cubic-bezier(.2,1.5,.4,1)}
.plv-cast.from-r.in{animation:plvInR .5s cubic-bezier(.2,1.5,.4,1)}
@keyframes plvInL{from{opacity:0;transform:translateX(-170%) skewX(14deg)}60%{transform:translateX(-42%) skewX(-5deg)}to{transform:translateX(-50%)}}
@keyframes plvInR{from{opacity:0;transform:translateX(70%) skewX(-14deg)}60%{transform:translateX(-58%) skewX(5deg)}to{transform:translateX(-50%)}}
