.plv-cast.drop.in{animation:plvDrop .8s cubic-bezier(.3,0,.5,1)}
@keyframes plvDrop{0%{opacity:1;transform:translateX(-50%) translateY(-130%) scale(.7,1.3)}55%{transform:translateX(-50%) translateY(0) scale(1.25,.7)}72%{transform:translateX(-50%) translateY(-9%) scale(.92,1.1)}100%{transform:translateX(-50%)}}
/* talking: a little bob. reactions: loud squash and stretch */
.plv-cast.talk img{animation:plvTalk .5s ease-in-out infinite alternate}
@keyframes plvTalk{to{transform:translateY(-6px) scale(1.02,.98)}}
.plv-cast.a-hop img{animation:plvHop .5s ease}.plv-cast.a-bounce img{animation:plvBounce .8s ease}
.plv-cast.a-shake img{animation:plvShake .5s}.plv-cast.a-sway img{animation:plvSway 1.2s ease-in-out}
