@keyframes plvShake{12%{transform:translateX(-11px) rotate(-3deg)}25%{transform:translateX(11px) rotate(3deg)}37%{transform:translateX(-9px) rotate(-2deg)}50%{transform:translateX(9px) rotate(2deg)}75%{transform:translateX(-4px)}}
