/* reaction marks drawn like manga */
.plv-mark{position:absolute;top:3%;right:4%;min-width:34px;height:34px;display:grid;place-items:center;padding:0 7px;font:900 22px/1 "Trebuchet MS",sans-serif;color:#000;opacity:0;transform:scale(0) rotate(-12deg)}
