.plv-sfx{position:absolute;inset:0;pointer-events:none;z-index:6}
.plv-sfxt{position:absolute;font:900 clamp(36px,9vw,84px)/1 Impact,"Arial Black",sans-serif;font-style:italic;color:#fff;-webkit-text-stroke:3px #000;paint-order:stroke fill;text-shadow:5px 5px 0 #000;letter-spacing:2px;transform:rotate(var(--r));animation:plvSfx 1.4s ease-out forwards}
@keyframes plvSfx{0%{opacity:0;transform:rotate(var(--r)) scale(2.6)}12%{opacity:1;transform:rotate(var(--r)) scale(.9)}22%{transform:rotate(var(--r)) scale(1.08)}80%{opacity:1}100%{opacity:0;transform:rotate(var(--r)) scale(1)}}
/* speech panel */
.plv-lower{position:absolute;z-index:5;left:50%;bottom:14px;transform:translateX(-50%);width:min(860px,calc(100% - 28px));min-height:104px;padding:12px 20px 14px;border:4px solid #000;border-radius:18px;background:#fff;color:#000;box-shadow:6px 6px 0 #000;transition:opacity .2s}
.plv-lower:before{content:"";position:absolute;left:46px;top:-24px;width:26px;height:24px;background:#fff;clip-path:polygon(0 100%,100% 100%,30% 0);filter:drop-shadow(0 -3px 0 #000)}
.plv-lower.hide{opacity:0}
.plv-name{position:absolute;left:18px;top:-20px;padding:2px 14px;border:3px solid #000;background:#ffe14a;font:900 15px/1.4 "Trebuchet MS",sans-serif;transform:rotate(-2deg);box-shadow:3px 3px 0 #000}
.plv-name:empty{display:none}
.plv-text{margin:4px 0 0;min-height:52px;font-size:19px;line-height:1.4;font-weight:700}
.plv-lower.narrate{background:#fff6c4;border-radius:3px;border-width:3px}
.plv-lower.narrate:before{display:none}
.plv-lower.narrate .plv-text{font-style:italic;font-weight:600}
.plv-lower.shout{animation:plvShout .12s steps(2) infinite;border-radius:6px;background:#fff;clip-path:polygon(0 6%,3% 0,8% 5%,14% 0,20% 5%,27% 0,33% 5%,40% 0,47% 5%,54% 0,61% 5%,68% 0,75% 5%,82% 0,89% 5%,95% 0,100% 6%,99% 50%,100% 94%,95% 100%,88% 95%,80% 100%,72% 95%,64% 100%,55% 95%,46% 100%,38% 95%,30% 100%,22% 95%,14% 100%,7% 95%,2% 100%,0 94%,1% 50%)}
.plv-lower.shout .plv-text{font-size:21px;font-weight:900}
@keyframes plvShout{50%{transform:translateX(-50%) translate(2px,-1px)}}
.plv-next{position:absolute;right:20px;bottom:8px;width:0;height:0;border:8px solid transparent;border-top:12px solid #000;opacity:0}
.plv-lower.done .plv-next{opacity:1;animation:plvNext .6s steps(2) infinite}
@keyframes plvNext{50%{transform:translateY(4px)}}
.plv-skip{position:absolute;top:12px;right:12px;z-index:8;padding:5px 12px;border:3px solid #000;border-radius:6px;color:#000;background:#fff;box-shadow:3px 3px 0 #000;font:900 13px "Trebuchet MS",sans-serif;cursor:pointer}
.plv-slate{position:absolute;left:-5%;right:-5%;top:34%;z-index:8;padding:14px 10px;text-align:center;color:#fff;background:#000;border-block:5px solid #ffe14a;font:900 clamp(24px,6vw,44px) Impact,"Arial Black",sans-serif;font-style:italic;letter-spacing:3px;transform:rotate(-3deg) translateX(-120%);pointer-events:none}
.plv-slate.show{animation:plvSlate 1.9s cubic-bezier(.2,1.2,.3,1) forwards}
@keyframes plvSlate{0%{transform:rotate(-3deg) translateX(-120%)}18%{transform:rotate(-3deg) translateX(0)}82%{transform:rotate(-3deg) translateX(0)}100%{transform:rotate(-3deg) translateX(120%)}}
.plv.flash:after{content:"";position:absolute;inset:0;z-index:10;background:#fff;animation:plvFlash .45s ease-out forwards;pointer-events:none}
@keyframes plvFlash{to{opacity:0}}
.plv.shake .plv-stage,.plv.shake .plv-bg,.plv.shake .plv-lines{animation:plvQuake .5s}
@keyframes plvQuake{15%{transform:translate(-14px,8px)}30%{transform:translate(12px,-9px)}45%{transform:translate(-10px,6px)}60%{transform:translate(8px,-5px)}80%{transform:translate(-4px,3px)}}
@media(max-width:600px){.plv-text{font-size:16px}.plv{border-width:5px}}

/* Vee's score set: keep the run and the next target in front of the prize list. */
.pl-banner{border-color:#080d1b;background:linear-gradient(112deg,#232039,#31305a 65%,#181b30);box-shadow:inset 0 2px #ffffff38,0 4px #080d1b,0 0 0 2px #ffe09a8c}
.pl-banner:before{background:linear-gradient(125deg,transparent 58%,#ffe09a20 59% 60%,transparent 61%),repeating-linear-gradient(0deg,#fff1 0 1px,transparent 1px 5px);opacity:.7}
.pl-banner-body small,.pl-top-title small,.pl-hero-copy small,.pl-best small,.pl-live small{color:#80f5eb}
.pl-banner-foot em{color:#241b34;background:#ffe09a}
.pl-banner-foot i,.pl-banner-sub{color:#dedcf0}
.pl-top-title b{color:#fff5d9}
.pl-back{border-color:#101321;color:#eeeaff;background:#33324d;box-shadow:inset 0 1px #fff4,0 3px #0b0d19}
.pl-page{gap:9px}
.pl-hero{min-height:176px;border-color:#101321;background-position:center;box-shadow:inset 0 2px #fff3,0 4px #0b0d19}
