.pl-hero-copy p{max-width:340px;color:#f0eefa}
.pl-reset{color:#c9c7df}
.pl-mode{border-color:#101321;color:#d8d4e9;background:#242238;box-shadow:inset 0 1px #fff2,0 3px #0b0d19}
.pl-mode b{color:#fff5d9}.pl-mode em{color:#211d31;background:#ffe09a}.pl-mode small{color:#cfcadd}
.pl-mode.on{border-color:#80f5eb;background:#293a4b;box-shadow:inset 0 1px #fff4,0 0 0 2px #80f5eb55,0 3px #0b0d19}
.pl-mode[data-mode=hard].on{border-color:#ff987a;background:#513344;box-shadow:inset 0 1px #fff4,0 0 0 2px #ff987a55,0 3px #0b0d19}
.pl-start{border-color:#101321;background:#242238}
.pl-best b{color:#fff5d9}.pl-best span{color:#c9c7df}
.pl-go{border-color:#161629;color:#231c30;background:linear-gradient(180deg,#fff0b7,#ffcb71);box-shadow:inset 0 2px #fff9,0 4px #0b0d19}
.pl-target{padding:2px 3px 5px;color:#d8d4e9;font-size:9px;font-weight:900}
.pl-target span{display:block;margin-bottom:5px}.pl-target b{color:#fff1bc}
.pl-target-track,.pl-live-track{height:7px;overflow:hidden;border-radius:99px;background:#111426}
.pl-target-track i,.pl-live-track i{display:block;width:0;height:100%;border-radius:inherit;background:linear-gradient(90deg,#72e4e0,#ffda83);transition:width .25s}
.pl-details{border:2px solid #111426;border-radius:11px;background:#211f34;padding:0 10px 10px}
.pl-details summary{padding:11px 3px;color:#fff5d9;font:1000 13px Georgia,serif;cursor:pointer;list-style:none}
.pl-details summary::-webkit-details-marker{display:none}
