.pl-details[open] summary:after{content:'−'}
.pl-details summary span{display:block;margin-top:2px;color:#bdb9d3;font:800 9px sans-serif}
.pl-details .pl-h{margin:12px 0 7px}.pl-details .pl-note{margin:6px 0}
.pl-h{color:#fff5d9}.pl-h small{color:#bdb9d3}
.pl-note{color:#d8d4e9}.pl-shard,.pl-chip{background:#111426}
.pl-m,.pl-tier,.pl-board li,.pl-claim{border-color:#111426;background:#29263e}
