.pl-m em,.pl-board li b{color:#80f5eb}.pl-board li.you{background:#2b4754;box-shadow:inset 0 0 0 2px #80f5eb}
.pl-replay{border-color:#111426;color:#c9c7df;background:#242238}
.pl-live{border-color:#111426;background:#19182bea;box-shadow:0 0 0 2px #80f5eb88}
