.pl-live-track{height:4px}
.pl-result{background:#080916e9}.pl-result-card{border-color:#80f5eb;background:linear-gradient(160deg,#303050,#181927)}
.pl-result-card small,.pl-result-ms b{color:#80f5eb}.pl-result-card h2{color:#fff5d9}.pl-result-card p{color:#c9c7df}.pl-result-card p.new{color:#ffe09a}
