/* Prism Spin */
.prism-card{--tier:#c3ced6;border:2px solid var(--tier)!important;background:radial-gradient(120% 90% at 50% 0,color-mix(in srgb,var(--tier) 16%,#1b1827),#14131d)!important;box-shadow:0 0 14px color-mix(in srgb,var(--tier) 35%,transparent)}
.prism-head{display:flex;align-items:center;justify-content:space-between;gap:8px}
.prism-head>b{color:#f5ecff;font-size:15px}
.prism-badge{display:inline-flex;align-items:baseline;gap:5px;padding:3px 9px;border-radius:99px;border:1px solid var(--tier);color:var(--tier);background:color-mix(in srgb,var(--tier) 14%,#0d0c14);font-size:10px;font-weight:1000;letter-spacing:.8px;text-transform:uppercase}
.prism-badge i{font-style:normal;font-size:8px;opacity:.8;letter-spacing:.2px}
.prism-tiles{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px}
.prism-tile{position:relative;display:grid;justify-items:center;gap:3px;padding:12px 8px 10px;border:2px solid color-mix(in srgb,var(--tier) 55%,#000);border-radius:12px;background:linear-gradient(160deg,color-mix(in srgb,var(--tier) 18%,#2a2438),#1a1826);text-align:center;min-width:0;overflow:hidden}
.prism-label{color:#9d93b3;font-size:7px;font-weight:1000;letter-spacing:1.2px}
.prism-tile .prism-icon{font-size:34px;line-height:1.1;filter:drop-shadow(0 0 8px var(--tier))}
.prism-tile b{color:#f6eeff;font-size:14px}
.prism-tile small{color:#b4bdb8;font-size:9px;font-weight:700;line-height:1.3}
.prism-tile em{position:absolute;top:5px;right:5px;padding:1px 5px;border-radius:5px;background:linear-gradient(90deg,#ff6b8b,#ffb84d,#9be564,#4dc3ff,#b98cff);color:#1b1020;font-size:6px;font-style:normal;font-weight:1000;letter-spacing:.6px}
.prism-pending{position:relative;margin-top:10px;padding:10px;border:2px dashed var(--tier);border-radius:14px;background:color-mix(in srgb,var(--tier) 8%,transparent)}
.prism-pending .prism-tile{border-color:var(--tier)}
.prism-pending.spinning .prism-tile{animation:prismShake .14s linear infinite;border-color:#fff}
.prism-pending.spinning .prism-tile small,.prism-pending.spinning .prism-tile b,.prism-pending.spinning .prism-badge{visibility:hidden}
.prism-pending.spinning{border-style:solid;animation:prismPulse .5s ease-in-out infinite alternate}
.prism-pending.landed{border-style:solid;animation:prismLand .55s cubic-bezier(.2,1.6,.4,1)}
.prism-pending.landed .prism-tile{animation:prismPop .5s cubic-bezier(.2,1.8,.4,1) both}
.prism-pending.landed .prism-tile:nth-child(2){animation-delay:.1s}
.prism-pending.tier-3{box-shadow:0 0 18px var(--tier)}
.prism-pending.tier-4{border-color:transparent;background:linear-gradient(#1a1624,#1a1624) padding-box,linear-gradient(120deg,#ff6b8b,#ffb84d,#9be564,#4dc3ff,#b98cff,#ff6b8b) border-box;background-size:100% 100%,300% 100%;animation:prismLand .55s cubic-bezier(.2,1.6,.4,1),prismRainbow 2.5s linear infinite;box-shadow:0 0 24px #ffc94d99}
.prism-row{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-top:8px}
.prism-row.hidden{visibility:hidden}
.prism-keep{color:#152017!important;background:linear-gradient(180deg,#d8fa92,#78cf69)!important}
.prism-skip{color:#e8e4f4!important;background:linear-gradient(180deg,#5b5470,#3a3550)!important}
.prism-spin{display:flex!important;flex-direction:column;align-items:center;gap:3px;width:100%;margin-top:10px;min-height:50px;font-size:15px;color:#fff!important;background:linear-gradient(90deg,#ff6b8b,#ffb84d,#9be564,#4dc3ff,#b98cff,#ff6b8b)!important;background-size:200% 100%!important;animation:prismRainbow 4s linear infinite;text-shadow:0 1px 3px #000a}
.prism-spin:active{transform:translateY(2px)}
.prism-spin:disabled{animation:none;filter:grayscale(.75) brightness(.7)}
.prism-costs{display:flex;gap:10px;font-size:10px;text-shadow:none}
.prism-cost{padding:1px 7px;border-radius:99px;background:#0009;color:#fff}
.prism-cost.short{color:#ff9a9a}
.prism-note{margin-top:8px;color:#8f8aa4;font-size:9px;text-align:center;line-height:1.5}
.prism-burst{position:absolute;left:50%;top:50%;width:0;height:0;pointer-events:none}
.prism-burst i{position:absolute;width:7px;height:7px;border-radius:2px;opacity:0;animation:prismSpark 1s ease-out forwards}
@keyframes prismShake{0%,100%{transform:translateY(0) rotate(0)}25%{transform:translateY(-3px) rotate(-1.5deg)}75%{transform:translateY(2px) rotate(1.5deg)}}
@keyframes prismPulse{from{box-shadow:0 0 6px #fff4}to{box-shadow:0 0 22px #fffa}}
@keyframes prismLand{0%{transform:scale(.94)}100%{transform:scale(1)}}
@keyframes prismPop{0%{transform:scale(.6) rotate(-6deg);opacity:0}100%{transform:scale(1) rotate(0);opacity:1}}
@keyframes prismRainbow{to{background-position:200% 0}}
@keyframes prismSpark{0%{transform:translate(0,0) rotate(0) scale(1);opacity:1}100%{transform:translate(var(--dx),var(--dy)) rotate(260deg) scale(.2);opacity:0}}

/* Auto indicator: lit gold when on, dimmed with a slash when off */
#btnAuto{width:auto!important;min-width:38px;padding:0 6px}
#btnAuto:not(.on){opacity:.65;filter:grayscale(.8)}
#btnAuto.on{box-shadow:0 0 0 2px #fff6,0 0 10px #ffd34e!important}

/* Waxwell: the wick on his head is always readable. Lit = steady flame and a warm glow;
   Tired II = snuffed, a grey smoke curl and a dimmer body. Ignite's runner flame (above) takes over while dashing. */
.unit.waxwell-lit:not(.waxwell-runner) .body{filter:drop-shadow(0 0 7px #ff8a3877) drop-shadow(0 4px 4px #35160f)}
.unit.waxwell-lit:not(.waxwell-runner) .body:after{content:"";position:absolute;z-index:5;left:50%;bottom:86%;width:12px;height:21px;margin-left:-6px;border-radius:65% 35% 60% 40%;background:linear-gradient(#fffbd0 0 18%,#ffd55d 34%,#ff792e 68%,#bc271f 90%,transparent);filter:drop-shadow(0 0 5px #ff8a38);transform-origin:50% 100%;animation:waxHeadFlame .5s ease-in-out infinite alternate;pointer-events:none}
.unit.waxwell-tired:not(.waxwell-runner) .body{filter:saturate(.72) brightness(.9) drop-shadow(0 4px 4px #35160f)}
.unit.waxwell-tired:not(.waxwell-runner) .body:after{content:"";position:absolute;z-index:5;left:50%;bottom:86%;width:6px;height:16px;margin-left:-3px;border-radius:50%;background:linear-gradient(#cfd3dccc,transparent);filter:blur(1.5px);transform-origin:50% 100%;animation:waxSmoke 1.6s ease-out infinite;pointer-events:none}
@keyframes waxSmoke{from{opacity:.75;transform:translate(0,0) scale(.7)}to{opacity:0;transform:translate(5px,-18px) scale(1.5)}}
.kh-shop .kh-all { margin-left: 0; }

/* Shared status language: one brief application stamp, then a cheap attached
   cue while hard control lasts. No particles or per-frame JS are needed. */
.fx-stat-burst{position:absolute;z-index:9;pointer-events:none;transform:translate(-50%,-50%);--stat-ink:#f1ce70}
.fx-stat-burst.buff{--stat-ink:#8fe0b3}
.fx-stat-burst.debuff{--stat-ink:#f2909c}
.fx-stat-burst.control{--stat-ink:#f4ce72}
.fx-stat-burst i{position:absolute;inset:12%;border:3px solid var(--stat-ink);background:color-mix(in srgb,var(--stat-ink) 16%,transparent);clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%);box-shadow:inset 0 0 0 2px #0f1826;animation:statStamp .64s cubic-bezier(.2,.8,.3,1) both}
.fx-stat-burst b{position:absolute;left:35%;top:32%;width:30%;height:36%;background:#fff7dc;filter:drop-shadow(2px 2px 0 #182028);animation:statGlyph .58s ease-out both}
.fx-stat-burst.buff b{clip-path:polygon(50% 0,100% 48%,69% 48%,69% 100%,31% 100%,31% 48%,0 48%)}
.fx-stat-burst.debuff b{clip-path:polygon(31% 0,69% 0,69% 52%,100% 52%,50% 100%,0 52%,31% 52%)}
.fx-stat-burst.control b{clip-path:polygon(58% 0,18% 52%,47% 52%,34% 100%,85% 39%,57% 39%)}
@keyframes statStamp{0%{opacity:0;transform:rotate(-24deg) scale(.3)}32%{opacity:1;transform:rotate(0) scale(1)}100%{opacity:0;transform:rotate(10deg) scale(1.28)}}
@keyframes statGlyph{0%{opacity:0;transform:translateY(8px) scale(.5)}30%{opacity:1;transform:translateY(0) scale(1.12)}100%{opacity:0;transform:translateY(-13px) scale(.8)}}

.unit .status-ambient{position:absolute;inset:0;z-index:7;pointer-events:none}
.unit .status-ambient::before,.unit .status-ambient::after{position:absolute;left:50%;pointer-events:none}
.unit .status-ambient::before,.unit .status-ambient::after{content:''}
.unit .status-ambient.stun::before{bottom:78%;width:38px;height:30px;margin-left:-19px;background:linear-gradient(120deg,#fff2a6,#f5ae43);clip-path:polygon(28% 0,0 56%,36% 56%,21% 100%,100% 36%,61% 36%,76% 0);filter:drop-shadow(0 0 6px #ffdc69);animation:statusDizzy 1.15s ease-in-out infinite}
.unit .status-ambient.stun::after{bottom:76%;width:60px;height:25px;margin-left:-30px;border:2px solid #ffe57d;clip-path:polygon(0 50%,18% 0,50% 26%,82% 0,100% 50%,82% 100%,50% 74%,18% 100%);box-shadow:0 0 7px #f9c153;animation:statusHover 1.15s ease-in-out infinite}
.unit .status-ambient.freeze::before{bottom:79%;width:32px;height:34px;margin-left:-16px;background:linear-gradient(135deg,#fff,#9ddff7 58%,#5799ca);clip-path:polygon(50% 0,73% 33%,100% 50%,68% 67%,50% 100%,31% 67%,0 50%,31% 32%);filter:drop-shadow(0 0 6px #9feaff);animation:statusHover 1.6s ease-in-out infinite}
.unit .status-ambient.freeze::after{inset:12% 5% 4%;left:5%;border:2px solid #a9ecff9c;clip-path:polygon(15% 0,70% 4%,100% 30%,91% 81%,58% 100%,0 84%,6% 28%);animation:statusFrost 2s ease-in-out infinite alternate}
.unit .status-ambient.sleep::before{bottom:81%;width:26px;height:26px;margin-left:-13px;border-radius:50%;box-shadow:inset -9px 2px #d8c3ff,0 0 8px #a389d8;animation:statusDrift 2.2s ease-in-out infinite}
.unit .status-ambient.petrify::before{bottom:78%;width:32px;height:29px;margin-left:-16px;background:linear-gradient(145deg,#f3e5cb,#8c8178);clip-path:polygon(48% 0,90% 15%,100% 70%,65% 100%,18% 83%,0 37%);filter:drop-shadow(2px 2px 0 #4c4037);animation:statusHover 2.5s ease-in-out infinite}
.unit .status-ambient.silence::before{bottom:79%;width:30px;height:29px;margin-left:-15px;background:linear-gradient(45deg,transparent 43%,#d8b4ff 44% 57%,transparent 58%),linear-gradient(-45deg,transparent 43%,#d8b4ff 44% 57%,transparent 58%);filter:drop-shadow(0 0 5px #a668d0);animation:statusHover 1.9s ease-in-out infinite}
.unit .status-ambient.root::before{bottom:4%;width:55px;height:28px;margin-left:-27px;background:#bddb8e;clip-path:polygon(0 76%,24% 46%,37% 67%,48% 0,56% 65%,74% 39%,100% 74%,76% 66%,55% 100%,37% 82%,21% 100%);filter:drop-shadow(0 0 5px #649a46);animation:statusRoot 1.6s ease-in-out infinite}
.unit .status-ambient.fear::before{bottom:78%;width:31px;height:32px;margin-left:-15px;background:linear-gradient(#ffc6c0,#ee6671);clip-path:polygon(50% 0,80% 14%,72% 69%,48% 79%,25% 68%,20% 14%);filter:drop-shadow(0 0 5px #c44b5a);animation:statusDizzy .9s ease-in-out infinite}
.unit .status-ambient.fear::after{bottom:76%;width:8px;height:8px;margin-left:-4px;background:#ffd8c6;clip-path:polygon(50% 0,100% 50%,50% 100%,0 50%);animation:statusDizzy .9s ease-in-out infinite}
@keyframes statusDizzy{0%,100%{transform:translateY(0) rotate(-8deg)}50%{transform:translateY(-3px) rotate(8deg)}}
@keyframes statusOrbit{to{transform:rotate(360deg)}}
@keyframes statusHover{0%,100%{transform:translateY(0);opacity:.75}50%{transform:translateY(-4px);opacity:1}}
@keyframes statusFrost{from{opacity:.3;transform:scale(.96)}to{opacity:.7;transform:scale(1.03)}}
@keyframes statusDrift{0%,100%{opacity:.35;transform:translate(-4px,2px)}50%{opacity:1;transform:translate(4px,-7px)}}
@keyframes statusRoot{0%,100%{opacity:.55;transform:scaleX(.85)}50%{opacity:1;transform:scaleX(1.08)}}
html.graphics-low .unit .status-ambient::after{display:none}
html.accessibility-reduced-effects .unit .status-ambient::before,
html.accessibility-reduced-effects .unit .status-ambient::after{animation:none!important}

/* Battle props use the project's art and drawn silhouettes at every scale. */
.fx-item-token{display:block!important;width:25px!important;height:25px!important;background-position:center!important;background-size:contain!important;background-repeat:no-repeat!important;font-size:0!important}
.fx-teacup{display:block;width:24px;height:19px;border-radius:2px 2px 10px 10px;background:linear-gradient(#fff4d2 0 23%,#c9955d 25% 82%,#6e412e 100%);border:2px solid #f9e9c4;box-shadow:0 3px 2px #28170da8,0 0 7px #c9955d}
.fx-teacup::after{content:'';position:absolute;left:20px;top:3px;width:10px;height:10px;border:3px solid #f9e9c4;border-left:0;border-radius:0 65% 65% 0}
