/* Crowded-fight relief: Battle.watchFrameRate() adds .perf-lite when frames stay slow. */
#battle.perf-lite #vignette,
#battle.perf-lite .unit .shadow{display:none!important}
#battle.perf-lite #fxBack *,
#battle.perf-lite #fxFront *,
#battle.perf-lite #popLayer *,
#battle.perf-lite .unit .body,
#battle.perf-lite .unit .body img,
#battle.perf-lite .unit .nameplate,
#battle.perf-lite .unit .status-chip,
#battle.perf-lite .unit .stats,
#battle.perf-lite .unit-loadout{filter:none!important;box-shadow:none!important;text-shadow:none!important;mix-blend-mode:normal!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important}
#battle.perf-lite #popLayer .pop,
#battle.perf-lite #fxFront *,
#battle.perf-lite #fxBack *{will-change:auto!important}
#battle.perf-lite #battleHud,
#battle.perf-lite #battleHud *{backdrop-filter:none!important;-webkit-backdrop-filter:none!important;text-shadow:none!important}
#battle.perf-lite .unit.boss .body:before,
#battle.perf-lite .unit.elite .body:before,
#battle.perf-lite .unit.casting .body:before,
#battle.perf-lite .unit.hurt .body:after,
#battle.perf-lite .unit .hpmini.low,
#battle.perf-lite .unitcard.ult-ready .uc-port{animation:none!important}
/* A floating number needs one short transition, not a permanent GPU layer. */
.pop{will-change:auto}

/* Skill preview frame: a compact, flat display bezel. The arena and trait
   showcase share the same housing so switching skills does not change chrome. */
.live-preview-wrap{
  position:relative;
  min-width:0;
  padding:6px;
  border:2px solid #0b1112;
  border-bottom-width:4px;
  border-radius:3px;
  background:#44524e;
  box-shadow:inset 0 0 0 1px #82948a,0 3px 0 #101718;
}
.live-preview-wrap .skill-preview-stage,
.live-preview-wrap .trait-preview-stage{
  border:2px solid #111a1b;
  border-bottom:0;
  border-radius:1px 1px 0 0;
  box-shadow:none;
}
.live-preview-wrap .live-bar{
  min-height:42px;
  padding:6px 8px;
  border:2px solid #111a1b;
  border-top:1px solid #53625a;
  border-radius:0 0 1px 1px;
  background:#1d2929;
  box-shadow:none;
}
