  color:#17201c;
  background:#b9d28e;
  box-shadow:0 2px 0 #0c1313;
}
.live-preview-wrap .preview-btn.active{background:#e2c178}
.live-preview-wrap .preview-btn:active{transform:translateY(2px);box-shadow:none}
.live-preview-wrap .preview-btn:focus-visible,
.live-preview-wrap .trait-preview-stage:focus-visible{outline:2px solid #e2c178;outline-offset:2px}
.trait-preview-stage{
